(window.GIM_TS=window.GIM_TS||{})["Menachot.1"]={"from":24,"a":[["\u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 שלשיטת ר' יוסי, ירך ימין וירך שמאל \u0003תרי גופי נינהו\u0004 \u0005[שני גופים הם\u0006 נחשבים\u0005],\u0006 ואם חישב באחת מהן לא פיגל בחבירתה, שתי הלחם \u0003מי מיצטרפי\u0004 \u0005[האם\u0006 \u0003מצטרפות]\u0004 במחשבה לאכול כזית משתיהן?","השיב רב הונא: אין להוכיח מכאן לשיטת ר' יוסי, שכן \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 בענין שתי הלחם כשיטת \u0005מי היא]?\u0006 שיטת \u0003רבי היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003השוחט את הכבש\u0004 האחד מכבשי העצרת על מנת \u0003לאכול חצי זית מחלה זו\u0004 למחר, \u0003וכן\u0004 שוחט את \u0003חבירו\u0004 על מנת \u0003לאכול חצי זית מחלה זו\u0004 השניה למחר, \u0003רבי אומר: אומר אני שזה כשר,\u0004 שאין זה מצטרף.","ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 במקרה ש\u0003אמר חצי חצי\u0004 כלומר, ששחט כל כבש על מנת לאכול חצי כזית מחלה אחת למחר — אינו מצטרף וכשר, \u0003אבל\u0004 אם \u0003אמר\u0004 בכל אחד מן הכבשים: הריני שוחט כבש זה על מנת לאכול \u0003כזית משתיהן,\u0004 חצי כזית מחלה זו וחצי כזית מחלה זו — \u0003מצטרף,\u0004 כפי ששנינו בברייתא.","ושואלים: \u0003ורבי אליבא דמאן\u0004 \u0005[על פי\u0006 שיטתו \u0005של מי]\u0006 הוא שונה בברייתא לעיל: לעולם אין בו כרת עד שיפגל בשתיהן בכזית? \u0003אי אליבא דרבנן\u0004 \u0005[אם לפי שיטת חכמים]\u0006 במשנתנו, שאם חישב לאכול חלה אחת למחר נתפגלה גם חבירתה — \u0003אפילו\u0004 חישב על כזית \u0003באחת מהן נמי\u0004 \u0005[גם כן]\u0006 הרי זה פיגול! \u0003אי אליבא\u0004 \u0005[אם לפי שיטתו]\u0006 של \u0003ר' יוסי,\u0004 שאם חישב לאכול אחת למחר לא נתפגלה השניה — \u0003הדרא קושיין לדוכתיה\u0004 \u0005[חוזרת קושייתנו\u0006 על רב הונא \u0005למקומה],\u0006 שאם בשתי ירכות סבור ר' יוסי ששני גופים הן, ואין מחשבת באחת מפגלת בחבירתה, כיצד יצטרפו חצי כזית וחצי כזית משתי הלחם!","ומשיבים: \u0003לעולם\u0004 תפרש \u0003כי רבי שונה בברייתא\u0004 \u0003אליבא דרבנן\u0004 \u0005[לפי\u0006 שיטת \u0005חכמים]\u0006 של משנתנו, שדי שיחשב לאכול אחת מן החלות למחר כדי לפגל את השניה, \u0003ולא תימא\u0004 \u0005[ואל תאמר]\u0006 \"אינו פיגול \u0003עד שיפגל בשתיהן\"\u0004 בלשון נקבה, שמשמעו עד שיפגל בשתי החלות, \u0003אלא\u0004 אמור כך: לעולם אינו פיגול עד שיפגל \u0003בשניהן\u0004 כלומר, שיחשוב מחשבת חוץ לזמנו בשחיטת שני הכבשים, \u0003ו\u0004במקרה זה \u0003אפילו\u0004 חישב \u0003באחת מהן\u0004 מן החלות לאוכלה למחר — הרי זה פיגול.","\u0003ו\u0004דבר זה בא \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003ר' מאיר\u0004 ש\u0003אמר\u0004 במשנה להלן (מנחות טז,א): \u0003מפגלין בחצי מתיר,\u0004 שאם שחט אחד מן הכבשים לאכול את שתי הלחם למחר הרי זה פיגול, וכאן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 רבי ש\u0003לא.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 הלשון \u0003\"לעולם\u0004 אינו פיגול\"? \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 שהכוונה היא שאין זה פיגול עד שיחשב \u0003בשתיהן\u0004 בשתי הלחם לאוכלן למחר, \u0003ו\u0004גם \u0003בשניהן\u0004 כששחט את שני הכבשים, \u0003ו\u0004שיטת \u0003ר' יוסי היא, ו\u0004אם כן \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003ר' מאיר ו\u0004גם \u0003מדרבנן קאתי\u0004 \u0005[מ\u0006דברי \u0005חכמים הוא בא]\u0006 — \u0003היינו דקאמר\u0004 \u0005[זהו שהוא אומר]\u0006 \u0003\"לעולם\",\u0004 שמדגיש שדעתו היא בניגוד לכל שאר הדעות.","\u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 שהיא שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003ו\u0004אינה באה \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 אלא \u0003מ\u0004דברי \u0003ר' מאיר, מאי\u0004 \u0005[מהו]\u0006 ההדגשה \u0003\"לעולם\"?\u0004 אלא בהכרח ברייתא זו שיטת ר' יוסי היא, ועומדת בעינה הקושיה ממנה על רב הונא, שאמר כי לדעת ר' יוסי אם פיגל בירך ימין לא פיגל בירך שמאל.","\u0003ועוד, הא\u0004 \u0005[הרי]\u0006 \u0003אמר רב אשי: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 שלא כרב הונא, ממה ששנינו, \u0003רבי אומר משום ר' יוסי:\u0004 המחשב מחשבת חוץ לזמנו בחטאות הפנימיות, שמזים מדמן בהיכל, \u0003אם\u0004 \u0003פיגל\u0004 (חישב) \u0003בדבר הנעשה בחוץ\u0004 (בעזרה) — \u0003פיגל,\u0004 אבל חישב \u0003בדבר הנעשה בפנים\u0004 (בהיכל) — \u0003לא פיגל,\u0004","\u0003כיצד? היה עומד בחוץ\u0004 בזמן השחיטה \u0003ואמר: \"הריני שוחט על מנת להזות מדמו\u0004 בפנים \u0003למחר\"\u0004 — \u0003לא פיגל,\u0004 לפי \u0003ש\u0004זו \u0003מחשבה\u0004 שחישב \u0003בחוץ בדבר הנעשה בפנים.\u0004 וכן להיפך, אם \u0003היה עומד בפנים\u0004 בשעת ההזאה, \u0003ואמר: \"הריני מזה על מנת להקטיר אימורין\u0004 על המזבח החיצון \u0003למחר ולשפוך שיריים\u0004 על יסוד המזבח החיצון \u0003למחר\"\u0004 — גם כן \u0003לא פיגל, ש\u0004היתה זו \u0003מחשבה בפנים בדבר הנעשה בחוץ.\u0004","אבל אם \u0003היה עומד בחוץ\u0004 בשעת שחיטה, \u0003ואמר: \"הריני שוחט על מנת לשפוך שיריים למחר ולהקטיר אימורין למחר\"\u0004 — \u0003פיגל, ש\u0004היא \u0003מחשבה בחוץ בדבר הנעשה בחוץ.\u0004","ויש לברר: כשהוא שוחט על מנת \u0003לשפוך שיריים\u0004 למחר, \u0003לאיפגולי מאי\u0004 \u0005[שיתפגל מה]?\u0006 מה מתפגל על ידי כך? \u0003אילימא לאיפגולי\u0004 \u0005[אם תאמר שיתפגל]\u0006 ה\u0003דם\u0004 עצמו, וכי \u0003דם מי מיפגל\u0004 \u0005[האם נעשה פיגול]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005],\u0006 \u0003אלו דברים שאין חייבין עליהן משום פיגול: הקומץ, והלבונה, והקטורת, ומנחת כהנים, ומנחת נסכים, ומנחת כהן משיח, והדם!\u0004","\u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שהכוונה היא \u0003לאפגולי\u0004 \u0005[שיתפגל]\u0006 ה\u0003בשר\u0004 של הקרבן. \u0003השתא\u0004 \u0005[ומעתה]\u0006 יש לדון: \u0003ומה התם דלא חשיב ביה\u0004 \u0005[שם שאינו מחשב בו]\u0006 \u0003בבשר גופיה\u0004 \u0005[עצמו]\u0006 לאוכלו חוץ לזמנו, אלא בדם לשפוך את שייריו למחר, בכל זאת \u0003אמר ר' יוסי: מיפגל\u0004 \u0005[מתפגל]\u0006 הבשר, \u0003הכא\u0004 \u0005[כאן]\u0006 כששוחט על מנת לאכול ירך של ימין חוץ לזמנו, \u0003דחשיב ביה\u0004 \u0005[שמחשב בו]\u0006 \u0003בזבח גופיה\u0004 \u0005[עצמו],\u0006 \u0003לא כל שכן\u0004 שאם \u0003פיגל בירך ימין\u0004 ש\u0003פיגל\u0004 גם \u0003בירך שמאל?\u0004","\u0003ועוד, האמר\u0004 \u0005[הרי אמר]\u0006 \u0003רבינא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה שלא כרב הונא ממה ששנינו במשנתנו: \u0003הקומץ את המנחה לאכול שיריה או להקטיר קומצה למחר, מודה ר' יוסי בזו שפיגל וחייבין עליו כרת.\u0004","ויש לברר: \u0003להקטיר קומצה לאיפגולי מאי\u0004 \u0005[שיתפגל מה]?\u0006 מה מתפגל על ידי כך? \u0003אילימא לאיפגולי\u0004 \u0005[אם תאמר שיתפגל]\u0006 ה\u0003קומץ,\u0004 וכי \u0003קומץ מי מיפגל\u0004 \u0005[האם נעשה פיגול]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005],\u0006 \u0003אלו דברים שאין חייבין עליהן משום פיגול: הקומץ כו'! אלא פשיטא\u0004 \u0005[פשוט]\u0006 הדבר שהכוונה היא \u0003לאיפגולי\u0004 \u0005[שיתפגלו]\u0006 ה\u0003שיריים. השתא\u0004 \u0005[\u0006ו\u0005מעתה]\u0006 יש לדון: \u0003ומה התם\u0004 \u0005[שם]\u0006 \u0003דלא חשיב בהו\u0004 \u0005[שאינו מחשב בהם]\u0006 \u0003בשיריים גופיה\u0004 \u0005[עצמם]\u0006 לאוכלם למחר —"],["\u0003מיפגלי\u0004 \u0005[נעשו פיגול],\u0006 \u0003הכא דחשיב בהו\u0004 \u0005[כאן,\u0006 בירך של ימין ושל שמאל, \u0005שמחשב בהם]\u0006 \u0003בזביחה גופה\u0004 \u0005[עצמה]\u0006 על מנת לאכול אחת מהן למחר, \u0003לא כל שכן\u0004 שתתפגל השניה?","\u0003אלא אמר רבי יוחנן:\u0004 לדעת ר' יוסי, אם פיגל בירך ימין נתפגלה גם ירך שמאל, שגוף אחד הן, וכפי שהוכחנו. וכן דעתו ביחס לשתי הלחם, כפי ששנינו בברייתא, שאם חישב על כזית משתיהן הרי זה מצטרף. ומה שהוא שונה במשנה שאם פיגל באחת מהן לא נתפגלה חבירתה, ומכאן משמע שלדעתו שני גופים הן — \u0003היינו טעמא\u0004 \u0005[זהו טעמו]\u0006 של \u0003ר' יוסי: הכתוב עשאן\u0004 את שתי הלחם \u0003גוף אחד, והכתוב עשאן\u0004 גם \u0003שני גופין,\u0004 עשאן \u0003גוף אחד\u0004 — \u0003דמעכבי אהדדי\u0004 \u0005[שמעכבות זה את זה],\u0006 ואין אחת כשרה בלא השניה, עשאן \u0003שני גופין\u0004 — \u0003דאמר רחמנא\u0004 \u0005[שאמרה התורה]\u0006 \u0003הא לחודה עבידא והא לחודה עבידא\u0004 \u0005[זו לעצמה נעשית וזו לעצמה נעשית]\u0006 שצריך ללוש ולערוך כל אחת בפני עצמה.","ומשום כך, אם \u0003ערבינהו\u0004 \u0005[עירב אותן]\u0006 במחשבתו, שחישב על מנת לאכול כזית משתיהן — הריהן \u0003מתערבין,\u0004 ופיגל, שהרי \u0003הכתוב עשאן גוף אחד,\u0004 ואם \u0003פלגינהו\u0004 — \u0003מיפלגי\u0004 \u0005[חילק אותן,\u0006 שחישב רק באחת מהן — הרי \u0005הן מתחלקות],\u0006 ולא פיגל בחבירתה, שהרי \u0003הכתוב עשאן שני גופין.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' יוחנן\u0004 שאלה זו: אם \u0003פיגל ב\u0004אחד מן המינים של \u0003לחמי תודה,\u0004 \u0003מהו,\u0004 האם פיגל גם בשאר? וכן אם פיגל \u0003ב\u0004אחד משני המינים של \u0003מנחת מאפה,\u0004 חלות או רקיקים, \u0003מהו,\u0004 האם פיגל במין השני? \u0003תנא ליה\u0004 \u0005[שנה לו]\u0006 \u0003רב תחליפא ממערבא\u0004 ברייתא ששנינו בה: \u0003וכן אתה אומר בלחמי תודה, וכן אתה אומר במנחת מאפה,\u0004 משמע שדין אחד להם.","ועוד בענין צירוף לפיגול \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אם \u0003בשעת שחיטה\u0004 של קרבן \u0003חישב לאכול חצי זית\u0004 מבשרו למחר, \u0003ובשעת זריקה\u0004 של הדם \u0003חישב לאכול חצי זית\u0004 למחר — הרי זה \u0003פיגול, מפני ששחיטה וזריקה מצטרפין\u0004 למחשבת פיגול.","ונחלקו בענין זה אמוראים, \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 דוקא \u0003שחיטה וזריקה, דתרווייהו\u0004 \u0005[ששתיהן]\u0006 \u0003מתירין\u0004 את הקרבן — \u0003אין\u0004 \u0005[כן]\u0006 מצטרפות לפגל, אבל \u0003קבלה\u0004 של הדם בכלי שרת \u0003והולכה\u0004 שלו למזבח, שאינן מתירות בעצמן, אלא הן עבודות של הכנה — \u0003לא. ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 להיפך: \u0003הנך דמרחקן\u0004 \u0005[אלה,\u0006 שחיטה וזריקה, \u0003שרחוקות]\u0004 זו מזו, מצטרפות כשחישב בשתיהן, \u0003וכל שכן הני דמקרבן\u0004 \u0005[אלה,\u0006 קבלה והולכה, \u0005שקרובות\u0006 זו לזו\u0005]\u0006 מצטרפות, שהיה בכך רצף של מחשבה.","ועל מה ששנינו בברייתא ששחיטה וזריקה מצטרפות, שואלים: \u0003איני\u0004 \u0005[כן הוא]?\u0006 \u0003והא תני\u0004 \u0005[והרי שנה]\u0006 \u0003לוי\u0004 בברייתא שלו: \u0003ארבע עבודות אין מצטרפות לפיגול, שחיטה וזריקה, קבלה והולכה! אמר רבא, לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 של לוי, ששנינו בה שאינן מצטרפות — הריהי כשיטת \u0003רבי, הא\u0004 \u0005[זו]\u0006 שמצטרפות — כשיטת \u0003רבנן\u0004 \u0005[חכמים].\u0006","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 בענין שני כבשי עצרת ושתי הלחם: \u0003השוחט את הכבש\u0004 על מנת \u0003לאכול חצי זית מחלה זו\u0004 למחר, \u0003וכן\u0004 שחט את \u0003חבירו\u0004 במחשבה \u0003לאכול חצי זית מחלה זו\u0004 השניה למחר, \u0003רבי אומר: אומר אני שזה כשר,\u0004 ומכאן שלדעתו אין המחשבה בשני מתירים מצטרפת לפגל, אם חישב בכל פעם בחצי אכילה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 \u0003אימר דשמעת ליה\u0004 \u0005[אמור ששמעת אותו]\u0006 את \u0003רבי\u0004 שאומר שאין מחשבה מצטרפת לפגל — כשחישב בכל פעם ב\u0003חצי מתיר\u0004 (כבש אחד מתוך שנים) \u0003וחצי אכילה\u0004 (חצי כזית), אבל בשחיטה וזריקה, שמחשב בכל פעם ב\u0003כולו מתיר\u0004 \u0005[במתיר כולו]\u0006 \u0003וחצי אכילה, מי שמעת ליה\u0004 \u0005[האם שמעת אותו]\u0006 שהוא אומר שאינו פיגול?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא בר רב חנן לאביי:\u0004 \u0003ואי אית ליה\u0004 \u0005[ואם,\u0006 כדבריך, \u0005יש לו]\u0006 \u0003לרבי\u0004 כלומר, סבור הוא שאם חישב ב\u0003כולו מתיר וחצי אכילה\u0004 הרי זה פיגול, מדוע כששחט כל כבש על מנת לאכול כחצי זית מחלה אחרת הרי זה כשר לגמרי? \u0003לגזור\u0004 \u0005[שיגזור]\u0006 במקרה זה \u0003חצי מתיר וחצי אכילה\u0004 ויאמר שהוא פסול, גזירה \u0003אטו\u0004 \u0005[משום]\u0006 \u0003כולו מתיר וחצי אכילה\u0004 שהוא פיגול וחייבים עליו כרת, \u0003דהא\u0004 \u0005[שהרי]\u0006 מצאנו כי \u0003ר' יוסי גזר\u0004 \u0005[גוזר]\u0006 כן בכגון זה, \u0003ורבנן גזרי\u0004 \u0005[ו\u0006כן \u0005חכמים גוזרים]!\u0006","ומפרטים: \u0003ר' יוסי גזר\u0004 \u0005[גוזר],\u0006 כפי \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 הקומץ את המנחה על מנת להקטיר את הקומץ למחר — הרי זה פיגול (לדעת הכל), על מנת \u0003להקטיר לבונתה למחר, ר' יוסי אומר: פסול\u0004 הוא \u0003ואין בו כרת, וחכמים אומרים: פיגול\u0004 הוא \u0003וחייבין עליה כרת.\u0004 משמע שר' יוסי פוסל בדבר שאינו פיגול (מחשב להקטיר לבונתה למחר) גזירה משום מחשב להקטיר קומצה למחר, שהוא פיגול.","\u0003ורבנן נמי גזרי\u0004 \u0005[וחכמים גם כן גוזרים]\u0006 בדומה לזה, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003פיגל ב\u0004שעת הקטרת ה\u0003קומץ ולא ב\u0004שעת הקטרת \u0003לבונה,\u0004 או \u0003ב\u0004שעת הקטרת \u0003לבונה ולא בקומץ\u0004 — \u0003ר' מאיר אומר: פיגול\u0004 הוא \u0003וחייבין עליו כרת, וחכמים אומרים: אין בו כרת עד שיפגל בכל המתיר.\u0004 וממה שאמרו \"אין בו כרת\" ולא אמרו \"כשר\" משמע שהוא פסול, גזירה משום פיגול בכל המתיר!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?\u0006 \u0003בשלמא התם\u0004 \u0005[נניח שם]\u0006 אפשר לומר ש\u0003גזר\u0004 \u0005[גוזר]\u0006 \u0003ר' יוסי\u0004 במחשב על \u0003קומץ\u0004 של \u0003לבונה אטו\u0004 \u0005[משום]\u0006 מחשב על \u0003קומץ\u0004 של \u0003מנחה,\u0004 שהוא דומה לו.","וכן \u0003רבנן גזרי\u0004 \u0005[\u0006\u0005חכמים גוזרים]\u0006 במחשב בשעת הקטרת \u0003קומץ\u0004 בלבד, \u0003גזירה\u0004 \u0003אטו\u0004 \u0005[משום]\u0006 מחשב בשעת הקטרת \u0003קומץ\u0004 של \u0003מנחת חוטא\u0004 שאין בה לבונה, שאם חישב בו פיגל, מפני שחישב בכל המתיר. \u0003ו\u0004כן הם גוזרים במחשב בהקטרת \u0003לבונה\u0004 בלבד, גזירה \u0003אטו\u0004 \u0005[משום]\u0006 \u0003לבונה הבאה בבזיכין\u0004 של לחם הפנים, שאין בה קומץ, ואם חישב בה פיגל, מפני שחישב בכל המתיר.","וכן \u0003כבשים נמי\u0004 \u0005[גם כן]\u0006 שאמרו חכמים (להלן מנחות טז,א) כי השוחט אחד מכבשי עצרת על מנת לאכול שתי החלות למחר אין בו כרת, אבל הוא פסול — גוזרים הם בשחיטת \u0003כבש\u0004 אחד גזירה \u0003אטו\u0004 \u0005[משום]\u0006 \u0003כבש חבירו,\u0004 שאם יפגל גם בו נמצא מפגל בכל המתיר.","וכיוצא בזה, לגבי \u0003בזך,\u0004 שאם הקטיר אחד מן הבזיכים של לחם הפנים על מנת לאכול שני סדרים למחר, אומרים הם שהוא פסול, גזירה \u0003אטו\u0004 \u0005[משום]\u0006 הקטרה של \u0003בזך\u0004 \u0003חבירו,\u0004 שאם יפגל גם בו נמצא מפגל בכל המתיר.","\u0003אלא הכא\u0004 \u0005[כאן]\u0006 בשוחט כל אחד מכבשי העצרת על מנת לאכול חצי כזית מחלה אחרת, \u0003מי איכא\u0004 \u0005[האם יש]\u0006 \u0003חצי מתיר וחצי אכילה בעלמא\u0004 \u0005[בכלל]\u0006 שהוא פיגול, \u0003דליקום וליגזר\u0004 \u0005[שיקום\u0006 רבי \u0005ויגזור]\u0006 בזה, ויאמר שהוא פסול?","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 \u0003דטעמא דרבנן משום הכי הוא\u0004 \u0005[שטעמם של חכמים משום כך הוא],\u0006 שהם פוסלים במפגל בקומץ ולא בלבונה, משום שיש דבר כמותו שהוא פיגול, ומנין? \u0003דקתני סיפא\u0004 \u0005[שהוא שונה בסופה]\u0006 של אותה משנה: \u0003מודים חכמים לר' מאיר במנחת חוטא ומנחת קנאות, שאם פיגל בקומץ\u0004 — \u0003שפיגול וחייבין עליה כרת, שהקומץ הוא המתיר.\u0004","ויש לשאול: \u0003הא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 \u0003למה לי למיתנא\u0004 \u0005[לשנות אותו]\u0006 \u0003כלל? פשיטא\u0004 \u0005[פשוט]\u0006 הדבר שהוא פיגול, \u0003מי איכא מתיר אחרינא\u0004 \u0005[האם יש\u0006 שם \u0005מתיר אחר]\u0006 מלבד הקומץ? \u0003אלא לאו הא קא משמע לן\u0004 \u0005[האם לא\u0006 דבר \u0005זה משמיע לנו],\u0006 \u0003דטעמא\u0004 \u0005[שהטעם]\u0006 שבקומץ של מנחה רגילה הרי זה פסול — \u0003משום דאיכא\u0004 \u0005[שיש]\u0006 \u0003קומץ\u0004 של \u0003מנחת חוטא דדמי ליה\u0004 \u0005[שדומה לו],\u0006 שהוא פיגול.","\u0003נטמאת אחת מן החלות\u0004 של שתי הלחם שבחג השבועות, \u0003או אחד מן הסדרים\u0004 של לחם הפנים — \u0003ר' יהודה אומר: שניהם,\u0004 שתי החלות או שני הסדרים, \u0003יצאו לבית השריפה,\u0004 כדין קדשים שנפסלו, לפי \u0003שאין קרבן ציבור חלוק,\u0004 ואם נפסל חלקו \u0003—\u0004 פסול כולו. \u0003וחכמים אומרים:\u0004 לא כן, אלא \u0003הטמא\u0004 נשאר \u0003בטומאתו\u0004 ויצא לבית השריפה, \u0003והטהור יאכל.\u0004","\u0003אמר ר' אלעזר: מחלוקת\u0004 ר' יהודה וחכמים היא כשנטמאת אחת מן החלות \u0003לפני זריקה\u0004 של דם הכבשים, המתירים את שתי הלחם, ונחלקו האם הועילה זריקת הדם להתיר את החלה הטהורה שנותרה. \u0003אבל\u0004 אם נטמאה אחת מן החלות \u0003לאחר זריקה,\u0004 לאחר שכבר הותרו החלות באכילה — \u0003דברי הכל הטמא בטומאתו והטהור יאכל.\u0004","ושואלים: \u0003ו\u0004כשנטמאת אחת מן החלות \u0003לפני זריקה, במאי פליגי\u0004 \u0005[במה,\u0006 באיזה עיקרון \u0005הם חלוקים]?\u0006 \u0003אמר רב פפא: ב\u0004יחס ל\u0003ציץ\u0004 שבראש הכהן הגדול, המרצה על טומאת הקדשים, ובשאלה האם הוא \u0003מרצה על אכילות קא מיפלגי\u0004 \u0005[הם חלוקים],\u0006 כלומר, האם הוא מרצה רק על טומאת הדברים הקרבים על המזבח, או גם על טומאת הדברים הנאכלים לכהנים,"],["\u0003רבנן סברי\u0004 \u0005[חכמים סבורים]:\u0006 \u0003הציץ מרצה על אכילות,\u0004 על טומאת הנאכל לכהנים, וזריקת הדם כשרה לגמרי, ולכן החלה שלא נטמאה הותרה על ידה באכילה. \u0003ור' יהודה סבר\u0004 \u0005[סבור],\u0006 \u0003אין הציץ מרצה על אכילות,\u0004 וכיון שזריקת הדם אינה כשרה לגמרי — לא הועילה להתיר את החלה הטהורה באכילה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן לרב פפא:\u0004 וכי רק משום כך חולק ר' יהודה על חכמים? \u0003והא\u0004 \u0005[והרי]\u0006 ביחס ל\u0003עולין\u0004 על המזבח שנטמאו, שלכל הדעות \u0003הציץ מרצה על העולין,\u0004 וגם לדעת ר' יהודה, \u0003ופליגי\u0004 \u0005[ו\u0006בכל זאת \u0005חלוקים\u0006 הם\u0005]!\u0006","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003נטמא אחד מן הבזיכין\u0004 של לחם הפנים, העומדים להקטרה על המזבח — \u0003ר' יהודה אומר: שניהם יעשו בטומאה,\u0004 כלומר, רשאי לטמא גם את הבזיך השני, ולהקטיר את שניהם על המזבח, \u0003לפי שאין קרבן ציבור חלוק,\u0004 והקרבת קרבן ציבור דוחה את הטומאה. \u0003וחכמים אומרים: הטמא\u0004 יקרב \u0003בטומאתו, והטהור בטהרתו.\u0004 משמע שאין המחלוקת תלויה בשאלה האם הציץ מרצה או לא!","\u0003ועוד, אמר רב אשי: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת שאין זה טעם המחלוקת, ממה ששנינו לענין פסח הנאכל בטומאה, \u0003ר' יהודה אומר: אפילו שבט אחד טמא וכל השבטים טהורין\u0004 — \u0003יעשו\u0004 ישראל כולם את קרבן הפסח \u0003בטומאה, לפי שאין קרבנות ציבור חלוק, והכא מאי\u0004 \u0005[וכאן מה\u0006 ענין\u0005]\u0006 של \u0003הציץ מרצה איכא\u0004 \u0005[יש]?\u0006 והרי הציץ מרצה על טומאת הקרבן, ולא על טומאת המקריבים!","\u0003ועוד, האמר\u0004 \u0005[הרי אמר]\u0006 \u0003רבינא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת שאין זה טעם המחלוקת, ממה ששנינו במשנתנו: \u0003נטמאת אחת מן החלות\u0004 של שתי הלחם, \u0003או אחת מן הסדרין\u0004 של לחם הפנים, \u0003ר' יהודה אומר: שניהם יצאו לבית השריפה, לפי שאין קרבן ציבור חלוק, וחכמים אומרים: הטמא בטומאתו והטהור יאכל.\u0004","\u0003ואם איתא\u0004 \u0005[אכן]\u0006 המחלוקת היא האם ציץ מרצה על אכילות — \u0003\"לפי שאין הציץ מרצה על אכילות\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 \u0003אלא אמר ר' יוחנן: תלמוד ערוך הוא בפיו של ר' יהודה,\u0004 מסורת היא בידו, \u0003שאין קרבן ציבור חלוק,\u0004 ואם נטמא מקצתו נפסל כולו.","\u0003התודה מפגלת את הלחם\u0004 שמביאים עמה, \u0003והלחם אינו מפגל את התודה. כיצד?\u0004 אם \u0003שחט את התודה\u0004 על מנת \u0003לאכול ממנה למחר\u0004 — הרי \u0003היא\u0004 עצמה \u0003ו\u0004גם \u0003הלחם מפגלין,\u0004 והאוכלם חייב כרת. אבל אם שחטה על מנת \u0003לאכול מן הלחם למחר\u0004 — \u0003הלחם מפגל והתודה אינה מפוגלת.\u0004","וכן \u0003הכבשים\u0004 של שתי הלחם של עצרת \u0003מפגלין את הלחם, והלחם אינו מפגל את הכבשים. כיצד? השוחט את הכבשים\u0004 על מנת \u0003לאכול מהן למחר\u0004 — \u0003הם והלחם מפוגלין,\u0004 על מנת \u0003לאכול את הלחם למחר\u0004 — \u0003הלחם מפוגל והכבשים אינן מפוגלין.\u0004","ביחס למה ששנינו שהתודה מפגלת את הלחם, שואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום\u0004 מה שאמר \u0003רב כהנא,\u0004 ש\u0003אמר רב כהנא: מנין ללחמי תודה שנקראו תודה? שנאמר: \"והקריב על זבח התודה חלות\"\u0004 (ויקרא ז, יב), והסמיך \"חלות\" ל\"תודה\", ללמד שגם הן קרויות תודה,","\u0003אי הכי איפכא נמי\u0004 \u0005[אם כך ההיפך גם כן]\u0006 היה צריך להיות, שהמפגל בלחם מפגל גם בתודה! ודוחים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006 כי \u0003לחם איקרי\u0004 \u0005[נקרא]\u0006 אמנם \u0003תודה,\u0004 אבל \u0003תודה לא איקרי\u0004 \u0005[נקראה]\u0006 \u0003לחם.\u0004","ושואלים: \u0003אלא הא דקתני\u0004 \u0005[זו ששנינו]:\u0006 \u0003הכבשים\u0004 של שתי הלחם \u0003מפגלין את הלחם והלחם אינו מפגל את הכבשים, לחם\u0004 של שתי הלחם \u0003היכא אשכחן דאיקרי\u0004 \u0005[היכן מצאנו שנקרא]\u0006 \u0003כבשים? אלא לאו\u0004 \u0003היינו טעמא\u0004 \u0005[האם לא זהו הטעם]\u0006 שהתודה מפגלת את הלחם ולא להיפך — מפני שה\u0003לחם\u0004 בא ב\u0003גלל\u0004 התודה \u0003ואין\u0004 ה\u0003תודה\u0004 באה ב\u0003גלל\u0004 ה\u0003לחם,\u0004 שהתודה היא העיקר. וכן ביחס לכבשים ושתי הלחם, \u0003לחם\u0004 בא ב\u0003גלל\u0004 ה\u0003כבשים ואין כבשים\u0004 ב\u0003גלל\u0004 ה\u0003לחם.\u0004","ומעירים: \u0003וצריכי\u0004 \u0005[וצריכים]\u0006 שייאמרו \u0005ההלכות בשני המקרים,\u0006 \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק בתודה, היינו אומרים כך: \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא דכי\u0004 \u0005[שכאשר]\u0006 \u0003מפגל בלחם לא מפגלא\u0004 \u0005[מתפגלת]\u0006 \u0003תודה\u0004 — \u0003משום\u0004 ש\u0003לא הוזקקו זה לזה בתנופה,\u0004 שאין צורך בלחם כדי לקיים בתודה מצות הנפה. \u0003אבל כבשים\u0004 של שתי הלחם ש\u0003הוזקקו זה לזה בתנופה,\u0004 כי מניפים את הלחם יחד עם הכבשים בתנופה אחת — \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003מפגל בלחם ליפגלי נמי\u0004 \u0005[שיתפגלו גם כן]\u0006 ה\u0003כבשים,\u0004 על כן \u0003צריכא\u0004 \u0005[צריכה]\u0006 ההלכה להיאמר גם במקרה זה.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' אלעזר מרב: השוחט את התודה\u0004 על מנת \u0003לאכול כזית ממנה ומלחמה למחר, מהו\u0004 הדין? ומסבירים: \u0003לאיפגולי\u0004 \u0005[שתתפגל]\u0006 ה\u0003תודה\u0004 באופן זה \u0003לא מיבעיא\u0004 \u0005[נשאלה]\u0006 \u0003לי\u0004 שאלה זו, שהרי \u0003השתא\u0004 \u0005[עכשיו],\u0006 אם היה מחשב בכזית שלם ש\u0003כולו מלחמה לא מיפגלא\u0004 \u0005[לא היתה מתפגלת]\u0006 על ידי כך, למרות שיש במחשבה זו לפגל את הלחם, כפי ששנינו במשנה, כאשר הוא מחשב בחצי כזית \u0003ממנה ו\u0004בחצי כזית \u0003מלחמה,\u0004 שאתה צריך לצרף שתי מחשבות שונות שאין בכל אחת כדי לפגל, \u0003מיבעיא\u0004 \u0005[נצרכה לומר]\u0006 שאינה מתפגלת?","\u0003כי קא מיבעיא לי\u0004 \u0005[כאשר נשאלה לי]\u0006 השאלה הרי זה לענין \u0003לאיפגולי\u0004 \u0005[שיתפגל]\u0006 ה\u0003לחם,\u0004 והשאלה היא: \u0003מי מצטרפה\u0004 \u0005[האם מצטרפת]\u0006 ה\u0003תודה לאיפגולי\u0004 \u0005[שיתפגל]\u0006 ה\u0003לחם או לא?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב: \u0003אף בזו,\u0004 כמו במחשב לאכול כזית מן הלחם — \u0003הלחם מפוגל והתודה אינה מפוגלת.\u0004 ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 הלחם מפוגל? \u0003לימא\u0004 \u0005[נאמר]\u0006 \u0003קל וחומר: ומה תודה\u0004 שהיא \u0003המפגל,\u0004 שמחשבה בכחצי כזית ממנה מצטרפת (לדברי רב) לפגל את הלחם — \u0003אין מתפגל,\u0004 הלחם \u0003הבא לפגל ולא פיגל,\u0004 שאין המחשבה בחצי כזית ממנו מצטרפת כדי לפגל את התודה — \u0003אינו דין שלא יתפגל?\u0004","ושואלים: \u0003ומי אמרינן\u0004 \u0005[והאם אומרים אנו]\u0006 \u0003קל וחומר כי האי גוונא\u0004 \u0005[כגון זה]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003מעשה באחד\u0004"],["\u0003שזרע כרמו של חבירו\u0004 כאשר היה הכרם \u0003סמדר\u0004 (בתחילת צמיחת הענבים), \u0003ובא מעשה לפני חכמים, ואסרו את הזרעים\u0004 של הזורע, כדין כלאי הכרם, \u0003והתירו את הגפנים.\u0004 ויש לשאול: \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003לימא\u0004 \u0005[שיאמר]\u0006 \u0003קל וחומר הוא: ומה האוסר\u0004 כלומר, הגפן, שעל ידה נאסרו הזרעים — \u0003אינו נאסר,\u0004 הזרע \u0003הבא לאסור ולא אסר\u0004 את הגפנים — \u0003אינו דין שלא יתאסר?\u0004","ודוחים: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 דווקא \u0003קנבוס ולוף אסרה תורה\u0004 לזרוע בכרם, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003היתה שדהו זרועה קנבוס ולוף\u0004 — \u0003לא יהא זורע על גביהם,\u0004 מפני \u0003שהן עושות\u0004 פרי \u0003לשלש שנים,\u0004 ואילו \u0003שאר זרעים\u0004 רק \u0003מדרבנן הוא דאסירי\u0004 \u0005[מדברי חכמים הוא שאסורים],\u0006 ומכיון שהכל מדרבנן, \u0003האי דעביד איסורא\u0004 \u0005[זה\u0006 \u0005שעשה איסור],\u0006 שזרע את הכרם של חבירו — \u0003קנסוה רבנן\u0004 \u0005[קנסו אותו חכמים],\u0006 \u0003האי דלא עביד איסורא\u0004 — \u0003לא קנסוה רבנן\u0004 \u0005[זה שלא עשה איסור,\u0006 בעל הכרם, \u0005לא קנסו אותו חכמים].\u0006 \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בדין פיגול, שהוא מדין תורה, \u0003לימא\u0004 \u0005[שיאמר]\u0006 \u0003קל וחומר!\u0004","\u0003ואיכא דמתני לה\u0004 \u0005[ויש ששונים את הבעיה הזו]\u0006 לא לענין תודה אלא לענין \u0003כבשים\u0004 של שתי הלחם. וכך \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' אלעזר מרב: השוחט את הכבשים\u0004 על מנת \u0003לאכול כזית\u0004 מצורף \u0003מהן ומלחמן, מהו?\u0004","\u0003לאיפגולי\u0004 \u0005[שיתפגלו]\u0006 ה\u0003כבשים לא קא מיבעיא\u0004 \u0005[לא נשאלה]\u0006 \u0003לי,\u0004 כי \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 כאשר מחשב על כזית ש\u0003כולו מלחם לא מפגלי\u0004 \u0005[אינם מתפגלים],\u0006 כפי ששנינו במשנתנו שהלחם אינו מפגל את הכבשים, כאשר חישב על כזית \u0003מהן ומלחמן מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שאינם מתפגלים? \u0003כי קא מיבעיא לי\u0004 \u0005[כאשר נשאלה לי]\u0006 השאלה הרי זה \u0003לאיפגולי\u0004 \u0005[ל\u0006ענין ש\u0005יתפגל]\u0006 ה\u0003לחם, מי מצטרפי\u0004 \u0005[האם מצטרפים]\u0006 ה\u0003כבשים לאיפגולי\u0004 \u0005[שיתפגל]\u0006 \u0003ללחם או לא?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב: \u0003אף בזו,\u0004 כמו במחשב לאכול כזית מן הלחם — \u0003הלחם מפוגל והכבשים אינן מפוגלין.\u0004 ושואלים אותה שאלה: \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003לימא\u0004 \u0005[נאמר]\u0006 \u0003קל וחומר: ומה המפגל\u0004 כלומר, הכבשים, שמחשבה בהם מצטרפת לפגל את הלחם — \u0003אינו מתפגל,\u0004 הלחם \u0003הבא לפגל\u0004 על ידי הצירוף \u0003ולא פיגל\u0004 — \u0003אינו דין שלא יתפגל!\u0004","ומקשים: \u0003ומי אמרינן\u0004 \u0005[והאם אומרים אנו]\u0006 \u0003קל וחומר כי האי גונא\u0004 \u0005[כגון זה]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003מעשה באחד שזרע כרמו של חבירו סמדר\u0004 ובא מעשה לפני חכמים ואסרו את הזרעים והתירו את הגפנים, \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 נאסרים רק הזרעים? \u0003לימא\u0004 \u0005[שיאמר]\u0006 \u0003קל וחומר: מה\u0004 הכרם \u0003האוסר אינו נאסר, הבא לאסור ולא אסר\u0004 כלומר, הזרעים — \u0003אינו דין שלא יתאסר?\u0004","ודוחים: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003קנבוס ולוף אסרה תורה,\u0004 אבל \u0003שאר זרעים מדרבנן הוא דאסירי\u0004 \u0005[מדברי חכמים הוא שאסורים],\u0006 ולכן \u0003האי דעבד איסורא קנסוה רבנן\u0004 \u0005[זה שעשה איסור,\u0006 הזורע, \u0005קנסו אותו חכמים],\u0006 \u0003דלא עבד איסורא לא קנסוה רבנן\u0004 \u0005[\u0006\u0003זה\u0004 \u0005שלא עשה\u0006 \u0003איסור,\u0004 בעל הכרם, \u0005לא קנסו אותו חכמים],\u0006 \u0003אבל הכא\u0004 \u0005[כאן]\u0006 שהוא דין תורה — \u0003לימא\u0004 \u0005[נאמר]\u0006 \u0003קל וחומר!\u0004","ומעירים: ביחס לשאלתו של ר' אלעזר, \u0003מאן דמתני לה\u0004 \u0005[מי שהיה שונה אותה\u0006\u0003]\u0004 על \u0003תודה\u0004 האם היא מצטרפת עם לחמי התודה להתפגל כשחישב על כזית משניהם — \u0003כל שכן\u0004 שהשאלה נוגעת ל\u0003כבשים\u0004 של שתי הלחם, \u0003ומאן דמתני לה\u0004 \u0005[ו\u0006אולם \u0005מי שהיה שונה אותה]\u0006 על \u0003כבשים\u0004 ושתי הלחם, יש מקום לומר כי דווקא ב\u0003כבשים\u0004 ושתי הלחם \u0003הוא\u0004 שנשאלה השאלה, מפני ש\u0003הוזקקו זה לזה\u0004 \u0003לתנופה,\u0004 שהכהן מניף אותם יחד (ויקרא כג, כ), \u0003אבל תודה\u0004 ולחמה ש\u0003לא הוזקקה זה לזה\u0004 \u0003בתנופה\u0004 — \u0003לא,\u0004 אלא פשוט הדבר שאינה מצטרפת.","\u0003רבי אבא זוטי\u0004 \u0005[הקטן]\u0006 \u0003בעי לה הכי\u0004 \u0005[שאל אותה כך,\u0006 בנוסח אחר\u0005],\u0006 שכך \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' אלעזר מרב: השוחט את הכבש\u0004 האחד מכבשי העצרת על מנת \u0003לאכול כזית מחבירו למחר, מהו?\u0004 והשאלה היא: האם כשהוא \u0003אומר\u0004 \u0003\"חבירו\" כבש משמע, ו\u0004אם כן \u0003לא מפגל,\u0004 מפני שאין מתיר מפגל מתיר, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \"חבירו\" \u0003לחם משמע,\u0004 שתי הלחם, \u0003ו\u0004הוא \u0003מפגל ליה\u0004 \u0005[אותו],\u0006 כפי ששנינו במשנתנו?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב: \u0003תניתוה\u0004 \u0005[שניתם אותה\u0006 כבר\u0005],\u0006 יש לשאלה זו פתרון מהמשנה להלן: \u0003שחט אחד מן הכבשים\u0004 על מנת \u0003לאכול ממנו למחר\u0004 — \u0003הוא פיגול וחבירו כשר, לאכול מחבירו למחר\u0004 — \u0003שניהם כשרים, אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003\"חבירו\" כבש משמע!\u0004 ודוחים: מכאן אין ראיה גמורה, \u0003דלמא\u0004 \u0005[שמא]\u0006 מדובר שם \u0003דפריש\u0004 \u0005[שפירש]\u0006 \u0003ואמר \"חבירו כבש\",\u0004 אבל אם אמר \"חבירו\" סתם עדיין נשארה שאלה.","\u0003הזבח מפגל את הנסכים\u0004 הבאים עמו, \u0003מ\u0004שעה \u0003שקדשו בכלי\u0004 ולא קודם לכן, אלו \u0003דברי ר' מאיר.\u0004 אבל \u0003הנסכים אינן מפגלים את הזבח. כיצד? השוחט את הזבח לאכול ממנו למחר\u0004 — \u0003הוא ונסכיו מפוגלין,\u0004 אבל אם שחטו על מנת \u0003להקריב נסכיו למחר\u0004 — \u0003הנסכים מפוגלין, הזבח אינו מפוגל.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003נסכי בהמה חייבין עליהן משום פיגול\u0004 כששחט את הזבח במחשבת חוץ לזמנו, \u0003מפני שדם הזבח מתירן לקרב,\u0004 שכל שיש לו מתירים (לאכילה או להקרבה) חייבים עליו משום פיגול משקרבו מתיריו, אלו \u0003דברי ר' מאיר.\u0004","\u0003אמרו לו לר' מאיר: והלא אדם מביא זבחו היום ונסכיו\u0004 למחר, ואפילו \u0003עד עשרה ימים,\u0004 ואם כן אינם חלק בלתי נפרד מן הזבח כדי שיתפגלו על ידו! \u0003אמר להן: אף אני לא אמרתי\u0004 שיהיו מפוגלים \u0003אלא ב\u0004נסכים ה\u0003באין עם הזבח,\u0004 וכבר קדשו בכלי ליקרב. \u0003אמרו לו:\u0004 והרי \u0003אפשר לשנותו\u0004 את הנסכים \u0003לזבח אחר,\u0004 ואם כן אינם חלק בלתי נפרד מן הזבח!","\u0003אמר רבא, קסבר\u0004 \u0005[סבור]\u0006 \u0003ר' מאיר:\u0004 \u0003הוקבעו\u0004 הנסכים \u0003ב\u0004שעת ה\u0003שחיטה\u0004 להיות שייכים לזבח זה, ולא ניתן לשנותם, ולכן הוא מפגלם, \u0003כ\u0004מו \u0003לחמי תודה\u0004 שהוקבעו בשחיטת התודה להיות שייכים אליה, ולהתפגל על ידה.","בדומה לכך \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003לוג שמן של מצורע חייבין עליו משום פיגול, מפני שדם אשם מתירו ל\u0004תת ממנו על \u0003בהונות\u0004 המצורע, \u0003אלו\u0004 \u0003דברי ר' מאיר. אמרו לו לר' מאיר: והלא אדם מביא אשמו היום, ולוגו\u0004 של שמן \u0003מיכן ועד עשרה ימים,\u0004 ולאו דווקא באותו יום. והרי זו הוכחה שאינו ממש חלק מן הקרבן!","\u0003אמר להן: אף אני לא אמרתי\u0004 שהוא מתפגל \u0003אלא\u0004 בשמן ה\u0003בא עם האשם.\u0004 אמרו לו: אף במקרה זה אין השמן נחשב חלק מן הקרבן, שהרי \u0003אפשר לשנותו לאשם אחר. אמר רבא, קסבר\u0004 \u0005[סבור]\u0006 \u0003ר' מאיר:\u0004 לוג השמן \u0003הוקבעו\u0004 יחד עם האשם זה \u0003בשחיטה, כלחמי תודה,\u0004 ששחיטת התודה קובעת אותם יחד עם הזבח שבאו עמו."],["\u0003פיגל בקומץ ולא בלבונה,\u0004 שחישב על אכילת השיריים למחר בשעת הקטרת הקומץ ולא בשעת הקטרת הלבונה, או שחישב \u0003ב\u0004שעת הקטרת \u0003לבונה ולא ב\u0004שעת הקטרת ה\u0003קומץ, ר' מאיר אומר: פיגול\u0004 הוא \u0003וחייבין עליו כרת, וחכמים אומרים: אין בו כרת עד שיפגל בכל המתיר,\u0004 והמתיר של המנחה הוא הקומץ והלבונה גם יחד.","\u0003ומודים חכמים לר' מאיר במנחת חוטא ובמנחת קנאות,\u0004 שאין בהן לבונה, \u0003שאם פיגל בקומץ\u0004 — \u0003שהוא פיגול וחייבין עליו כרת,\u0004 מפני \u0003ש\u0004במקרה זה \u0003הקומץ\u0004 לבדו \u0003הוא המתיר.\u0004","אם \u0003שחט אחד מן הכבשים\u0004 של שתי הלחם בשבועות על מנת \u0003לאכול\u0004 את \u0003שתי\u0004 ה\u0003חלות למחר,\u0004 או \u0003הקטיר אחד מן הבזיכין\u0004 של לחם הפנים על מנת \u0003לאכול\u0004 את \u0003שני\u0004 ה\u0003סדרים\u0004 של הלחם \u0003למחר\u0004 — \u0003ר' מאיר אומר: פיגול\u0004 הוא \u0003וחייבין עליו כרת, וחכמים אומרים: אין בו כרת עד שיפגל בכל המתיר,\u0004 ושני הכבשים יחד מתירים את שתי הלחם, וכן שני הבזיכים יחד הם מתירי לחם הפנים.","\u0003שחט אחד מן הכבשים\u0004 של שתי הלחם על מנת \u0003לאכול ממנו למחר\u0004 — \u0003הוא פיגול,\u0004 שהוא המתיר של עצמו, \u0003וחבירו כשר.\u0004 ואם חישב \u0003לאכול מחבירו למחר\u0004 — \u0003שניהם כשרים,\u0004 שאין מתיר מפגל מתיר אחר.","\u0003אמר רב: מחלוקת\u0004 זו, כשפיגל בקומץ ולא בלבונה או להיפך, האם הוא פיגול, היא כגון ש\u0003נתן את הקומץ\u0004 על המערכה להקטירו \u0003בשתיקה\u0004 בסתם, \u0003ו\u0004אחר כך נתן \u0003את הלבונה\u0004 \u0003במחשבה\u0004 לאכול את השיריים למחר, שבוודאי חישב רק באחד מהם.","\u0003אבל\u0004 אם \u0003נתן הקומץ במחשבה\u0004 לאכול את השיריים למחר, \u0003ואת הלבונה בשתיקה\u0004 — \u0003דברי הכל פיגול,\u0004 וגם לדעת חכמים, והסברה היא: \u0003שכל העושה\u0004 — \u0003על דעת ראשונה הוא עושה. ושמואל אמר: עדיין הוא מחלוקת\u0004 כלומר, אף בזו חלוקים חכמים.","מסופר, \u0003יתיב\u0004 \u0005[יושב\u0006 היה\u0005]\u0006 \u0003רבא וקאמר לה להא שמעתא\u0004 \u0005[ואומר את השמועה הזו]\u0006 בשם רב. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב אחא בר רב הונא לרבא\u0004 ממה ששנינו: \u0003במה דברים אמורים\u0004 שהקומץ לבדו מפגל את המנחה — כשחישב מחשבת חוץ לזמנו \u0003ב\u0004שעת \u0003קמיצה ובמתן כלי ובהילוך,\u0004 אבל אם מש","\u0003בא לו להקטרה, נתן את הקומץ\u0004 על גבי אש המערכה \u0003בשתיקה, ואת הלבונה\u0004 נתן \u0003במחשבה\u0004 חוץ לזמנו, או אם נתן \u0003את הקומץ במחשבה ואת הלבונה בשתיקה\u0004 — \u0003ר' מאיר אומר: פיגול\u0004 הוא \u0003וחייבין עליו כרת, וחכמים אומרים: אין בו כרת עד שיפגל בכל המתיר.\u0004","\u0003קתני מיהא\u0004 \u0005[\u0006הריהו \u0005שונה על כל פנים]:\u0006 \u0003נתן את הקומץ במחשבה ואת הלבונה בשתיקה, ו\u0004בכל זאת \u0003פליגי\u0004 \u0005[חלוקים\u0006 חכמים\u0005],\u0006 ואין אומרים שהעושה על דעת ראשונה עושה. והרי זו קושיה על דברי רב!","השיב לו רבא: \u0003אימא\u0004 \u0005[אמור]\u0006 והסבר את הלשון כך: נתן את הקומץ במחשבה \u0003וכבר נתן את הלבונה בשתיקה מעיקרא\u0004 \u0005[מתחילה].\u0006 וטוענים, \u0003שתי תשובות בדבר,\u0004 כדי לדחות הסבר זה: \u0003חדא\u0004 \u0005[אחת],\u0006 שלפי הסבר זה נמצא \u0003דהיינו קמייתא\u0004 \u0005[שזו היא\u0006 ההלכה \u0005הראשונה]\u0006 שנאמרה כבר: נתן את הקומץ בשתיקה ואת הלבונה במחשבה! \u0003ועוד, התניא\u0004 \u0005[הרי שנויה\u0006 ברייתא\u0005]\u0006 אחרת ששנו בה במפורש: ו\u0003אחר כך\u0004 הקטיר את הלבונה!","\u0003תרגמא\u0004 \u0005[הסביר,\u0006 תירץ \u0005אותה]\u0006 \u0003רב חנינא\u0004 את הברייתא לפי שיטת רב: מדובר כאן \u0003בשתי דיעות\u0004 כלומר, בשני כהנים, שאחד הקטיר את הקומץ במחשבת חוץ לזמנו, והשני את הלבונה. שהואיל ואין מחשבתו של אחד קשורה בזה של חבירו — אין לומר שהמקטיר את הלבונה בשתיקה על דעת ראשונה עושה.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו בברייתא ביחס לפיגול בזריקת דם הזבח: \u0003במה דברים אמורים\u0004 שאם חישב מחשבת חוץ לזמנו במתנת הדם הראשונה, שהוא פיגול — \u0003בדמים הניתנין על מזבח החיצון,\u0004 כגון עולה, שמתנה אחת מתירה את הקרבן, והשאר אינו מעכב.","\u0003אבל דמים הניתנין על מזבח הפנימי, כגון ארבעים ושלש\u0004 הזאות \u0003של\u0004 פר ושעיר של \u0003יום הכיפורים,\u0004 או \u0003אחת עשרה\u0004 הזאות \u0003של פר כהן משוח, ו\u0004כן \u0003אחת עשרה של פר העלם דבר של ציבור,\u0004 שאם חיסר הזאה אחת נפסל הקרבן, אם \u0003פיגל בין ב\u0004הזאה ה\u0003ראשונה בין בשניה ובין בשלישית,\u0004 במקרה זה \u0003ר' מאיר אומר: פיגול\u0004 הוא \u0003וחייבין עליו כרת, וחכמים אומרים: אין בו כרת עד שיפגל בכל המתיר,\u0004 וכיון שכל ההזאות כולן הן המתיר, אין פיגול עד שיחשב בכל אחת מהן.","\u0003קתני מיהא\u0004 \u0005[שונה הוא על כל פנים]:\u0006 \u0003פיגל בין בראשונה בין בשניה ובין בשלישית, ופליגי\u0004 \u0005[וחלוקים]\u0006 חכמים על ר' מאיר במקרה שפיגל בראשונה, ואין אומרים שהזאה שניה נמשכת אחר מחשבתו הראשונה!","\u0003וכי תימא\u0004 \u0005[ואם תאמר],\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003בשתי דעות,\u0004 שהיו שני כהנים גדולים שעשו את ההזאה, וכגון שנפסל הכהן הגדול והחליפו כהן אחר, ומשום כך אין לומר שהשני עושה על דעת הראשון — \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]:\u0006 \"בזאת יבוא אהרן אל הקדש בפר\" וכו' (ויקרא טז, ג), \u0003\"בפר\"\u0004 — \u0003ואפילו בדמו של פר\u0004 כלומר, שיכול כהן גדול להמשיך ולהזות את שאר ההזיות מדמו של פר שהביאו כהן אחר מתחילה, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]:\u0006 \u0003\"בפר\" ולא בדמו של פר,\u0004 ויש צורך להביא פר אחר ולהתחיל את ההזיות מחדש, אם כן \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הלוא אין אפשרות של שתי דעות בעבודת קרבן אחד!","\u0003אמר רבא:\u0004 לדעת רב, יש לתרץ את הברייתא באופן אחר: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003כגון שפיגל\u0004 הכהן הגדול במחשבה בהזאה \u0003בראשונה, ושתק ב\u0004הזאה \u0003שניה, ופיגל בשלישית, דאמרינן\u0004 \u0005[שאנו אומרים]:\u0006 \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 שגם כאן יש להניח ש\u0003כל העושה על דעת ראשונה הוא עושה,\u0004 אם כן \u0003מיהדר פיגולי\u0004 \u0005[לחזור ולפגל]\u0006 \u0003ב\u0004פעם ה\u0003שלישית\u0004 במפורש \u0003למה לי?\u0004 אלא יש להניח שבמקרה זה לא התכוון לעשות את ההזאה השניה על דעת הזאה ראשונה, ולפיכך סבורים חכמים שאינו פיגול, מפני שלא פיגל בכל המתיר.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 על תירוץ זה \u0003רב אשי: מידי\u0004 \u0005[כלום]\u0006 \u0003שתק\u0004 בשניה \u0003קתני\u0004 \u0005[הוא שונה\u0006 שם\u0005]?\u0006 \u0003אלא אמר רב אשי: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003כגון שפיגל\u0004 גם \u0003בראשונה ו\u0004גם \u0003בשניה ו\u0004גם \u0003בשלישית,\u0004 שחזר ואמר בכל פעם שהוא עושה כן במחשבת חוץ לזמנו, ואת ההמשך עשה בשתיקה, \u0003דאמרינן\u0004 \u0005[שאומרים אנו]:\u0006 \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 שגם במקרה זה \u0003כל העושה על דעת ראשונה הוא עושה,\u0004 אם כן \u0003מיהדר פגולי\u0004 \u0005[לחזור ולפגל]\u0006 בה במפורש \u0003בשניה ובשלישית למה לי?\u0004"],["ומקשים: גם הסבר זה אינו עומד, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"בין\u0004 בראשונה \u0003בין\u0004 בשניה\" \u0003קתני\u0004 \u0005[הוא שונה],\u0006 משמע שגם אם חישב בכל אחת מהן פיגל, ולא רק בשלושתן יחד! ומעירים: אכן \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר.","ודנים בברייתא זו לגופה. \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: פיגל בהזאות של פר ושעיר יום הכיפורים, בין בהזאה ראשונה, בין בשניה ובין בשלישית, \u0003ר' מאיר אומר: פגול\u0004 הוא \u0003וחייבין עליו כרת.\u0004 ושואלים: \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003כרת לא מיחייב\u0004 \u0005[אינו חייב]\u0006 על אכילת פיגול \u0003עד שיקרבו כל המתירין,\u0004","\u0003דאמר מר\u0004 \u0005[החכם]:\u0006 נאמר בפיגול \"לא \u0003ירצה\"\u0004 (ויקרא ז, יח) — ללמד ש\u0003כהרצאת כשר,\u0004 כדרך שמרצה קרבן כשר שנאמר בו \"ירצה\" (שם כב, כז) — \u0003כך הרצאת פסול, מה הרצאת כשר\u0004 אינה מרצה \u0003עד שיקרבו כל המתירין\u0004 כראוי, \u0003אף הרצאת פסול\u0004 אינה עושה פיגול \u0003עד שיקרבו כל המתירין\u0004 כראוי (חוץ ממחשבת הפיגול עצמה).","\u0003והאי\u0004 \u0005[וזה],\u0006 הדם של הפר והשעיר של יום הכיפורים, \u0003כיון דחשיב\u0004 \u0005[שחישב]\u0006 \u0003בה\u0004 מחשבת חוץ לזמנו כשהיזה ממנו \u0003בפנים\u0004 בקדש הקדשים — הרי \u0003פסליה\u0004 \u0005[פסלו],\u0006 אם כן, \u0003כי מדי\u0004 \u0005[כאשר מזה]\u0006 אחר כך \u0003בהיכל\u0004 — \u0003מיא בעלמא הוא דקא מדי\u0004 \u0005[מים בלבד הוא שהוא מזה],\u0006 ולא דם הראוי להזאה, ונמצא שלא קרבו כל המתירים כראוי, וכיצד הוא נעשה פיגול?","\u0003אמר רבה: משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 \u0003בארבעה פרים וארבעה שעירים,\u0004 שלאחר שפיגל בהזאות שבפנים נשפך הדם, והוצרך להביא פר ושעיר אחרים ולהזות מדמם על הפרוכת, ופיגל בהם. ושוב נשפך הדם, והביא פר ושעיר להזאות על קרנות מזבח הזהב, ופיגל בהם. ונשפך הדם, והוצרך להביא עוד פר ושעיר להזאות על גגו של מזבח הזהב.","\u0003רבא אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמדובר ב\u0003פר אחד ושעיר אחד,\u0004 והדם שנותר נפסל, על כל פנים \u0003לפגולי מרצי\u0004 \u0005[ל\u0006ענין \u0005פיגול הוא מרצה]\u0006 כאילו השלים את כל העבודה כראוי.","עוד שנינו בברייתא שסך כל ההזאות ביום הכיפורים היה \u0003ארבעים ושלש\u0004 מתנות. ושואלים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ארבעים ושבע\u0004 מתנות היו שם! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 ששנינו בה ארבעים ושלוש, הרי היא \u0003כמאן דאמר\u0004 \u0005[כ\u0006דעת \u0005מי שאומר]\u0006 שלאחר שהיזה בפנים ועל הפרוכת \u0003מערבין\u0004 את דם הפר והשעיר \u0003ל\u0004צורך הזאה על ארבע \u0003קרנות\u0004 של מזבח הזהב, \u0003והא\u0004 \u0005[וזו]\u0006 ששנינו בה ארבעים ושבע, היא \u0003כמאן דאמר\u0004 \u0005[כ\u0006דעת \u0005מי שאומר]\u0006 ש\u0003אין מערבין,\u0004 אלא מזים מכל אחד בנפרד, ונמצא שיש ארבע הזאות נוספות.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 אחרת: \u0003ארבעים ושמונה\u0004 הזאות! ומסבירים: \u0003לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 ששנינו ארבעים ושמונה, היא \u0003כמאן דאמר\u0004 \u0005[כ\u0006דעת \u0005מי שאומר]:\u0006 \u0003שירים\u0004 של דם הפר והשעיר, שצריך לתת על יסוד מזבח החיצון, \u0003מעכבין\u0004 את העבודה, ואם כן יש עוד מתנת דם — שפיכת השיריים, \u0003הא\u0004 \u0005[זו]\u0006 ששנינו ארבעים ושבע היא \u0003כמאן דאמר\u0004 \u0005[כ\u0006דעת \u0005מי שאומר]\u0006 \u0003שירים לא מעכבין,\u0004 ויש רק ארבעים ושבע.","ביחס למה ששנו חכמים במשנתנו, שאם פיגל בחצי מתיר, וכגון שחישב בשעת הקטרת הקומץ לאכול את השיריים למחר, ולא חישב גם בשעת הקטרת הלבונה — אין זה פיגול, \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים: אם \u0003פיגל ב\u0004שעת \u0003הולכה\u0004 של הקומץ למזבח לשם הקטרה, ולא פיגל בשעת הולכת הלבונה, \u0003מהו\u0004 הדין?","\u0003אמר ר' יוחנן: הולכה\u0004 של הקומץ דינה \u0003כקמיצה\u0004 של הקומץ, שאם חישב בה פיגל, מפני שהיא נחשבת כמתיר שלם (שהרי אין קמיצה בלבונה). \u0003וריש לקיש אמר: הולכה\u0004 של הקומץ דינה \u0003כהקטרה\u0004 של הקומץ, שאין מפגלים בה כשלעצמה, כיון שיש גם הקטרה של הלבונה.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ריש לקיש\u0004 נחשב הדבר כמפגל בחצי מתיר, שהרי \u0003איכא נמי\u0004 \u0005[יש גם כן]\u0006 \u0003הולכה\u0004 של ה\u0003לבונה, אלא ל\u0004שיטת \u0003ר' יוחנן מאי טעמא\u0004 \u0005[מה הטעם]\u0006 שפיגל בהולכת הקומץ? והרי לא פיגל בכל ההולכה!","\u0003אמר רבא, קסבר\u0004 \u0005[סבור]\u0006 \u0003ר' יוחנן: כל עבודה\u0004 כגון הולכה, \u0003שאינה מתרת\u0004 כשלעצמה את הקרבן, אם עשאה אפילו באחד מן המתירים (כגון בקומץ ולא בלבונה) \u0003עבודה חשובה היא לפגל עליה בפני עצמה,\u0004 ואין זה כמפגל בחצי מתיר, שהרי אינה מתיר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: הרי שחיטת אחד מן הכבשים\u0004 של שתי הלחם בעצרת, שהשחיטה \u0003עבודה שאינה מתירתה\u0004 לא את הקרבת האימורים, ולא את אכילת הבשר ושתי הלחם, שהרי זריקת הדם היא המתירה אותם, \u0003ופליגי\u0004 \u0005[ו\u0006בכל זאת \u0005חלוקים\u0006 בה\u0005]\u0006 חכמים, וסבורים שהיא נחשבת חצי מתיר ואינה מפגלת כשלעצמה,","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003שחט אחד מן הכבשים לאכול שתי חלות למחר,\u0004 או \u0003הקטיר אחד מן הבזיכין לאכול שני סדרים למחר, ר' מאיר אומר: פגול וחייבין עליו כרת, וחכמים אומרים: אין בו כרת עד שיפגל בכל המתיר!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 ש\u0003לחם\u0004 כבר \u0003בתנור\u0004 נעשה \u0003קדוש,\u0004 ולא הוצרך אלא לזריקת הדם כדי להתירו? לא, \u0003שחיטת כבשים מקדשא ליה\u0004 \u0005[מקדשת אותו]\u0006 את הלחם, \u0003והבא לקדש,\u0004 כגון שחיטת הכבשים — \u0003כבא להתיר דמי\u0004 \u0005[נחשב],\u0006 ושחיטת כבש אחד נחשבת איפוא כחצי מתיר, ולכן אינה מפגלת לעצמה.","עוד \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב שימי בר אשי\u0004 ממה ששנינו בענין שחיטת קרבן הפסח, \u0003אחרים אומרים:\u0004 כששחט אחד מן הסימנים (קנה או ושט) במחשבה ראויה, ואחד במחשבת פסול, אם \u0003הקדים\u0004 מחשבה שיאכלו ממנו \u0003מולים ל\u0004מחשבה שיאכלו ממנו \u0003ערלים\u0004 (שהיא פוסלת) — הרי הוא \u0003כשר,\u0004 אם \u0003הקדים ערלים למולים\u0004 — \u0003פסול;\u0004","\u0003וקיימא לן\u0004 \u0005[ומוחזק בידינו]\u0006 שתנא קמא ואחרים \u0003ב\u0004עבודת \u0003חצי מתיר פליגי\u0004 \u0005[חלוקים הם],\u0006 האם היא פוסלת. והרי שחיטה זו לא באה לקדש דבר, ובכל זאת נחשבת שחיטת אחד הסימנים לחצי מתיר! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: אין זו קושיה, \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 ש\u0003דם\u0004 כבר \u0003בצואר בהמה קדוש?\u0004 לא, \u0003דם\u0004 — ה\u0003סכין מקדשא ליה\u0004 \u0005[מקדשת אותו],\u0006 \u0003והבא לקדש כבא להתיר דמי\u0004 \u0005[נחשב],\u0006 ונמצא ששחיטת סימן אחד היא כחצי מתיר.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו: \u0003במה דברים אמורים\u0004 שאם פיגל בקומץ ולא בלבונה הרי זה פיגול — \u0003בקמיצה ובמתן כלי ובהילוך;\u0004","\u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה ל\u0003הילוך\u0004 שמוליך את הקומץ ל\u0003הקטרה?\u0004 הרי שמפגלים בהולכת הקומץ לבדה, שלא כדברי ריש לקיש! ודוחים: \u0003לא,\u0004 הכוונה ל\u0003הילוך\u0004 של \u0003מתן כלי\u0004 שמוליך את הקומץ כדי לקדשו בכלי שרת, והוא עבודה שלימה, שאין מתן כלי בעבודת הלבונה.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 מדוע הוא שונה בסדר העבודות: \u0003\"במתן כלי ובהילוך\",\u0004 שמשמע שההילוך נעשה לאחר הנתינה בכלי, לצורך הקטרה? והלוא \u0003בהילוך ובמתן כלי מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 ומשיבים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006 \u0003תני הכי\u0004 \u0005[שנה כך],\u0006 תקן את נוסח הדברים: בהילוך ובמתן כלי.","ועוד מקשים: לפי דבריך, שהולכה של הקומץ לשם הקטרה דינה כהקטרה, ואין מפגלים עד שיפגל גם בלבונה, הרי מה ששנינו בהמשך: \u0003בא לו להקטרה\u0004 אינו פיגול עד שיפגל גם בלבונה — \u0003בא לו להולכה\u0004 ולהקטרה \u0003מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 ומשיבים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006 \u0003כיון\u0004 ש\u0003הולכה\u0004 זו \u0003צורך\u0004 של \u0003הקטרה היא, קרי לה\u0004 \u0005[קורא לה]\u0006 \u0003הקטרה\u0004 כלומר, זהו חלק מעבודת ההקטרה.","וחוזרים ומקשים: \u0003אלא\u0004 מה ששנינו שם: \u0003נתן את הקומץ בשתיקה\u0004 ואת הלבונה במחשבה וכו' — \u0003הוליך\u0004 את הקומץ בשתיקה ואת הלבונה במחשבה \u0003מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]\u0006 גם כן! ומעירים: אכן, דבר זה \u0003קשיא\u0004 \u0005[קשה].\u0006","ועוד בענייני פיגול למחצה: אם \u0003הקטיר\u0004 כשיעור \u0003שומשום\u0004 מן הקומץ ומן הלבונה במחשבה \u0003לאכול\u0004 כדי \u0003שומשום\u0004 מן השיריים שלא בזמנו, וכך הקטיר את הקומץ והלבונה מעט מעט במחשבה זו \u0003עד שכלה קומץ כולו\u0004 — \u0003רב חסדא ורב המנונא ורב ששת\u0004 נחלקו בזה, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 אם עשה כן הרי זה \u0003פיגול, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: פסול\u0004 הוא, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: כשר\u0004 הוא.","ומציעים, \u0003לימא\u0004 \u0005[\u0006האם \u0005נאמר]\u0006 כך: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שהוא \u0003פיגול\u0004 סבור \u0003כר' מאיר,\u0004 שמפגלים גם בעבודת מקצת המתיר, וכגון במשנתנו שחישב בהקטרת הקומץ בלבד לאכול את השיריים למחר, \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 שהוא \u0003פסול\u0004 סבור \u0003כרבנן\u0004 \u0005[כחכמים],\u0006 האומרים במשנתנו שאם פיגל בחצי מתיר אינו פיגול, אבל הוא פסול. \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 שהוא \u0003כשר\u0004 סבור \u0003כרבי\u0004 שאמר (לעיל מנחות יד,א) שהשוחט כל כבש מכבשי עצרת כדי לאכול חצי כזית מחלה אחרת הרי זה כשר, שאין חצאיה מצטרפים לשיעור פיגול?","ודוחים: \u0003ממאי\u0004 \u0005[ממה]\u0006 אתה מסיק זאת? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003עד כאן לא קאמר\u0004 \u0005[אומר]\u0006 \u0003ר' מאיר התם\u0004 \u0005[שם]\u0006 שמפגלים בעבודת חצי מתיר, \u0003אלא\u0004 כש\u0003חישב\u0004 \u0003בשיעורו\u0004 השלם של אכילה למחר, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 ש\u0003לא חישב בשיעורו,\u0004 אלא בכל פעם שהקטיר חישב לאכול כדי שומשום — \u0003לא! ו\u0004עוד, שמא","\u0003עד כאן לא קא אמרי רבנן התם\u0004 \u0005[לא אומרים חכמים שם]\u0006 שאין מפגלים בחצי מתיר, \u0003אלא\u0004 במקרה ש\u0003לא חישב ביה בכוליה\u0004 \u0005[בו בכל]\u0006 עבודת ה\u0003מתיר,\u0004 אלא רק בשעת הקטרת הקומץ, \u0003אבל הכא דחישב ביה בכוליה מתיר\u0004 \u0005[כאן שחישב בו במתיר כולו],\u0006 בשעת הקטרת הקומץ והלבונה, אף שחישב בכל פעם בהקטרת כמות קטנה — \u0003הכי נמי דפגיל\u0004 \u0005[כך גם כן\u0006 יש לומר \u0005שפיגל]!\u0006","\u0003ו\u0004עוד, שמא \u0003עד כאן לא קא אמר\u0004 \u0005[לא אומר]\u0006 \u0003רבי התם\u0004 \u0005[שם]\u0006 שהוא כשר כשחישב על חצי כזית מכל חלה, \u0003אלא\u0004 במקרה \u0003דלא הדר מלייה\u0004 \u0005[שלא חזר ומילא אותו]\u0006 במחשבתו את שיעור האכילה לכזית \u0003מאותה עבודה\u0004 עצמה, שהרי בעבודת כל כבש חישב רק על כחצי זית, \u0003אבל הכא דהדר מלייה\u0004 \u0005[כאן שחזר ומילא אותו]\u0006 את שיעור האכילה \u0003מאותה עבודה\u0004 עצמה, שבסיכומו של דבר חישב בהקטרה על אכילה בשיעור המחייב — \u0003הכי נמי דפסיל\u0004 \u0005[כך גם כן\u0006 יש לומר \u0005שפוסל]!\u0006","\u0003אלא\u0004 צריך להסביר את המחלוקת באופן אחר: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שהמקטיר כדי שומשום כדי לאכול כדי שומשום הרי זה \u0003פיגול\u0004 — ל\u0003דברי הכל\u0004 הוא פיגול, וכן \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003פסול\u0004 — \u0003דברי הכל\u0004 הוא פסול, וכן \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003כשר\u0004 — ל\u0003דברי הכל\u0004 הוא כשר.","ומסבירים: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שהוא \u0003פיגול\u0004 ל\u0003דברי הכל, קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003דרך אכילה בכך\u0004 מעט מעט, \u0003ו\u0004גם \u0003דרך הקטרה בכך. ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003פסול\u0004 ל\u0003דברי הכל, קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003אין דרך אכילה בכך\u0004 במעט מעט, ולכן אין במחשבה לאכול באופן זה משום פיגול, \u0003ו\u0004אולם גם \u0003אין דרך הקטרה בכך, והואי לה\u0004 \u0005[והרי היא]\u0006 איפוא \u0003כמנחה שלא הוקטרה\u0004 כראוי, ולא הותרה לכהנים, ולכן היא פסולה. \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003כשר\u0004 ל\u0003דברי הכל, קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003דרך הקטרה בכך,\u0004 והקטרה ראויה היא, \u0003ו\u0004אולם \u0003אין דרך אכילה בכך,\u0004 ולכן אין זו מחשבת פיגול.","\u0003אמרי\u0004 \u0005[אמרו]\u0006"],["\u0003חריפי דפומבדיתא\u0004 \u0005[החריפים של פומבדיתא]:\u0006 \u0003הקטרה מפגלת הקטרה,\u0004 וכגון שאם הקטיר קומץ על מנת להקטיר לבונה למחר — הרי המנחה פיגול. \u0003ואפילו לרבנן דאמרי\u0004 \u0005[ל\u0006דעת \u0005חכמים שאומרים]\u0006 במשנתנו: \u0003אין מפגלין בחצי מתיר,\u0004 שאם פיגל בשעת עבודת הקומץ בלבד אין זה פיגול — \u0003הני מילי היכא דחישב ביה\u0004 \u0005[דברים אלה\u0006 אמורים \u0005במקום שחישב בו]\u0006 \u0003בשירים\u0004 לאוכלם למחר, \u0003ולבונה במילתא קיימא\u0004 \u0005[בעינה עומדת],\u0006 שלא חישב בה כלל. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 שבשעת הקטרת הקומץ \u0003חישב לה בלבונה\u0004 — \u0003כמה דחישב ביה בכוליה\u0004 \u0005[כמו שחישב בו בכל]\u0006 ה\u0003מתיר דמי\u0004 \u0005[נחשב].\u0006","\u0003אמר רבא: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 במשנה שהקטרה מפגלת הקטרה, \u0003זה הכלל: כל הקומץ ו\u0004כן ה\u0003נותן\u0004 את הקומץ \u0003בכלי, והמוליך והמקטיר,\u0004 על מנת \u0003לאכול דבר שדרכו לאכול ולהקטיר דבר שדרכו להקטיר, חוץ למקומו\u0004 — \u0003פסול ואין בו כרת,\u0004 על מנת לאכול או להקטיר \u0003חוץ לזמנו\u0004 — \u0003פגול וחייבין עליו כרת.\u0004","\u0003מאי לאו\u0004 \u0005[האם אין]\u0006 דינה של \u0003הקטרה\u0004 שהוזכרה שם \u0003דומיא דהנך\u0004 \u0005[בדומה לאלה\u0006 האחרים\u0005],\u0006 קמיצה ומתן בכלי והולכה? \u0003מה הנך\u0004 \u0005[אלה]\u0006 \u0003בין\u0004 שחישב בהם \u0003לאכול\u0004 שיריים למחר, \u0003בין\u0004 שחישב בהם \u0003להקטיר\u0004 לבונה למחר — מפגל, \u0003אף הקטרה בין\u0004 שחישב בה על מנת \u0003לאכול\u0004 מהשיריים למחר, \u0003בין\u0004 שהתכוון \u0003להקטיר\u0004 את הלבונה למחר, פיגל?","ודוחים: \u0003לא,\u0004 יש לפרש כי \u0003הנך\u0004 \u0005[אלה],\u0006 קמיצה ומתן בכלי והילוך, מפגל בהם \u0003בין\u0004 שחישב בהם \u0003לאכול\u0004 שיריים למחר \u0003בין להקטיר\u0004 לבונה למחר, אבל \u0003הקטרה,\u0004 אם חישב בה \u0003לאכול\u0004 שיריים למחר — \u0003אין\u0004 \u0005[כן]\u0006 הרי הוא מפגל, אם חישב \u0003להקטיר\u0004 לבונה למחר — \u0003לא.\u0004","מסופר, \u0003יתיב\u0004 \u0005[יושב\u0006 היה\u0005]\u0006 \u0003רב מנשיא בר גדא קמיה\u0004 \u0005[לפני]\u0006 \u0003אביי, ויתיב וקא אמר משמיה\u0004 \u0005[ויושב\u0006 היה \u0005ואומר משמו]\u0006 של \u0003רב חסדא: אין הקטרה\u0004 של קומץ \u0003מפגלת הקטרה\u0004 של לבונה. \u0003ואפילו ל\u0004שיטת \u0003ר' מאיר\u0004 ש\u0003אמר\u0004 במשנתנו: \u0003מפגלין בחצי מתיר,\u0004 שאם פיגל בקומץ ולא בלבונה הרי פיגול — \u0003הני מילי היכא\u0004 \u0005[דברים אלה\u0006 אמורים \u0005במקום]\u0006 ש\u0003חישב בהו\u0004 \u0005[בהם]\u0006 \u0003בשירים,\u0004 שה\u0003קומץ\u0004 הוא \u0003מתיר דידהו\u0004 \u0005[שלהם],\u0006 \u0003אבל הכא\u0004 \u0005[כאן]\u0006 ש\u0003קומץ לאו\u0004 \u0005[אינו]\u0006 \u0003מתיר\u0004 של \u0003לבונה הוא\u0004 — \u0003לא מצי מפגל ביה\u0004 \u0005[אינו יכול לפגל בו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב מנשיא: \u0003עני מרי\u0004 \u0005[ענה אדוני],\u0006 האם דברים אלה שאמר רב חסדא, אמרם \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב\u0004 רבו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006 ומעירים, \u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 במפורש, \u0003אמר רב חסדא אמר רב: אין הקטרה מפגלת הקטרה.\u0004","","","\u0003אמר רב יעקב בר אידי משמיה\u0004 \u0005[משמו]\u0006 של \u0003אביי: אף אנן נמי תנינא\u0004 \u0005[אף אנו גם כן שנינו]\u0006 במשנה כדברי רב: \u0003שחט אחד מן הכבשים\u0004 של עצרת \u0003לאכול ממנו למחר\u0004 — הכבש הזה \u0003הוא פיגול וחבירו כשר,\u0004 על מנת \u0003לאכול מחבירו למחר\u0004 — \u0003שניהם כשרין; מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003משום\u0004 ש\u0003כיון דלאו\u0004 \u0005[שלא]\u0006 \u0003מתיר דידיה\u0004 \u0005[שלו]\u0006 \u0003הוא\u0004 הכבש השני, לכן \u0003לא מצי מפגל ביה\u0004 \u0005[אינו יכול לפגל בו]?\u0006 ומכאן נלמד גם לענין הקומץ והלבונה! ודוחים: \u0003לא,\u0004 אפשר לחלק, \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 שאין כבש מפגל את חבירו משום \u0003דלא איקבע בחד מנא\u0004 \u0005[שלא נקבע\u0006 אתו להקרבה \u0005בכלי אחד],\u0006 שהרי כל כבש עומד לעצמו, \u0003אבל הכא דאיקבע בחד מנא\u0004 \u0005[כאן שנקבע\u0006 הקומץ והלבונה \u0005בכלי אחד]\u0006 לשם הקרבה — \u0003כי חד דמו\u0004 \u0005[כמו\u0006 דבר \u0005אחד נחשבים],\u0006 ולכן זה מפגל את זה.","","ובענין זה \u0003אמר רב המנונא: הא מילתא אבלע\u0004 \u0005[דבר זה הבליע]\u0006 \u0003לי ר' חנינא,\u0004 למדני היטב, \u0003ותקילא לי ככוליה תלמודאי\u0004 \u0005[ושקול לי,\u0006 חביב בעיני, \u0005ככל תלמודי]\u0006 מפני שיש בו חידוש גדול: אם \u0003הקטיר\u0004 את ה\u0003קומץ\u0004 על מנת \u0003להקטיר לבונה\u0004 למחר, \u0003ו\u0004את ה\u0003לבונה\u0004 הקטיר על מנת \u0003לאכול שירים למחר\u0004 — הרי זה \u0003פגול.\u0004 ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה\u0006 בדיוק \u0005הוא משמיע לנו\u0006 בכך\u0005]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003הקטרה מפגלת הקטרה קא משמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 — \u0003לימא\u0004 \u0005[שיאמר]\u0006 רק: \u0003הקטיר קומץ\u0004 על מנת \u0003להקטיר לבונה\u0004 הרי זה פיגול! \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003מפגלין ב\u0004עבודת \u0003חצי מתיר קא משמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 — \u0003לימא\u0004 \u0005[שיאמר]\u0006 רק: \u0003הקטיר קומץ לאכול שירים למחר\u0004 הרי זה פיגול! \u0003אי תרוייהו אתא קא משמע לן\u0004 \u0005[אם שניהם\u0006 הוא \u0005בא להשמיע לנו],\u0006 \u0003לימא\u0004 \u0005[שיאמר]:\u0006 \u0003הקטיר קומץ להקטיר לבונה ולאכול שירים למחר!\u0004","","\u0003אמר רב אדא בר אהבה,\u0004 \u0003לעולם קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003אין הקטרה מפגלת הקטרה,\u0004 ואם רק היה מקטיר קומץ על מנת להקטיר לבונה למחר — לא היה בזה פיגול, \u0003ו\u0004כן סבור הוא ש\u0003אין מפגלין ב\u0004עבודת \u0003חצי מתיר,\u0004 ואם רק היה מקטיר את הקומץ לאכול שיריים למחר — לא היה זה פיגול, \u0003ושאני הכא\u0004 \u0005[ושונה כאן]\u0006 במקרה שהזכיר כאן, \u0003דפשטא ליה\u0004 \u0005[שפשטה לה]\u0006 \u0003מחשבה\u0004 של חוץ לזמנו \u0003בכולה מנחה,\u0004 שהרי חישב בשעת הקטרת הקומץ על הקטרת הלבונה, ובשעת הקטרת הלבונה חישב על השיריים. \u0003מסופר,\u0004 \u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003רב יצחק בר אבא: הקטיר קומץ\u0004 על מנת \u0003לאכול שירים\u0004 למחר — \u0003לדברי הכל פגול\u0004 הוא. ותוהים: כיצד אפשר לומר שהוא כדברי הכל? \u0003והא מיפלג פליגי\u0004 \u0005[והרי חלוקים הם בכך]\u0006 ר' מאיר וחכמים במשנה! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 כך: \u0003לדברי הכל פסול\u0004 הוא, שאף חכמים מודים שמחשבה בעבודת חצי מתיר פוסלת את הקרבן, למרות שאינה מפגלת.","","ושואלים: אם אנו מתקנים את נוסח הברייתא, אפשר לתקן אחרת, \u0003ולימא\u0004 \u0005[ושיאמר]:\u0006 \u0003הרי זה פגול, ו\u0004שיטת \u0003ר' מאיר היא!\u0004 ומשיבים: מסתבר כי ה\u0003תנא \"דברי הכל\" אתניוה\u0004 \u0005[שנו לו],\u0006 והביטוי \u0003\"פיגול\" ב\"פסול\" מיחלף ליה\u0004 \u0005[מתחלף לו],\u0006 שאפשר לטעות בדבר, אבל \u0003\"הרי זה\" ב\"דברי הכל\" לא מיחלף ליה\u0004 \u0005[אינו מתחלף לו].\u0006","\u0003הקומץ את המנחה\u0004 על מנת \u0003לאכול\u0004 חוץ לזמנו \u0003דבר שאין דרכו לאכול,\u0004 או \u0003להקטיר\u0004 חוץ לזמנו \u0003דבר שאין דרכו להקטיר\u0004 — הרי זה \u0003כשר,\u0004 ואילו \u0003ר' אליעזר פוסל\u0004 בכך, אף על פי שגם הוא מסכים שאין זה פיגול לחייב על אכילתו כרת.","קמץ על מנת \u0003לאכול\u0004 למחר \u0003דבר שדרכו לאכול, ו\u0004כן \u0003להקטיר\u0004 חוץ לזמנו \u0003דבר שדרכו להקטיר\u0004 אבל \u0003פחות מכזית,\u0004 שהוא שיעור אכילה והקטרה — הרי זה \u0003כשר.\u0004 וכן אם קמץ על מנת \u0003לאכול\u0004 חוץ לזמנו \u0003כחצי זית ולהקטיר כחצי זית\u0004 — \u0003כשר,\u0004 משום \u0003שאין אכילה והקטרה מצטרפין.\u0004 \u0003אמר ר' אסי אמר ר' יוחנן: מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' אליעזר\u0004 שסבור כי אם חישב לאכול דבר שאין דרכו לאכול חוץ לזמנו הרי זה פסול? \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 בענין פיגול בלשון כפולה: \u0003\"ואם האכל יאכל מבשר זבח שלמיו\"\u0004 (ויקרא ז, יח) — \u0003בשתי אכילות הכתוב מדבר, אחד אכילת אדם ואחד אכילת מזבח\u0004 (שאש המזבח אוכלת את המוקרב על גביו), \u0003לומר לך: כשם שמחשבין\u0004 ופוסלים על ידי כך \u0003באכילת אדם\u0004 — \u0003כך מחשבין באכילת מזבח, ו\u0004עוד הוא למד מכאן: \u0003כשם שמחשבין מאכילת אדם לאכילת אדם ו\u0004מחשבים \u0003מאכילת מזבח לאכילת מזבח,\u0004 שאם חישב לאכול למחר דבר שדרכו לאכול, ולהקטיר למחר דבר שדרכו להקטיר הרי זה פוסל — \u0003כך מחשבין מאכילת אדם למזבח\u0004 \u0003ומאכילת מזבח לאדם,\u0004 שאם חישב להקטיר למחר דבר שדרכו לאכול, או לאכול למחר דבר שדרכו להקטיר — הרי זה פוסל. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 מדוע הוא מגיע למסקנה זו? \u0003מדאפקינהו רחמנא\u0004 \u0005[מפני שהוציאה,\u0006 ביטאה, \u0005התורה]\u0006 את ענין ה\u0003הקטרה בלשון אכילה,\u0004 ובכך באה התורה לדמותם זה לזה.","","","","","ומעירים, \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שאינם סבורים כן מסבירים כך: \u0003האי דאפקינהו רחמנא\u0004 \u0005[זה שהוציאה,\u0006 ביטאה \u0005אותם, התורה]\u0006 \u0003בלשון אכילה,\u0004"],["בא ללמדנו ענין אחר, \u0003דלא שנא כי\u0004 \u0005[שאינו שונה כאשר]\u0006 הוא \u0003מחשב בלשון אכילה למזבח,\u0004 כגון: \"על מנת שיאכל המזבח את הקומץ למחר\", \u0003ולא שנא כי\u0004 \u0005[ואינו שונה כאשר]\u0006 הוא \u0003מחשב\u0004 \u0003בלשון הקטרה למזבח,\u0004 שאומר: \"על מנת להקטיר את הקומץ על המזבח למחר\" — הרי זה פיגול.","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 חידוש אחר בא להשמיענו: \u0003מה אכילה\u0004 שמחשב עליה שיעורה \u0003בכזית\u0004 כדי לחייב עליה משום פיגול, שסתם אכילה שיעורה בכזית — \u0003אף הקטרה\u0004 שמחשב עליה שיעורה \u0003בכזית. ולעולם אכילה דאורחא\u0004 \u0005[כדרכה]\u0006 \u0003משמע,\u0004 שמחשב שיאכל אדם דבר שדרכו לאכול, או שיאכל המזבח דבר העומד לאכילת מזבח.","\u0003ור' אליעזר,\u0004 מה הוא עונה על כך? \u0003אם כן,\u0004 לשם לימוד זה בלבד, \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 לשון \u0003\"אם האכל האכל\", אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003\"אם יאכל יאכל\", מאי\u0004 \u0005[מהו]\u0006 \u0003\"האכל יאכל\"\u0004 בשינוי? \u0003שמעת מינה תרתי\u0004 \u0005[לומד אתה מזה שתיים],\u0006 שמחשבים בלשון אכילה למזבח, ובשיעור כזית, וכן שמחשבים מאכילת מזבח לאדם ומאכילת אדם למזבח.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לרב אסי: ואי טעמא\u0004 \u0005[ואם טעמו]\u0006 של \u0003ר' אליעזר משום הכי\u0004 \u0005[כך]\u0006 \u0003הוא,\u0004 שהוא למד מלשון הכתוב שמחשבים מאכילת אדם לאכילת מזבח ולהיפך, מדוע הוא רק פוסל? \u0003כרת נמי ליחייב\u0004 \u0005[גם כן יתחייב]\u0006 על כך, כפיגול גמור! \u0003וכי תימא הכי נמי\u0004 \u0005[ואם תאמר כך\u0006 הוא \u0005גם כן],\u0006 \u0003והא את הוא דאמרת משמיה\u0004 \u0005[והרי אתה\u0006 עצמך \u0005הוא שאמרת משמו]\u0006 של \u0003ר' יוחנן: מודה ר' אליעזר שאין ענוש כרת!\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 באמת, \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא אליבא\u0004 \u0005[על פי\u0006 שיטתו\u0005]\u0006 של \u0003ר' אליעזר, איכא למאן דאמר\u0004 \u0005[יש מי שאומר]:\u0006 \u0003פסולה דאורייתא\u0004 \u0005[מן התורה],\u0006 וחייב על כך כרת, ולשיטתו הביא ר' יוחנן לעיל את המקור מן הכתוב. \u0003ואיכא למאן דאמר\u0004 \u0005[ויש מי שסבור]:\u0006 \u0003פסולה\u0004 רק \u0003דרבנן\u0004 \u0005[מ\u0006דברי \u0005סופרים],\u0006 ולשיטתו אמר ר' יוחנן שאינו חייב כרת.","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003השוחט את הזבח\u0004 על מנת \u0003לשתות מדמו למחר,\u0004 שמחשב מאכילת מזבח לאדם, או על מנת \u0003להקטיר מבשרו\u0004 העומד לאכילה \u0003למחר,\u0004 שמחשב מאכילת אדם למזבח, או על מנת \u0003לאכול מאימוריו למחר\u0004 — הרי זה \u0003כשר,\u0004 שמחשב מאכילת מזבח לאדם, \u0003ור' אליעזר פוסל.\u0004 חישב \u0003להניח מדמו למחר\u0004 ולא לעשות בו דבר — \u0003ר' יהודה פוסל. אמר ר' אלעזר: אף בזו ר' אליעזר פוסל וחכמים מכשירין.\u0004","ויש לשאול: \u0003ר' יהודה,\u0004 שפוסל במחשב להניח מן הדם למחר, \u0003אליבא דמאן\u0004 \u0005[על פי\u0006 שיטתו \u0005של מי]\u0006 הוא אומר? \u0003אילימא אליבא דרבנן\u0004 \u0005[אם תאמר על פי\u0006 שיטתם של חכמים], האומרים שאם חישב לשתות מן הדם למחר הרי זה כשר — לא ייתכן הדבר, שכן \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003ומה התם דקא\u0004 \u0005[שם שהוא]\u0006 \u0003מחשב\u0004 \u0003בלשון אכילה\u0004 (שתיה) בכל זאת \u0003מכשרי רבנן\u0004 \u0005[מכשירים חכמים],\u0006 למרות שאם היה מחשב בלשון זו למזבח היה זה פיגול, \u0003הכא\u0004 \u0005[כאן]\u0006 שהוא מחשב להניח — \u0003לא כל שכן\u0004 שהוא כשר?","\u0003אלא\u0004 בהכרח אומר כן ר' יהודה \u0003אליבא\u0004 \u0005[לפי\u0006 שיטתו\u0005]\u0006 של \u0003ר' אליעזר. ו\u0004קשה הדבר, שהרי מיד לאחר מכן \u0003אמר ר' אלעזר: אף בזו ר' אליעזר פוסל וחכמים מכשירין,\u0004 ולפי הסבר זה, \u0003ר' אלעזר\u0004 בשיטת ר' אליעזר \u0003היינו\u0004 \u0005[הרי זו]\u0006 בדיוק שיטת \u0003ר' יהודה\u0004 לשיטתו, ואין מחלוקת ביניהם!","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 לגבי איסור \u0003כרת\u0004 שיש בדבר \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל, ש\u0003ר' יהודה דתנא קמא סבר\u0004 \u0005[ל\u0006שיטתו \u0005של התנא הראשון סבור]:\u0006 אם הוא מחשב \u0003להניח\u0004 מן הדם למחר — \u0003פסולא בעלמא\u0004 \u0005[פסול בלבד\u0006 הוא\u0005],\u0006 לדברי ר' אליעזר, ואילו \u0003בהנך\u0004 \u0005[באלה]\u0006 ששנו מתחילה, כגון לאכול מאימוריו למחר — \u0003כרת נמי מיחייב\u0004 \u0005[גם כן חייב],\u0006 \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' אלעזר למימר\u0004 \u0005[לומר]:\u0006 \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 \u0003פסול ואין בו כרת\u0004 לשיטת ר' אליעזר!","ודוחים: \u0003לא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003כרת ליכא\u0004 \u0005[אין]\u0006 לדעת ר' אליעזר במחשב מאכילת מזבח לאדם ומאכילת אדם למזבח, \u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003שלש מחלוקת\u0004 (דעות חלוקות) יש \u0003בדבר, תנא קמא סבר\u0004 \u0005[התנא הראשון סבור]:\u0006 דווקא \u0003בהנך פליגי\u0004 \u0005[באלה הם חלוקים],\u0006 כשמחשב מאכילת מזבח לאדם ומאכילת אדם למזבח, ובזה ר' אליעזר פוסל. אבל אם חישב \u0003להניח\u0004 מן הדם למחר — \u0003דברי הכל כשר,\u0004 וגם לדעת ר' אליעזר, שאין מחשבת פיגול אלא באכילת אדם או מזבח."],["\u0003ור' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003בהנך פליגי\u0004 \u0005[באלה הם חלוקים],\u0006 במחשב לשתות מדמו או להקטיר מבשרו, שחישב שלא כדרכו, ובזה חכמים מכשירים, אבל אם חישב \u0003להניח\u0004 למחר מקצת דמו — \u0003דברי הכל פסול, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003גזירה\u0004 להניח \u0003מקצת דמו אטו\u0004 \u0005[משום]\u0006 \u0003כל דמו, ו\u0004אם חישב להניח את \u0003כל דמו\u0004 למחר הרי זה \u0003פסולא דאורייתא\u0004 \u0005[פסול מן התורה],\u0006","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר להם ר' יהודה: אי אתם מודים לי שאם הניחו למחר\u0004 ולא היזה דמו כלל \u0003שפסול?\u0004 הואיל וכך אם \u0003חישב להניחו למחר נמי\u0004 \u0005[גם כן]\u0006 \u0003פסול.\u0004","\u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' אלעזר למימר\u0004 \u0005[לומר]:\u0006 \u0003אף בזו,\u0004 כלומר, בין במחשב לשתות מקצת דמו למחר ובין להניח מקצת דמו למחר, \u0003ר' אליעזר פוסל וחכמים מכשירין.\u0004","ושואלים: \u0003ו\u0004כי \u0003סבר\u0004 \u0005[סבור]\u0006 \u0003ר' יהודה\u0004 שאם התכוון \u0003להניח מדמו למחר דברי הכל פסול? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר רבי: כשהלכתי למצות מדותי,\u0004 כלומר, לסכם ולברר כל מה שלמדתי \u0003אצל ר' אלעזר בן שמוע, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 בנוסח אחר: כשהלכתי \u0003למצות מדותיו של ר' אלעזר בן שמוע\u0004 כלומר, ללמוד ולסכם את תורתו, \u0003מצאתי\u0004 את \u0003יוסף הבבלי יושב לפניו\u0004 לפני ר' אלעזר, ושואלו ולומד מפיו, \u0003והיה חביב לו ביותר\u0004 ליוסף הבבלי מה שהשיבו \u0003עד\u0004 שהגיעו \u0003ל\u0004הלכה \u0003אחת,\u0004 וכך \u0003אמר לו\u0004 יוסף הבבלי: \u0003רבי, השוחט את הזבח\u0004 על מנת \u0003להניח מדמו למחר, מהו?\u0004","\u0003אמר לו: כשר.\u0004 חזר ושאל אותו \u0003ערבית\u0004 אותה שאלה, \u0003אמר לו: כשר.\u0004 חזר ושאלו ב\u0003שחרית\u0004 למחרת, \u0003אמר לו: כשר.\u0004 ושוב שאלו ב\u0003צהרים, אמר לו: כשר.\u0004 כשחזר ושאלו ב\u0003מנחה\u0004 (לפנות ערב), \u0003אמר לו\u0004 ר' אלעזר: \u0003כשר, אלא שר' אליעזר פוסל. צהבו\u0004 (האירו) \u0003פניו של יוסף הבבלי\u0004 משמחה.","\u0003אמר לו\u0004 ר' אלעזר: \u0003יוסף, כמדומה אני שלא כיווננו שמועתינו עד עתה,\u0004 שכנראה לא הסכמת לדעתי עד עכשיו, עד שאמרתי שיש בכך פסול. \u0003אמר לו: רבי, הן\u0004 \u0005[כן]!\u0006 כשר הוא, כדבריך, \u0003אלא שר' יהודה פסול שנה לי\u0004 בענין זה, \u0003וחזרתי על כל תלמידיו ובקשתי לי חבר\u0004 ששמע דבר בענין זה מפיו, \u0003ולא מצאתי,\u0004 וסבור הייתי שטעות היא בידי, \u0003עכשיו ששנית לי\u0004 בשם ר' אליעזר שהוא \u0003פסול\u0004 \u0003החזרת לי אבידתי,\u0004 מצאתי מה שביקשתי.","\u0003זלגו עיניו דמעות של ר' אלעזר בן שמוע\u0004 מרוב התרגשות, \u0003אמר: אשריכם תלמידי חכמים שדברי תורה חביבין עליכם ביותר,\u0004 שהיה יוסף הבבלי שואל וחוזר ושואל כדי לברר מה שלמד. \u0003קרא עליו\u0004 ר' אלעזר \u0003המקרא הזה: \"מה אהבתי תורתך כל היום היא שיחתי\" וגו'\u0004 (תהלים קיט, צז), והוסיף: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מפני שר' יהודה\u0004 הוא \u0003בנו של ר' אלעאי, ור' אלעאי\u0004 היה \u0003תלמידו של ר' אליעזר, לפיכך שנה לך\u0004 ר' יהודה \u0003משנת ר' אליעזר\u0004 שהוא פוסל.","ומעתה לענייננו, \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 שהשוחט על מנת להניח מדמו למחר, ל\u0003דברי הכל פסול אתנייה\u0004 \u0005[שנה לו]\u0006 ר' יהודה ליוסף הבבלי, כפי שהסברנו את דעת ר' יהודה בברייתא, אם כן \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 מה שאמר יוסף הבבלי לר' אלעזר בן שמוע \u0003\"החזרת לי אבידתי\"?\u0004 הלוא \u0003איהו פלוגתא קאמר ליה\u0004 \u0005[הוא,\u0006 ר' אלעזר בן שמוע, \u0005מחלוקת אמר לו]\u0006 שרק ר' אליעזר סבור כן, ואין זה דברי הכל!","ומקשים לצד שני: \u0003אלא מאי\u0004 \u0005[מה\u0006 אתה אומר\u0005],\u0006 שלדברי חכמים \u0003כשר ור' אליעזר (פסול) פוסל אתנייה\u0004 \u0005[שנה לו]\u0006 ר' יהודה ליוסף הבבלי? \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003מאי\u0004 \u0005[מהו]\u0006 שאמר ר' אלעזר בן שמוע: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מפני\u0004 שר' יהודה היה תלמיד תלמידו של ר' אליעזר שנה לך שיש בכך \u0003פלוגתא\u0004 \u0005[מחלוקת]?\u0006 והלוא לדברי ר' אלעזר בן שמוע \u0003אנן נמי פלוגתא קא מתנינן\u0004 \u0005[אנו גם כן מחלוקת אנו שונים]\u0006 בזה!","\u0003אלא, לעולם \"דברי הכל פסול\" אתנייה\u0004 \u0005[שנה לו]\u0006 ר' יהודה ליוסף הבבלי, \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0003]\u0004 \u0003\"החזרת לי אבידתי\"?\u0004 לא שאמר לו ר' אלעזר ממש כפי ששמע מפיו של ר' יהודה, שהרי אמר לו שיש מחלוקת בדבר, אלא \u0003דהדר ליה מיהא\u0004 \u0005[שהחזיר לו על כל פנים]\u0006 \u0003שום\u0004 (שם) \u0003פסלות בעולם,\u0004 שיש מי שסבור כפי ששמע מרבו, שאם שחט על מנת להניח דמו למחר הרי זה פסול.","\u0003לא יצק\u0004 שמן על המנחה, או \u0003לא בלל\u0004 את המנחה בשמן, או \u0003לא פתת\u0004 אותה לפתיתים, \u0003ו\u0004כן אם \u0003לא מלח\u0004 אותה, או \u0003לא הניף\u0004 את מנחת העומר ומנחת הקנאות, או \u0003לא הגיש\u0004 את המנחה לקרן המזבח קודם הקמיצה, \u0003או שפתתן\u0004 את המנחות הטעונות פתיתה ל\u0003פתים מרובות,\u0004 גדולות מן השיעור הראוי, \u0003או\u0004 \u0003לא משחן\u0004 בשמן את הרקיקים הטעונים משיחה (ראה ויקרא ב, ד) — בכל המקרים האלה המנחה \u0003כשירה.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003לא יצק,\u0004 שהוא כשר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003לא יצק\u0004 שמן \u0003כלל,\u0004 הלוא \u0003עיכובא כתב\u0004 \u0005[עיכוב כתוב]\u0006 \u0003בה\u0004 ביציקה, ואם אינו יוצק הריהו פסול! \u0003אלא\u0004 בהכרח הכוונה היא ש\u0003לא יצק כהן אלא\u0004 יצק \u0003זר.\u0004 ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, \u0003לא בלל נמי\u0004 \u0005[גם כן]\u0006 תפרש: \u0003לא בלל כהן אלא זר,\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[אבל]\u0006 אם \u0003לא בלל כלל\u0004 — \u0003פסולה.\u0004"],["ומתקשים, \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 המתנדב מנחה של ששים ואחד עשרונים צריך להביא ששים עשרונים בכלי אחד, ועשרון אחד בכלי אחר, וטעם הדבר, מפני ש\u0003ששים\u0004 עשרונים \u0003נבללין\u0004 בלוג אחד של שמן, \u0003ששים ואחד אין נבללין\u0004 כראוי. \u0003והוינן\u0004 \u0005[והיינו עוסקים,\u0006 מתקשים\u0005]\u0006 \u0003בה: כי\u0004 \u0005[\u0006גם \u0005כאשר]\u0006 \u0003אינם נבללין מאי הוי\u0004 \u0005[מה בכך]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה שלנו\u0005]:\u0006 \u0003לא בלל\u0004 — \u0003כשרה!\u0004","\u0003ואמר ר' זירא\u0004 בהסבר הדבר: \u0003כל הראוי לבילה\u0004 (לבלילה) \u0003אין בילה\u0004 בפועל \u0003מעכבת בו, וכל שאינו ראוי לבילה\u0004 שאי אפשר לבלול אותו — \u0003בילה מעכבת בו.\u0004 ומכאן משמע ש\"לא בלל\" האמור במשנה פירושו: לא בלל כלל, והוא הדין למה ששנינו \"לא יצק\", שלא כפי שפירשנו לעיל!","ודוחים: \u0003מידי איריא\u0004 \u0005[כלום הדברים שייכים]?\u0006 \u0003הא כדאיתא והא כדאיתא\u0004 \u0005[זה כמו שהוא וזה כמו שהוא],\u0006 \u0003לא יצק\u0004 כוונתו — \u0003לא יצק כהן אלא זר, לא בלל\u0004 כוונתו — \u0003לא בלל כלל.\u0004","שנינו במשנה: \u0003או שפתתן פתים מרובות\u0004 (גדולות). שצריך לכפול כל אחת מן החלות לארבע, ובכל פתית כזית, והוא פתת לפתיתים גדולים יותר — \u0003כשרה.\u0004 ותוהים: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 אם \u0003לא פתת כלל כשרה,\u0004 אם פתת \u0003פתין מרובות מיבעיא\u0004 \u0005[נצרכה\u0006 \u0003לומר]\u0004 שהיא כשרה? ומשיבים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003פתין מרובות? שריבה בפתיתין,\u0004 כלומר, שהרבה במספר הפתיתים, שפתתן לפתיתים קטנים מדי, פחותים מכזית.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם\u0004 כוונת המשנה ל\u0003פתים מרובות ממש,\u0004 גדולות. \u0003ומהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 כשלא פתת כלל, \u0003הוא\u0004 שכשירה, מפני \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003תורת חלות עליהן, אבל הכא\u0004 \u0005[כאן]\u0006 שפתתן לפתיתים גדולים מן הראוי, \u0003ש\u0004\u0003לא תורת חלות איכא\u0004 \u0005[יש],\u0006 שהרי הן פתותות, \u0003ולא תורת פתיתין איכא\u0004 \u0005[יש],\u0006 שהן גדולות מדי, \u0003אפשר היה לומר שהיא פסולה, לכן\u0004 \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שגם זה אינו פוסל.","בעקבות מה שפירשה הגמרא, שמה ששנינו שאם לא יצק המנחה כשרה, מובנו שלא יצק כהן אלא זר, מתקשים: \u0003לימא מתניתין\u0004 \u0005[האם נאמר שמשנתנו]\u0006 המניחה שקמיצה כשרה בזר, היא ש\u0003לא כ\u0004דעת \u0003ר' שמעון? דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון אומר: כל כהן שאינו מודה בעבודה\u0004 שאינו מאמין בה — \u0003אין לו חלק ב\u0004מתנות \u0003כהונה, שנאמר: \"המקריב את דם השלמים ואת החלב מבני אהרן לו תהיה שוק הימין למנה\"\u0004 (ויקרא ז, לג), ללמדנו, מי ש\u0003מודה בעבודה\u0004 ומקבלה על עצמו — \u0003יש לו חלק בכהונה,\u0004 מי \u0003שאינו מודה בעבודה\u0004 — \u0003אין לו חלק בכהונה.\u0004","\u0003ואין לי אלא זו בלבד,\u0004 זריקת הדם והקטרת החלב, שהן עבודות הזבח, שאם אינו מודה בהן אין לו חלק בכהונה, \u0003מנין לרבות חמש עשרה עבודות\u0004 אחרות של הכהנים: עבודות המנחה —","\u0003היציקות, והבלילות, והפתיתות, והמליחות, והתנופות, וההגשות, והקמיצות, והקטרות,\u0004 וכן \u0003המליקות\u0004 של העוף, \u0003והקבלות\u0004 של הדם לצורך הזאה, \u0003והזאות\u0004 הדם, \u0003והשקאת סוטה, ועריפת עגלה, וטהרת מצורע, ונשיאות כפים, בין מבפנים\u0004 (במקדש) \u0003בין מבחוץ\u0004 (מחוץ למקדש), \u0003מנין?\u0004","\u0003תלמוד לומר: \"מבני אהרן\",\u0004 ללמדנו כי כל \u0003עבודה המסורה לבני אהרן, כל כהן שאינו מודה בה אין לו חלק בכהונה.\u0004 משמע שאף היציקה המנויה שם היא חובת הכהן, ואינה כשרה בזר!","\u0003אמר רב נחמן, לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003כאן\u0004 מדובר \u0003במנחת כהנים, כאן במנחת ישראל.\u0004 וההבדל הוא כך: \u0003מנחת ישראל\u0004 ש\u0003בת קמיצה היא,\u0004 שצריך לקמוץ ממנה חלק כדי להקטירו — על כך נאמר בכתוב ש\u0003מקמיצה ואילך מצות כהונה\u0004 (כמבואר להלן), ובכך \u0003לימד\u0004 הכתוב \u0003על יציקה ובלילה\u0004 שנעשות לפני קמיצה, \u0003שכשירה בזר.\u0004 אבל \u0003מנחת כהנים דלאו\u0004 \u0005[שאינה]\u0006 \u0003בת קמיצה היא,\u0004 אלא היא קריבה כליל — כבר \u0003מעיקרא בעיא\u0004 \u0005[מתחילה צריכה]\u0006 \u0003כהונה,\u0004 ולכן כל מעשיה פסולים בזר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: מכדי\u0004 \u0005[הואיל]\u0006 ו\u0003מנחת כהנים מהיכא איתרבי\u0004 \u0005[מהיכן נתרבתה]\u0006 שתהיה בה חובת \u0003יציקה? ממנחת ישראל,\u0004 שבה נאמר דין זה במפורש, ואם כן, כדין המלמד כן דין הלמד: \u0003מה התם\u0004 \u0005[שם]\u0006 במנחת ישראל, יציקה \u0003כשירה בזר\u0004 — \u0003אף הכא נמי\u0004 \u0005[כאן גם כן]\u0006 במנחת כהן, יציקה \u0003כשירה בזר!\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 משא ומתן זה בלשון אחרת: \u0003אמר רב נחמן, לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003כאן\u0004 ששנינו במשנתנו שיציקה כשרה בזר — מדובר \u0003ב\u0004מנחות \u0003נקמצות, כאן\u0004 בדברי ר' שמעון, שיציקה היא מעבודת הכהונה — \u0003בשאין נקמצות.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: מכדי\u0004 \u0005[הואיל]\u0006 ומנחות \u0003שאין נקמצות מהיכא איתרבי\u0004 \u0005[מהיכן נתרבו]\u0006 \u0003ל\u0004חובת \u0003יציקה? מ\u0004ה\u0003נקמצות,\u0004 ואם כן צריך להיות דינן \u0003כנקמצות, מה התם\u0004 \u0005[שם]\u0006 \u0003כשירה בזר\u0004 — \u0003אף הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003כשירה בזר! אלא מחוורתא\u0004 \u0005[מחוור,\u0006 ברור הדבר\u0005]\u0006 ש\u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כר' שמעון.\u0004","ושואלים: \u0003מאי טעמא דרבנן\u0004 \u0005[מה טעמם של חכמים]\u0006 שאומרים שיציקה כשרה בזר? ומשיבים, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ויצק עליה שמן ונתן עליה לבונה והביאה אל בני אהרן הכהן וקמץ\"\u0004 (שם ב, א— ב), לומר ש\u0003מקמיצה ואילך מצות כהונה, לימד על יציקה ובלילה\u0004 שקודם קמיצה \u0003שכשירה בזר.\u0004","\u0003ור' שמעון\u0004 מה הוא אומר? לדעתו מה שכתוב \u0003\"בני אהרן\u0004"],["\u0003הכהנים\"\u0004 (ויקרא ב, ב) — \u0003מקרא\u0004 זה \u0003נדרש\u0004 גם \u0003לפניו\u0004 למה שנאמר קודם \"ויצק עליה שמן ונתן עליה לבונה\" (שם א), \u0003ו\u0004גם \u0003לאחריו\u0004 שנאמר \"וקמץ\", שהכל \u0003צריך להיעשות על ידי בני אהרן הכהנים. ושואלים:\u0004","\u0003וסבר\u0004 \u0005[ו\u0006האם \u0005סבור]\u0006 \u0003ר' שמעון\u0004 ש\u0003מקרא נדרש לפניו ולאחריו? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 נאמר \u0003\"ולקח הכהן מדם החטאת באצבעו ונתן על קרנת המזבח\"\u0004 (שם ד, לד), ודרשו חכמים: \u0003\"באצבעו ולקח\"\u0004 — \u0003מלמד שלא תהא קבלה\u0004 של הדם \u0003אלא בימין,\u0004 שהרי כל מקום שהוזכרה אצבע וכהונה הרי זה ימין, \u0003\"באצבעו ונתן\"\u0004 — \u0003מלמד שלא תהא נתינה אלא בימין.\u0004","\u0003אמר ר' שמעון: וכי נאמר יד\u0004 ימין \u0003בקבלה?\u0004 ו\u0003הואיל ולא נאמר יד בקבלה,\u0004 גם אם \u0003קיבל בשמאל\u0004 — \u0003כשר. ו\u0004בפירוש המחלוקת","\u0003אמר אביי: ב\u0004שאלה האם \u0003מקרא נדרש לפניו ולאחריו קא מיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 שחכמים סבורים ש\"אצבעו\" מתייחס גם ל\"ולקח\" שלפניו וגם ל\"ונתן\" שאחריו, \u0003ור' שמעון סבר\u0004 \u0005[סבור]:\u0006 \u0003לאחריו נדרש, ולפניו אין נדרש.\u0004 ואם כן אי אפשר לפרש שטעמו של ר' שמעון הוא מפני שמקרא נדרש גם לפניו!","\u0003אלא היינו טעמא\u0004 \u0005[זהו טעמו]\u0006 של \u0003ר' שמעון:\u0004 נאמר \"ויצק עליה שמן ונתן עליה לבונה \u0003והביאה\u0004 אל בני אהרן הכהנים\" (שם ב, א— ב) — הרי \u0003וי\"ו מוסיף על ענין ראשון,\u0004 לומר שגם הענין הראשון (יציקה) הוא מצות הכהנים.","ושואלים: \u0003ו\u0004האם \u0003סבר\u0004 \u0005[סבור]\u0006 \u0003ר' שמעון\u0004 שדורשים \u0003וי\"ו מוסיף על ענין ראשון? אלא מעתה,\u0004 מה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ושחט את בן הבקר... והקריבו בני אהרן הכהנים את הדם וזרקו את הדם\"\u0004 (שם א, ה), ודייקו חכמים ש\u0003מקבלה\u0004 של הדם (\"והקריבו\") \u0003ואילך מצות כהונה, מלמד על שחיטה\u0004 שהוזכרה מתחילה \u0003ש\u0004היא \u0003כשירה בזר; אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004דעת \u0003ר' שמעון\u0004 אומרים אנו ש\u0003וי\"ו מוסיף על ענין ראשון,\u0004 \u0003שחיטה הכי נמי\u0004 \u0005[כך גם כן]\u0006 \u0003בזר תהא פסולה!\u0004","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 שיש טעם שלא לפרש כך, \u0003דאמר קרא\u0004 \u0005[שאמר הכתוב]\u0006 מתחילה \u0003\"וסמך\u0004 ידו על ראש העולה ונרצה לו לכפר עליו \u0003ושחט\"\u0004 (שם א, ד— ה) להקישם זה לזה: \u0003מה סמיכה בזרים,\u0004 שהרי דווקא הבעלים סומכים את ידיהם על ראש קרבנם — \u0003אף שחיטה בזרים.\u0004","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 אנו סומכים על היקש זה, שמא נאמר גם: \u0003מה סמיכה\u0004 נעשית רק \u0003בבעלים\u0004 עצמם — \u0003אף שחיטה\u0004 תהא רק \u0003בבעלים,\u0004 ולא על ידי אדם אחר! ודוחים: \u0003ההוא לא מצית אמרת\u0004 \u0005[\u0006דבר \u0005זה אינך יכול לומר],\u0006 שהרי \u0003קל וחומר\u0004 הוא: \u0003ומה זריקה\u0004 שהיא \u0003עיקר\u0004 ה\u0003כפרה לא בעיא\u0004 \u0005[צריכה]\u0006 \u0003בעלים,\u0004 אלא הכהנים זורקים \u0003עבורם,\u0004 \u0003שחיטה דלאו\u0004 \u0005[שאינה]\u0006 \u0003עיקר כפרה\u0004 — \u0003לא כל שכן\u0004 שאינה צריכה בעלים דווקא?","\u0003וכי תימא\u0004 \u0005[ואם תאמר],\u0006 \u0003אין דנין אפשר משאי אפשר,\u0004 והרי הבעלים שהם זרים אינם רשאים לזרוק את הדם, אבל שחיטה שכשרה בזר — שמא צריכה שתיעשה בבעלים! על כך יש להשיב: \u0003גלי רחמנא\u0004 \u0005[גילתה התורה]\u0006 \u0003ביום הכפורים,\u0004 שנאמר בכהן הגדול: \u0003\"ושחט את פר החטאת אשר לו\"\u0004 (שם טז, יא), ו\u0003מכלל\u0004 מה שנאמר שם \"אשר לו\", לומר שדווקא הוא כשר לשחוט את פרו, אתה למד ש\u0003שחיטה בעלמא\u0004 \u0005[ב\u0006דרך \u0005כלל]\u0006 \u0003לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 שתיעשה על ידי \u0003בעלים.\u0004","בענין מה ששנינו במשנה שיש מעבודות המנחה שאינן מעכבות, והמנחה כשרה בלעדיהן, מביאים מה ש\u0003אמר רב: כל מקום שנאמר\u0004 בו \u0003\"תורה\" ו\"חוקה\" אינו אלא לעכב,\u0004 שאי אפשר בלעדיה. ואומרים: \u0003קא סלקא דעתין תרתי בעיא\u0004 \u0005[עלה על דעתנו\u0006 לומר \u0005ששני\u0006 \u0003הדברים\u0004 \u0003צריכים],\u0004 גם תורה וגם חוקה, \u0003כדכתיב\u0004 \u0005[כמו שנאמר]\u0006 בפרה אדומה: \u0003\"זאת חקת התורה\"\u0004 (במדבר יט, א).","\u0003(סימן\u0004 לקושיות הבאות \u0003נת\"ץ יקמ\"ל:\u0004 \u0003נ\u0004 זיר, \u0003ת\u0004 ודה, \u0003מ\u0004צורע, \u0003י\u0004 ום הכיפורים, \u0003ק\u0004 רבנות, \u0003מ\u0004נחה, \u0003ל\u0004חם הפנים) ושואלים:","\u0003והרי נזיר דלא כתיבא ביה\u0004 \u0005[שלא כתובה בו]\u0006 \u0003אלא תורה\u0004 בקרבנותיו, שנאמר \"וזאת תהיה תורת הנזיר\" (שם ו, כא), \u0003ואמר רב: תנופה בנזיר מעכבא\u0004 \u0005[מעכבת]!\u0006 ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 \u0003כיון דכתיב\u0004 \u0005[שכתוב\u0006 בו\u0005]:\u0006 \u0003\"כן יעשה\"\u0004 (שם), הדגשה זו \u0003כמאן דכתיבא בהו\u0004 \u0005[כמי שכתובה בו]\u0006 \u0003חוקה דמי\u0004 \u0005[נחשב].\u0006","ושואלים: \u0003הרי\u0004 קרבן \u0003תודה דלא כתיבא ביה\u0004 \u0005[שלא כתובה\u0006 \u0003בו]\u0004 \u0003אלא תורה\u0004 (ויקרא ז, א), \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003ארבעה\u0004 מיני לחם \u0003שבתודה מעכבין זה את זה!\u0004 ודוחים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003תודה דאיתקש\u0004 \u0005[שהוקש]\u0006 \u0003לנזיר, דכתיב\u0004 \u0005[שכתוב]:\u0006 \u0003\"על זבח תודת שלמיו\"\u0004 (שם ו, יג), והרי די היה שייכתב \"על זבח התודה\", \u0003ואמר מר\u0004 \u0005[החכם]:\u0006 \u0003\"שלמיו\"\u0004 בא \u0003לרבות שלמי נזיר,\u0004 ללמד שדינו של זה כדינו של זה.","ושואלים: \u0003והרי מצורע דלא כתיב ביה\u0004 \u0005[שלא כתוב בו]\u0006 \u0003אלא תורה\u0004 (שם יד, ב), \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003ארבעה מינין שבמצורע\u0004 שצריך לטהרתו (עץ ארז, ואזוב, ושני תולדת, וצפרים) \u0003מעכבין זה את זה!\u0004 ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 \u0003כיון דכתיב\u0004 \u0005[שכתוב]:\u0006 \u0003\"זאת תהיה תורת המצרע\",\u0004 ההדגשה \"תהיה\" \u0003כמאן דכתיב ביה\u0004 \u0005[כמו שנכתב בו]\u0006 \u0003חוקה דמי\u0004 \u0005[נחשב].\u0006","ושואלים: \u0003והרי יום הכפורים דלא כתיב ביה\u0004 \u0005[שלא כתוב בו]\u0006 \u0003אלא חוקה\u0004 (שם טז, כט), \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003שני שעירי יום הכפורים מעכבין זה את זה! אלא\u0004 יש לומר שהבנתנו הראשונה לא היתה נכונה, אלא לדברי רב, כל מקום שנאמר \u0003או תורה או חוקה\u0004 הרי זה לעכב.","ושואלים: \u0003והרי\u0004 כל \u0003שאר\u0004 ה\u0003קרבנות דכתיב בהו\u0004 \u0005[שכתוב בהם]\u0006 \u0003תורה,\u0004 שנאמר: \"זאת התורה לעולה למנחה ולחטאת ולאשם ולמלואים ולזבח השלמים\" (שם ז, לז), \u0003ולא מעכבי\u0004 \u0005[ואינם מעכבים]\u0006 הציוויים שנאמרו בהם! ומשיבים: \u0003תורה בעיא\u0004 \u0005[צריכה]\u0006 שיהיה כתוב עמה גם \u0003חוקה, ו\u0004רק \u0003חוקה לא בעיא\u0004 \u0005[צריכה]\u0006 \u0003תורה.\u0004","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"תורה וחוקה\" קא אמר\u0004 \u0005[אומר]\u0006 רב, ומשמע ששניהם צריכים זה לזה! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003אף על גב דכתיב\u0004 \u0005[אף על פי שנכתב]\u0006 \u0003תורה, אי כתיבא\u0004 \u0005[אם כתובה]\u0006 שם גם \u0003חוקה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 הרי זה מעכב, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 כתובה חוקה — \u0003לא,\u0004 אינו מעכב.","ושואלים: \u0003והרי מנחה דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בה חוקה,\u0004 שנאמר: \"כל זכר בבני אהרן יאכלה חק עולם\" (שם ו, יז). \u0003ואמר רב: כל מקום שהחזיר הכתוב בתורת מנחה,\u0004 שנאמר בפרשת המנחה שבפרשת ויקרא (ויקרא פרק ב), וחזר ונאמר בפרשת המנחה שבפרשת צו (שם ו— יא) \u0003אינו אלא לעכב.\u0004 ונדייק מכאן: אם \u0003החזיר\u0004 הכתוב — \u0003אין\u0004 \u0005[כן],\u0006 אם \u0003לא החזיר\u0004 — \u0003לא,\u0004 אף על פי שכתובה שם חוקה!","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 לגבי מנחה, \u0003דכי כתיבא\u0004 \u0005[שכאשר כתובה]\u0006 שם המילה \u0003חוקה\u0004 בפרשת צו — לענין \u0003אכילה כתיבא\u0004 \u0005[היא כתובה],\u0006 ולא לענין עבודות המנחה.","ומקשים: ומה בכך? \u0003והרי לחם הפנים, דכי כתיבא\u0004 \u0005[שכאשר כתובה]\u0006 בו \u0003חוקה\u0004 על ענין ה\u0003אכילה כתיבא\u0004 \u0005[היא כתובה],\u0006 שנאמר: \"ואכלוהו במקום קדוש... חק עולם\" (שם כד, ט), \u0003ותנן\u0004 \u0005[ו\u0006בכל זאת \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003שני סדרים\u0004 של לחם הפנים \u0003מעכבין זה את זה, שני בזיכין\u0004 של לבונה \u0003מעכבין זה את זה, הסדרין והבזיכין מעכבין זה את זה!\u0004","\u0003אלא\u0004 בוודאי ש\u0003כל היכא דכתיבא\u0004 \u0005[כל מקום שכתובה]\u0006 חוקה על \u0003ה\u0004\u0003אכילה\u0004 — \u0003אכולא מילתא כתיבא\u0004 \u0005[על כל הענין היא כתובה],\u0006 לומר שהוא לעכב.","ומה שבמנחה אין אומרים כן (אלא רק במקום שחזר הכתוב) — \u0003שאני התם\u0004 \u0005[שונה\u0006 הדבר \u0005שם],\u0006 \u0003דאמר קרא\u0004 \u0005[ש\u0006כן \u0005אמר המקרא]:\u0006 \u0003\"מגרשה\u0004 (מסלתה) \u0003ומשמנה\"\u0004 (שם ב, טז), ולא \"מגרש ומשמן\", כדי להדגיש שהם מעכבים, ומכאן אתה למד:"],["\u0003גרש ושמן\u0004 הם אלו ש\u0003מעכבין, ואין דבר אחר\u0004 \u0003מעכב,\u0004 למרות שנאמרה שם חוקה.","ודנים \u0003גופא\u0004 \u0005[לגופה]\u0006 של אימרה זו שהבאנו לעיל. \u0003אמר רב: כל מקום שהחזיר לך הכתוב בתורה\u0004 בענין \u0003מנחה,\u0004 שנאמר בפרשה אחת ושוב נאמר בפרשה אחרת \u0003אינו אלא לעכב,\u0004 שאם לא עשה כן הרי זה פסול. \u0003ושמואל אמר:\u0004 רק \u0003גרש\u0004 (סולת) \u0003ושמן\u0004 שחזר עליהם הכתוב \u0003מעכבין, ואין דבר אחר מעכב.\u0004 ותמהים: \u0003ולשמואל,\u0004 כל דבר אחר במנחה, \u0003אף על גב דתנא ביה קרא לא מעכבא ליה\u0004 \u0005[אף על פי ש\u0006חזר ו\u0005שנה בו המקרא אינו מעכב לו]?!\u0006","\u0003אלא\u0004 לדעת הכל \u0003כל היכא דתנא ביה קרא\u0004 \u0005[כל מקום ששנה בו הכתוב]\u0006 \u0003ודאי מעכבא\u0004 \u0005[מעכב],\u0006 \u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004ענין \u0003\"מלא קמצו\" \"בקמצו\" קא מיפלגי\u0004 \u0005[חלוקים הם].\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 נאמר \"וקמץ משם \u0003מלא קמצו\"\u0004 (ויקרא ב, ב), ונאמר במקום אחר: \"והרים ממנו \u0003בקמצו\"\u0004 (שם ו, ח), והשינוי בא להדגיש — דווקא בקומצו \u0003ירים — בידו,\u0004 \u0003שלא יעשה\u0004 כלי \u0003מדה לקומץ\u0004 כדי ליטול על ידו את הקומץ מן המנחה;","\u0003רב סבר\u0004 \u0005[סבור]:\u0006 \u0003הא נמי תנא ביה קרא\u0004 \u0005[\u0006דין \u0005זה גם כן,\u0006 בקומצו ולא בכלי, \u0005שנה בו הכתוב]\u0006 לעכב, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 על אהרן ביום השמיני למילואים: \u0003\"ויקרב את המנחה וימלא כפו ממנה\"\u0004 (שם ט, יז) — כפו ולא בכלי. \u0003ושמואל\u0004 אומר: מחזרה זו אין ללמוד, כי \u0003דורות משעה לא ילפינן\u0004 \u0005[אין אנו למדים],\u0006 שאי אפשר ללמוד את דיני המנחה לדורות מקרבן מנחה שנעשה רק בזמן המילואים\u0005. ושואלים:\u0006","\u0003ו\u0004כי \u0003לא יליף\u0004 \u0005[לומד]\u0006 \u0003שמואל דורות משעה? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003כלי הלח,\u0004 כלומר, כלי שרת שעשויים לקבל בהם משקים, \u0003מקדשין את הלח\u0004 שבתוכם, \u0003ומדת יבש מקדשין את היבש, ואין כלי הלח מקדשין את היבש, ולא מדת יבש מקדשין את הלח.\u0004","\u0003ואמר שמואל: לא שנו\u0004 שאין כלי הלח מקדשים את היבש, \u0003אלא\u0004 ב\u0003מדות\u0004 הלח, \u0003אבל מזרקות\u0004 של דם, אף שהם עשויים לדברים לחים — \u0003מקדשין\u0004 יבש שנכנס בתוכם, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בקרבנות הנשיאים בחנוכת המשכן: \"מזרק אחד כסף... \u0003שניהם מלאים סלת\"\u0004 (במדבר ז, יג). הרי שהוא למד מחנוכת המשכן, שהיא לשעה, לדברים הנוהגים לדורות!","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 \u0003דתנא בה קרא תריסר זימנין\u0004 \u0005[ששנה בו המקרא שתים עשרה פעמים],\u0006 שבכל נשיא ונשיא נאמרה לשון זו, אבל בדרך כלל אין למדים משעה לדורות. ושבים למה שאמר רב, שכל ששנה הכתוב במנחה הרי זה לעכב.","\u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003רב כהנא ורב אסי לרב: והרי הגשה\u0004 של המנחה לקרן המזבח, שנאמר: \"והקריבה אל הכהן והגישה אל המזבח\" (ויקרא ב, ח), \u0003דתנא בה קרא\u0004 \u0005[ששנה בה המקרא],\u0006 \u0003ולא מעכבא\u0004 \u0005[ואינה מעכבת],\u0006 כפי ששנינו במשנתנו! ומסבירים: \u0003מאן תנא ביה\u0004 \u0005[מה,\u0006 היכן \u0005שנה בו]\u0006 המקרא? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"זאת תורת המנחה הקרב אותה בני אהרן לפני ה'\u0004 אל פני המזבח\" (שם ו, ז)!","השיב להם רב: \u0003ההוא\u0004 \u0005[אותו\u0006 פסוק\u0005]\u0006 לא כדי לצוות על ההגשה בא, אלא \u0003לקבוע לה מקום הוא דאתא\u0004 \u0005[שבא],\u0006 להגדיר היכן היו מגישים אותה. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 נאמר \u0003\"לפני ה' \"\u0004(שם) — \u0003יכול\u0004 יגיש \u0003במערב\u0004 המזבח, שהוא הצד הפונה כלפי פתח ההיכל? \u0003תלמוד לומר: \"אל פני המזבח\"\u0004 (שם) — בדרום, שמשם עולים למזבח.","\u0003אי\u0004 \u0005[אם]\u0006 \u0003\"אל פני המזבח\" יכול בדרום,\u0004 שמשם עולים למזבח? \u0003תלמוד לומר: \"לפני ה' \"\u0004— במערב, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 אתה מיישב את שני הדברים יחד? \u0003מגישה בקרן דרומית מערבית כנגד חודה של קרן ודיו.\u0004","\u0003ר' אליעזר אומר,\u0004 כך יש לדרוש את הכתוב: \u0003יכול יגישנה למערבה של קרן או לדרומה של קרן,\u0004 לאיזו שירצה? \u0003אמרת\u0004 (אומר אתה): \u0003כל מקום שאתה מוצא שתי מקראות, אחד מקיים עצמו ומקיים חבירו,\u0004 שאפשר לקיים את שניהם, \u0003ואחד מקיים עצמו ומבטל את חבירו\u0004 — \u0003מניחין את\u0004 המקרא \u0003שמקיים\u0004 את \u0003עצמו ומבטל חבירו\u0004 ואין למדים ממנו, \u0003ותופשין את שמקיים עצמו ומקיים חבירו;\u0004","\u0003שכשאתה אומר \"לפני ה' \" במערב\u0004 — \u0003בטלתה \"אל פני המזבח\"\u0004 שהוא \u0003בדרום, וכשאתה אומר \"אל פני המזבח\"\u0004 שהוא \u0003בדרום\u0004 — \u0003קיימתה \"לפני ה' \".\u0004","ושואלים: \u0003והיכא\u0004 \u0005[והיכן]\u0006 \u0003קיימתה\u0004 \"לפני ה' \" בדרום המזבח? \u0003אמר רב אשי, קסבר האי תנא\u0004 \u0005[סבור תנא זה,\u0006 ר' אליעזר\u0005]:\u0006 \u0003כוליה\u0004 \u0005[כל]\u0006 ה\u0003מזבח בצפון\u0004 העזרה \u0003קאי\u0004 \u0005[היה עומד],\u0006 מאמצעה ולצפון, ונמצא קצהו הדרומי מול פתח ההיכל שבאמצע העזרה, והוא ממש \"לפני ה' \".","ועוד ביחס למה שאמר רב, שכל שהחזיר עליו הכתוב במנחה הריהו מעכב, \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב הונא: הרי מלח\u0004 שצריך לתת על הקומץ המנחה קודם הקרבה, \u0003דלא תנא ביה קרא\u0004 \u0005[שלא שנה בו המקרא]\u0006 \u0003ו\u0004בכל זאת \u0003מעכבא ביה\u0004 \u0005[מעכב בו]!\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"ברית מלח עולם הוא\"\u0004 (במדבר יח, יט) — \u0003שתהא\u0004"],["\u0003ברית אמורה במלח, דברי ר' יהודה,\u0004 לומר שלעולם לא יפסוק המלח מן הקרבנות. \u0003ר' שמעון אומר: נאמר כאן \"ברית מלח עולם הוא\"\u0004 (במדבר יח, יט), \u0003ונאמר להלן\u0004 בפנחס: \u0003\"ברית כהנת עולם\"\u0004 (שם כה, יב), \u0003כשם שאי אפשר לקרבנות בלא כהונה, כך אי אפשר לקרבנות בלא מלח.\u0004 הרי שמלח מעכב בקרבן, למרות שלא שנה בו הכתוב!","\u0003אמר רב יוסף: רב,\u0004 האומר שמה שלא שנה עליו הכתוב אינו מעכב, \u0003כתנא דידן סבירא ליה\u0004 \u0005[כמו התנא\u0006 במשנה \u0005שלנו הוא סבור],\u0006 ש\u0003אמר: לא מלח\u0004 — \u0003כשר. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, מה שנאמר במשנה שאם \u0003לא יצק\u0004 כשר, \u0003נמי\u0004 \u0005[גם כן]\u0006 תפרש: \u0003לא יצק כלל\u0004 כשר? והרי יציקה בוודאי מעכבת, ששנה בה הכתוב! \u0003אלא\u0004 בהכרח אנו מפרשים: \u0003לא יצק כהן אלא זר\u0004 — כשר; ואם כן, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 הכוונה היא: \u0003לא מלח כהן אלא זר\u0004 — כשר, אבל לא מלח כלל — פסול!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: לגבי מליחה אי אפשר לפרש כן, \u0003וכי תעלה על דעתך שזר קרב לגבי מזבח\u0004 למלוח את הקומץ, שהוצרך התנא לומר שהוא כשר? אלא בוודאי כוונתו שלא מלח כלל.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר לדעת רב: \u0003כיון דכתיבא ביה\u0004 \u0005[שכתובה בו]\u0006 במלח, המלה \u0003\"ברית\"\u0004 — \u0003כמאן דתנא ביה קרא דמיא\u0004 \u0005[כמו ששנה בו המקרא נחשב],\u0006 שביטוי זה משמעו חיוב מוחלט, שאי אפשר בלעדיו.","\u0005ועל עיקרה של הקושיה על רב, שואלים:\u0006 \u0003ולא תנא ביה קרא\u0004 \u0005[ו\u0006כי \u0005לא שנה בו המקרא]\u0006 במלח? \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 ציווי נוסף: \u0003\"וכל קרבן מנחתך במלח תמלח\"\u0004 (ויקרא ב, יג)! ומשיבים: הכתוב \u0003ההוא\u0004 אינו נחשב לענין זה, מפני \u0003ש\u0004\u0003מיבעי ליה לכדתניא\u0004 \u0005[נצרך לו\u0006 לדבר אחר, \u0005לכמו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003אילו נאמר\u0004 רק \"וכל \u0003קרבן במלח\u0004 תמלח\", \u0003שומע אני: אפילו עצים ודם שנקראו\u0004 גם הם \u0003קרבן\u0004 צריכים מלח?","על כן \u0003תלמוד לומר: מנחה\u0004 (\"וכל קרבן מנחתך\"), ללמד: \u0003מה מנחה מיוחדת\u0004 שדברים \u0003אחרים באין חובה לה\u0004 לצרכה, שהיא צריכה עצים לצורך הקטרתה — \u0003אף כל שאחרים באין חובה לה\u0004 צריך מליחה, אבל לא עצים עצמם, שאינם זקוקים לעצים, ולא דם שנזרק על קרנות המזבח, ואינו צריך לעצים לשם הקרבתו.","ומציעים, \u0003אי\u0004 \u0005[או]\u0006 נאמר: \u0003מה מנחה מיוחדת שמתרת,\u0004 כלומר, מה קומץ המנחה, שהקטרתו מתירה את השיריים באכילה לכהנים, טעון מלח — \u0003אף כל שמתיר\u0004 טעון מלח, ולפי זה \u0003אביא\u0004 גם \u0003דם ש\u0004גם הוא \u0003מתיר\u0004 את הזבח בהקטרה ובאכילה, שיהא טעון מלח! \u0003תלמוד לומר\u0004 בהמשך הפסוק: \"ולא תשבית מלח ברית \u0003מעל מנחתך\",\u0004 להדגיש ולמעט: \u0003ולא מעל דמך.\u0004","ועוד מדייקים: אם מלשון \"מנחה\" \u0003יכול תהא\u0004 ה\u0003מנחה כולה טעונה מלח,\u0004 ואף השיריים הנאכלים? \u0003תלמוד לומר: \"קרבן\u0004 מנחתך במלח תמלח\", לומר שה\u0003קרבן\u0004 של המנחה, הקומץ הקרב על המזבח, הוא ה\u0003טעון מלח, ואין\u0004 ה\u0003מנחה כולה טעונה מלח.\u0004","\u0003ואין לי אלא קומץ מנחה\u0004 שצריך מלח, \u0003מנין לרבות את הלבונה\u0004 המוקטרת גם היא? וגם אם \u0003מרבה אני את הלבונה, שכן\u0004 היא \u0003באה עמה\u0004 עם קומץ המנחה \u0003בכלי אחד,\u0004 ויש לומר שגם היא בכלל \"קרבן מנחתך\",","\u0003מנין לרבות את הלבונה הבאה בפני עצמה,\u0004 שאדם רשאי לנדב לבונה להקטרה על המזבח, שגם היא טעונה מלח, \u0003ו\u0004כן \u0003לבונה הבאה בבזיכין\u0004 של לחם הפנים, \u0003ו\u0004כן \u0003הקטרת,\u0004 וכן המנחות שאינן נקמצות:","\u0003מנחת כהנים, ומנחת כהן משיח\u0004 שמביא הכהן הגדול בכל יום, \u0003ומנחת נסכים\u0004 שמביאים עם קרבן עולה ושלמים, וכן \u0003אימורי חטאת,\u0004 החלקים שמוקטרים על המזבח, \u0003ואימורי אשם, ואימורי קדשי קדשים\u0004 (כבשי העצרת), \u0003ואימורי קדשים קלים, ואברי עולה, ועולת העוף, מנין\u0004 שכולם צריכים מלח?","\u0003תלמוד לומר: \"על כל קרבנך תקריב מלח\"\u0004 (שם) ומלשון \"כל\" אתה למד שכל הקרב על המזבח טעון מלח. הרי שכתוב זה בענין מלח נדרש לגופו, ולכן אין זה נחשב כ\"שנה עליו הכתוב לעכב\", ואין להקשות מכאן על דברי רב.","ודנים בברייתא שהבאנו. \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003אין לי אלא קומץ מנחה, מנין לרבות את הלבונה?\u0004 וגם אם \u0003מרבה אני את הלבונה שכן באה עמה בכלי אחד,\u0004 מנין לרבות הלבונה הבאה בפני עצמה וכו' והקטורת וכו' — תלמוד לומר \"על כל קרבנך תקריב מלח\". ומקשים: מדוע הוצרכנו לכך? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמרת\u0004 בתחילה: \u0003מה מנחה מיוחדת שאחרים באין חובה לה,\u0004 שהיא טעונה עצים — טעונה מלח, אף כל שאחרים באים חובה לו טעון מלח, וגם לבונה ושאר דברים בכלל זה, שגם הם צריכים עצים כדי להקטירם!","ומשיבים: כאשר התנא שואל \"אין לי אלא קומץ\" וכו' \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 שמא נדרוש את הכתוב \"וכל קרבן מנחתך\" בדרך אחרת, \u0003אימא\u0004 \u0005[אמור]\u0006 כך: \u0003\"קרבן\"\u0004 שנאמר שם — \u0003כלל\u0004 הוא, \u0003ו\"מנחה\"\u0004 — הרי זה \u0003פרט,\u0004 ולפי המידות שהתורה נדרשת בהן, \u0003כלל ופרט\u0004 — \u0003אין בכלל אלא מה שבפרט,\u0004 ואם כן \u0003מנחה\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 צריכה מלח, \u0003מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 — \u0003לא,\u0004 ומנין לרבות לבונה ושאר דברים?","לכך \u0003הדר\u0004 \u0005[חזר]\u0006 הכתוב ו\u0003אמר: \"על כל קרבנך\u0004 תקריב מלח\" — הרי זה \u0003חזר וכלל,\u0004 ואם כן יש לנו כאן \u0003כלל ופרט וכלל,\u0004 ולפי כללי מדרש ההלכה \u0003אי\u0004 (אין) \u0003אתה דן\u0004 ומרחיב את הכלל \u0003אלא כעין הפרט, מה הפרט\u0004 ה\u0003מפורש,\u0004 מנחה, היא דבר \u0003שאחרים באין חובה לה, אף כל שאחרים באין חובה לה\u0004 טעון מלח.","ומסבירים: \u0003אחרים\u0004 ש\u0003באין חובה לה\u0004 למנחה \u0003מאי ניהו\u0004 \u0005[מה הם]\u0006 — \u0003עצים,\u0004 ואם כן \u0003\"אף כל\u0004 שאחרים באים לו חובה\" כוונתו לכל דבר שצריך \u0003עצים\u0004 לשם הקטרה.","ושואלים, \u0003אימא\u0004 \u0005[אמור]\u0006 באופן אחר: \u0003אחרים\u0004 ש\u0003באין חובה לה\u0004 למנחה \u0003ניהו\u0004 \u0005[מה הם]\u0006 — \u0003לבונה\u0004 הבאה עם המנחה, \u0003ו\u0004לדרך זו \u0003אייתי\u0004 \u0005[הבא]\u0006 למד במידת \"כלל ופרט וכלל\" את ה\u0003דם,\u0004 שגם הוא יהיה טעון מליחה, \u0003דאיכא\u0004 \u0005[ש\u0006הרי \u0005יש]\u0006 \u0003נסכים\u0004 שבאים חובה עם הקרבן, שעיקר כפרתו היא הדם! ודוחים: \u0003נסכים\u0004 אינם נחשבים כבאים עם הדם, אלא \u0003בהדי\u0004 \u0005[יחד עם]\u0006 ה\u0003אימורין\u0004 הקרבים על המזבח \u0003הוא דאתו\u0004 \u0005[שהם באים],\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אכילה ושתיה\u0004 של המזבח הם, שעם אכילת הבשר (האימורים) באה שתיית יין (נסכים). ומשיבים: \u0003אדרבה\u0004 \u0005[גדולה מזו,\u0006 להיפך\u0005]\u0006 הנסכים נחשבים כבאים עם הדם, שלאחר \u0003ה\u0004\u0003כפרה\u0004 הנעשית על ידי הדם באה ה\u0003שמחה\u0004 ביין!","\u0003אלא\u0004 אפילו כך, אין ללמוד ממנחה שבאה עמה לבונה, לדם שבאים עמו נסכים, שכן \u0003לבונה באה עמה\u0004 (עם המנחה) \u0003בכלי אחד,\u0004 ואילו נסכים אין באין בכלי אחד עם דם הזבח. \u0003אבל\u0004 אם נפרש שאחרים הבאים חובה למנחה הם עצים, ומכאן למדים לכל שבאים לו עצים חובה — מובן הדבר, שהרי \u0003עצים כי היכי דמתכשרא בהו\u0004 \u0005[כמו שנעשית מוכשרת על ידם]\u0006 ה\u0003מנחה\u0004 — \u0003הכי מתכשרא בהו כולהו\u0004 \u0005[כך\u0006 \u0003מוכשרים בהם כל]\u0004 ה\u0003קרבנות.\u0004","ושואלים, \u0003ואימא\u0004 \u0005[ואמור]\u0006 כך: \u0003מה הפרט מפורש,\u0004 קומץ המנחה, יש בו שני צדדים, גם \u0003שאחרים באין חובה לה ו\u0004גם שהיא \u0003מתרת\u0004 אחרים — \u0003אף כל שאחרים באין חובה לה ו\u0004גם \u0003מתרת\u0004 אחרים טעון מלח, \u0003ומאי ניהו\u0004 \u0005[ומה הוא]\u0006 הדבר שנוסף על ידי כך? \u0003לבונה הבאה בבזיכין,\u0004 שיש בה שני צדדים אלו, שהיא צריכה עצים, וכן \u0003דשריא\u0004 \u0005[ש\u0006היא \u0005מתירה]\u0006 את ה\u0003לחם, אבל מידי אחרינא\u0004 \u0005[\u0006כל \u0005דבר אחר]\u0006 — \u0003לא!\u0004","ומשיבים: \u0003מדאיצטריך\u0004 \u0005[מכיון שהוצרך\u0006 הכתוב\u0005]\u0006 \u0003\"מעל מנחתך\"\u0004 למעט — \u0003ולא מעל דמך,\u0004 שיש לו רק צד אחד של דמיון למנחה, שהוא מתיר כמותה, \u0003מכלל\u0004 הדברים אתה למד \u0003דהנך כולהו אתו בחד צד\u0004 \u0005[ש\u0006\u0003האחרים כולם,\u0004 שנלמדו ממנחה, \u0005באים,\u0006 נלמדים ממנה \u0005בצד אחד]\u0006 של דמיון, שאם בשני צדדים — לא היה צורך כלל למעט דם. וממשיכים לפרש את הברייתא.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003\"מעל מנחתך\" ולא מעל דמך.\u0004 ושואלים: הרי דבר זה אינו מפורש, \u0003ואימא\u0004 \u0005[ואמור]\u0006 כך: \u0003\"מעל מנחתך\" ולא \"מעל איבריך\",\u0004 כלומר, איברי העולה הקרבים על המזבח!","ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 כי \u0003אברים הוה ליה לרבויי\u0004 \u0005[היה\u0006 \u0003לו לרבות]\u0004 שיהיו טעונים מלח, ולא דם, מפני שהם דומים למנחה בכמה צדדים שאין בדם, \u0003שכן (אשב\"נ טמ\"א סימן\u0004 לצדדי הדמיון: \u0003א\u0004חרים, אי\u0003ש\u0004ים, \u0003ב\u0004חוץ, \u0003ט\u0004ומאה, \u0003מ\u0004עילה","\u0003) אחרים באין חובה לה כמותה,\u0004 שגם הם צריכים עצים כדי להקטירם, מה שאין כן הדם; שהם עולים ל\u0003אישים\u0004 (לאש המזבח) \u0003כמותה,\u0004 והדם נזרק על קרנות המזבח; שהם נעשים רק על המזבח \u0003בחוץ כמותה,\u0004 שלא כדם שהוא ניתן גם בתוך ההיכל, כגון בפר ושעיר של יום הכיפורים; וכן שיש בהם איסור אכילת \u0003נותר כמותה;\u0004 שיש בהם איסור אכילה ב","\u0003טומאה כמותה,\u0004 ויש בהם דין \u0003מעילה כמותה,\u0004 מה שאין כן בדם."],["ודוחים: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 \u0003דם הוה ליה לרבויי\u0004 \u0005[היה לו לרבות]\u0006 ולהצריכו מלח, שהוא דומה יותר למנחה, \u0003שכן\u0004 הוא \u0003מתיר כמותה,\u0004 שהדם מתיר את הזבח, כמו הקומץ את השיריים. וכן הוא \u0003נפסל בשקיעת החמה כמותה\u0004 אם לא ניתן עד אז על המזבח, ואילו את איברי העולה ניתן להעלות על המזבח כל הלילה! ומשיבים: \u0003הנך נפישן\u0004 \u0005[אלה מרובים],\u0006 צדדי ההשוואה של מנחה לאיברים מרובים מאשר ההשוואות לדם.","וממשיכים לדון בברייתא. \u0003אמר מר\u0004 \u0005[החכם]\u0006 ממה שנאמר \"וכל קרבן מנחתך במלח תמלח\" (ויקרא ב, יג) \u0003שומע אני אפילו עצים ודם שנקראו קרבן\u0004 צריכים מלח? תלמוד לומר: מנחה (\"מנחתך\"), מה מנחה מיוחדת שאחרים באים לה חובה וכו' יצאו דם ועצים שאין אחרים באים להם חובה, שאינם טעונים מלח. ושואלים: \u0003מאן שמעת ליה דאמר\u0004 \u0005[מי שמעת אותו שאומר]:\u0006 \u0003עצים איקרי\u0004 \u0005[נקראו]\u0006 \u0003קרבן? רבי,\u0004 והרי \u0003ל\u0004דעת \u0003רבי\u0004 אכן \u0003מבעיא בעו\u0004 \u0005[צריכים הם]\u0006 \u0003מלח!\u0004","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \"ונפש כי תקריב \u0003קרבן מנחה\"\u0004 (ויקרא ב, א) — \u0003מלמד שמתנדבין עצים, וכמה\u0004 צריך להביא? \u0003שני גזרין, וכן הוא אומר: \"והגורלות הפלנו על קרבן העצים\"\u0004 (נחמיה י, לה), הרי שמתנדבים עצים כמו שמתנדבים קרבן. \u0003רבי אמר: עצים קרבן\u0004 ממש כמו \u0003מנחה הן, וטעונין מלח, וטעונין הגשה\u0004 לקרן המזבח, כמו מנחה.","\u0003ואמר רבא: לדברי רבי עצים טעונין\u0004 גם \u0003קמיצה,\u0004 כלומר, שלוקח מעט מהם ומקריב לחוד. \u0003ואמר רב פפא: לדברי רבי עצים צריכין עצים,\u0004 כלומר, אם הביא קרבן עצים — צריכים הם להישרף על גבי עצי המערכה, ככל קרבן. הרי שלדעת רבי הסבור שעצים קרויים קרבן — צריכים הם מלח, שלא כברייתא!","ומתרצים: \u0003סמי\u0004 \u0005[מחק]\u0006 \u0003מיכן\u0004 מן הברייתא \u0003עצים,\u0004 שלא נתמעטו מ\"מנחתך\". ושואלים: \u0003ואלא\u0004 לפי זה, \u0003קרא למעוטי מאי\u0004 \u0005[המקרא\u0006 \"מנחתך\" \u0005למעט את מה]\u0006 הוא בא? \u0003אי למעוטי\u0004 \u0005[אם למעט]\u0006 \u0003דם\u0004 הרי דבר זה \u0003מ\"על מנחתך\"\u0004 שבהמשך הפסוק (ויקרא ב, יג) \u0003נפקא\u0004 \u0005[יוצא],\u0006 כפי שנאמר בהמשך הברייתא!"],["ומשיבים: \u0003אפיק\u0004 \u0005[הוצא]\u0006 \u0003עצים\u0004 מנוסח הברייתא, \u0003ועייל\u0004 \u0005[והכנס]\u0006 \u0003נסכים,\u0004 שאינם טעונים מלח, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003אבל היין\u0004 של נסכים, \u0003והדם, והעצים והקטרת אין טעונין מלח.\u0004","ומבררים: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 ברייתא זו? \u0003אי\u0004 \u0005[אם]\u0006 שיטת \u0003רבי\u0004 — \u0003קשיא\u0004 \u0005[קשה]\u0006 מדין \u0003עצים,\u0004 שהרי רבי אמר שהעצים צריכים מלח, \u0003אי רבנן\u0004 \u0005[אם\u0006 כשיטת \u0005חכמים]\u0006 — \u0003קשיא\u0004 \u0005[קשה]\u0006 מדין \u0003קטרת,\u0004 שהרי שנינו בברייתא שהיא טעונה מלח!","ומשיבים: \u0003האי תנא\u0004 \u0005[\u0006שיטת \u0005תנא זה]\u0006 \u0003הוא,\u0004 שהוא דורש את הכתוב באופן אחר. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה אומר:\u0004 נאמר \"וכל קרבן מנחתך במלח תמלח\" (ויקרא ב, יג), \u0003מה הפרט\u0004 ה\u0003מפורש\u0004 (\"מנחתך\") — \u0003דבר שמקבל טומאה, ועולה לאשים\u0004 (על אש המזבח), \u0003וישנו על מזבח החיצון\u0004 — \u0003אף כל דבר המקבל טומאה ועולה לאשים וישנו על מזבח החיצון\u0004 טעון מלח, ולפיכך:","\u0003יצאו עצים\u0004 — \u0003שאין מקבלין טומאה, יצאו דם ויין\u0004 — \u0003שאין עולים לאשים,\u0004 אלא ניתנים על קרן המזבח, \u0003יצאה קטרת\u0004 — \u0003שאינה\u0004 קרבה \u0003על מזבח החיצון,\u0004 אלא על המזבח הפנימי.","ושואלים: \u0003אלא\u0004 לכל הדעות, \u0003טעמא דמעטיה קרא\u0004 \u0005[הטעם,\u0006 דווקא מפני \u0005שמיעט המקרא]\u0006 את ה\u0003דם\u0004 אינו טעון מלח, \u0003הא לאו הכי הוה אמינא\u0004 \u0005[הרי\u0006 אם \u0005לא כך הייתי אומר]:\u0006 \u0003דם ליבעי\u0004 \u0005[צריך]\u0006 \u0003מלח.\u0004 ואולם כיצד ניתן היה לומר כן? והלוא \u0003כיון דמלחיה נפיק ליה\u0004 \u0005[שמלח אותו יצא לו]\u0006 \u0003מתורת דם!\u0004 שהרי מטעם זה \u0003אמר זעירי, אמר ר' חנינא: דם שבישלו\u0004 \u0003אינו עובר עליו\u0004 על אכילתו, מפני שיצא מתורת דם בתורה הראוי להקרבה, \u0003ורב יהודה אמר\u0004 בשם \u0003זעירי: דם שמלחו\u0004 גם כן \u0003אינו עובר עליו\u0004 מטעם זה,","\u0003ורב יהודה דידיה\u0004 \u0005[משלו]\u0006 \u0003אמר\u0004 והוסיף בענין דומה: \u0003אברים\u0004 של עולה \u0003שצלאן\u0004 תחילה \u0003ו\u0004אחר כך \u0003העלן\u0004 על המזבח, \u0003אין בהם משום \"לריח ניחוח\"\u0004 (ראה שמות כט, כה ועוד)!","ומשיבים: על כל פנים הוצרכנו למעט דם ממליחה, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 \u0003מישדא בה\u0004 \u0005[שיזרוק בו]\u0006 \u0003משהו\u0004 מלח \u0003למצוה בעלמא\u0004 \u0005[בלבד],\u0006 שהרי בכך אינו משנה את טבעו של הדם, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 הכתוב שאינו צריך מלח כלל.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של ההלכה שהזכרנו, \u0003אמר זעירי, אמר ר' חנינא: דם שבישלו אינו עובר עליו. יתיב\u0004 \u0005[יושב\u0006 היה\u0005]\u0006 \u0003רבא וקא אמר לה להא שמעתא\u0004 \u0005[ואומר את ההלכה הזו].\u0006 \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 ממה ששנינו בברייתא: \u0003הקפה\u0004 (הקריש) \u0003את הדם ואכלו, או שהמחה\u0004 (המיס) \u0003את החלב\u0004 האסור \u0003וגמעו,\u0004 אף ששינהו ממה שהיה — הרי זה \u0003חייב,\u0004 משמע מזה שדם שנשתנה תורת דם עליו!","אמר לו רבא: \u0003לא קשיא\u0004 \u0005[אין זה קשה],\u0006 \u0003כאן שהקפה באור\u0004 (על ידי אש) שוב אינו נידון כדם, ואינו עובר עליו, \u0003כאן שהקפה\u0004 (הקריש) \u0003בחמה\u0004 עובר עליו. וטעם הדבר: כשמבשל אותו \u0003באור לא הדר\u0004 \u0005[אינו חוזר]\u0006 למצבו המקורי, שנשתנה לגמרי, אבל כשמקפה אותו \u0003בחמה הדר\u0004 \u0005[חוזר הוא]\u0006 ונהיה דם.","הקשה לו אביי: כשהקפה \u0003בחמה נמי\u0004 \u0005[גם כן],\u0006 \u0003לימא\u0004 \u0005[נאמר]:\u0006 \u0003הואיל ואידחי אידחי\u0004 \u0005[הואיל ונדחה\u0006 לזמן מסויים מתורת דם, \u0005יידחה]\u0006 לעולם, \u0003דהא בעא מיניה\u0004 \u0005[שהרי שאל אותו]\u0006 \u0003רבי מני מר' יוחנן: דם שקרש ואכלו, מהו\u0004 לעבור עליו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הואיל ונדחה\u0004 מתורת דם \u0003ידחה! אישתיק\u0004 \u0005[שתק]\u0006 רבא ולא מצא תשובה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003ודאי,\u0004 \u0003כאן\u0004 מדובר \u0003ב\u0004דם \u0003חטאות החיצוניות (החיצונות)\u0004 שדמן ניתן על מזבח העולה, \u0003כאן ב\u0004דם \u0003חטאות הפנימיות\u0004 שדמן ניתן בתוך ההיכל!","\u0003אמר\u0004 לו: \u0003אדכרתן מילתא\u0004 \u0005[הזכרת לי דבר]\u0006 ששמעתי, ש\u0003אמר רב חסדא: דם שקרש בחטאות\u0004 החיצוניות \u0003ואכלו\u0004 — \u0003חייב,\u0004 כי \u0003\"ולקח\u0004 הכהן מדם החטאת \u0003ונתן\"\u0004 (ויקרא ד, כב) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 ודם גם בשעה שהוא קרוש \u0003בר לקיחה ונתינה הוא,\u0004 שניתן לקחת גוש של דם קרוש ולתת אותו על המזבח. אבל אם לקח דם שקרש \u0003בחטאות הפנימיות ואכלו\u0004 — \u0003פטור,\u0004 משום ש\u0003\"וטבל\u0004 הכהן את אצבעו בדם \u0003והזה\"\u0004 (שם ו) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \u0003והאי\u0004 \u0005[וזה]\u0006 דם קרוש \u0003לאו בר\u0004 \u0005[לא בן]\u0006 \u0003טבילה והזאה הוא.\u0004","\u0003ורבא דידיה\u0004 \u0005[משלו]\u0006 \u0003אמר\u0004 סברה אחרת: \u0003אפילו\u0004 דם שקרש \u0003בחטאות הפנימיות ואכלו\u0004 — \u0003חייב, הואיל וכנגדו ראוי\u0004 הדם להקרבה \u0003בחטאות החיצונות. אמר רב פפא: הלכך\u0004 \u0005[משום כך]\u0006 לפי עקרון זה, \u0003דם חמור שקרש ואכלו\u0004 — \u0003חייב\u0004 עליו משום אכילת דם, למרות שדם החמור וודאי אינו ראוי להקרבה, \u0003הואיל וכנגדו\u0004 דם קרוש \u0003ראוי בחטאות החיצונות.\u0004","ועוד בענין דם, \u0003אמר רב גידל, אמר זעירי: דם, בין\u0004 שהוא \u0003לח בין\u0004 שהוא \u0003יבש, חוצץ\u0004 לענין טבילה. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003הדם והדיו, והדבש והחלב,\u0004 אם הם \u0003יבשין\u0004 — \u0003חוצצין,\u0004 אם היו \u0003לחין\u0004 — \u0003אינן חוצצין,\u0004 הרי שדם לח אינו חוצץ! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה],\u0006 \u0003הא דסריך\u0004 \u0005[זה שנדבק]\u0006 מפני שהוא מתחיל להיקרש — חוצץ, \u0003הא דלא סריך\u0004 \u0005[זה שאיננו נדבק]\u0006 אינו נחשב לחציצה.","וחוזרים לדרשת הכתוב \"וכל קרבן מנחתך במלח תמלח\" (ויקרא ב, יג), ושואלים: מה שנאמר \u0003\"תמלח\" למאי אתא\u0004 \u0005[למה בא]?\u0006 ומשיבים, \u0003לכדתניא\u0004 \u0005[לכמו ששנויה\u0006 ברייתא\u0005]:\u0006 \"אילו נאמר רק \"מנחתך \u0003במלח\"\u0004 \u0003יכול תבונהו,\u0004 שיהא כולו מלא במלח? \u0003תלמוד לומר: \"תמלח\"\u0004 (שם). ומצד אחר, \u0003אי\u0004 \u0005[אם]\u0006 היה נאמר רק \u0003\"תמלח\", יכול\u0004 שיצא ידי חובה \u0003במי מלח\u0004 בלבד, ולא במלח ממש? \u0003תלמוד לומר: \"במלח\".\u0004","ועוד, מה שנאמר: \u0003\"ולא תשבית מלח\"\u0004 (שם) מלמד — \u0003הבא מלח שאינה שובתת,\u0004 מלח שמצוי תמיד, \u0003ואיזו? זו מלח סדומית,\u0004 שים המלח פולט בגליו בכל יום. \u0003ומנין שאם לא מצא מלח סדומית, שמביא מלח איסתרוקנית\u0004 שנחצב בידי אדם? \u0003תלמוד לומר\u0004 מיד לאחר מכן: \"על כל קרבנך \u0003תקריב\u0004 מלח\" (שם) להדגיש: \u0003\"תקריב\"\u0004 — \u0003כל\u0004 מלח \u0003שהוא, \"תקריב\"\u0004 — \u0003מכל מקום,\u0004 גם מחוצה לארץ, \u0003\"תקריב\"\u0004 — \u0003ואפילו בשבת, \"תקריב\"\u0004 — \u0003ואפילו בטומאה.\u0004 עד כאן הברייתא.","ומבארים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \"יכול \u0003תבונהו\"\u0004 האמור בברייתא? \u0003אמר רבה בר עולא, הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003יכול יתבוננו,\u0004 יערבו בו מלח הרבה, \u0003כ\u0004מו שמערבים \u0003תבן בטיט. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אי הכי\u0004 \u0005[אם כך],\u0006 מדוע השתמש התנא בלשון \"תבונהו\"? \u0003\"יתבוננו\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 \u0003אלא אמר אביי:\u0004 \"יכול תבונהו\" מובנו — \u0003יכול יעשנו\u0004 יתן עליו מלח \u0003כבנין.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אי הכי\u0004 \u0005[אם כך],\u0006 \"יכול \u0003יבננו\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 \u0003אלא אמר רבא:\u0004 יש להבין את לשון הברייתא כפי שהיא — \u0003יכול תבונהו.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \"יכול \u0003תבונהו\"? אמר רב אשי: יכול יתן בו טעם\u0004 בכולו, \u0003כבינה\u0004 הנותנת טעם באדם כולו? \u0003תלמוד לומר: \"תמלח\"\u0004 שאין בכך צורך, אלא \u0003כיצד הוא עושה? מביא\u0004 את \u0003האבר\u0004 העומד להקרבה \u0003ונותן עליו מלח, וחוזר והופכו ונותן עליו\u0004 שוב \u0003מלח, ומעלהו\u0004 למזבח.","\u0003אמר אביי: וכן לקדירה,\u0004 כשרוצים לבשל בשר וצריך למלוח אותו כדי לספוג ממנו את הדם — די למולחו באופן זה, ולאחר שמדיח את הבשר הריהו ראוי לבישול ואכילה."],["\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מלח שעל גבי האבר\u0004 מאיברי הקרבן שנמלחו — \u0003מועלין בו,\u0004 אבל מלח \u0003שעל גבי הכבש ושבראשו של מזבח\u0004 — \u0003אין מועלין בו. ואמר רב מתנה: מאי קראה\u0004 \u0005[מה המקרא]\u0006 המלמד שמועלים במלח שעל גבי האבר? שנאמר: \u0003\"והקרבתם לפני ה' והשליכו הכהנים עליהם מלח והעלו אותם עלה לה' \"\u0004(יחזקאל מג, כד), לומר שהאבר עם המלח שעליו קרויים עולה, ומועלים גם במלח.","ובענין זה שאין מעילה במלח \u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 תנאי התנו בית דין \u0003על המלח ועל העצים\u0004 של המקדש, \u0003שיהו הכהנים נאותין\u0004 (נהנים, משתמשים) \u0003בהן. אמר שמואל: לא שנו\u0004 שמותר לכהנים ליהנות בהם \u0003אלא לקרבנם, אבל לאכילה\u0004 — \u0003לא.\u0004","ואומרים: \u0003קא סלקא דעתין\u0004 \u0005[עלה על דעתינו]\u0006 לפרש כי \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003לקרבנם\u0004 שאמר שמואל — שמותר להם \u0003למלוח\u0004 את \u0003קרבנם\u0004 שהם מביאים, ומה שאמר שמואל: אבל \u0003לאכול\u0004 לא הותר להם להשתמש במלח — כוונתו לצורך \u0003אכילת\u0004 \u0003קדשים\u0004 המגיעים לחלקם, כגון בשר חטאת ואשם של ישראל. ותמהים: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 כדי \u0003למלוח עורות קדשים\u0004 הניתנים לכהנים \u0003יהבינן\u0004 \u0005[נותנים אנו\u0006 להם\u0005]\u0006 מלח, וכי \u0003ל\u0004צורך \u0003אכילת קדשים לא יהבינן\u0004 \u0005[אין אנו נותנים]\u0006 להם?","ומניין שנותנים להם מלח למליחת העורות — \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003נמצאת אתה אומר, בשלשה מקומות המלח נתונה\u0004 במקדש: \u0003בלשכת המלח, ועל גבי הכבש, ובראשו של מזבח; בלשכת המלח\u0004 — \u0003ששם מולחין עורות קדשים\u0004 הניתנים לכהנים, \u0003על גבי הכבש\u0004 — \u0003ששם מולחים את האברים\u0004 העומדים להקרבה, \u0003בראשו של מזבח\u0004 — \u0003ששם מולחין הקומץ והלבונה, והקטורת, ומנחת כהנים, ומנחת כהן משיח, ומנחת נסכים, ועולת העוף.\u0004 ואם כן, בוודאי רשאים הכהנים ליתן מלח לצורך אכילת הקדשים!","\u0003אלא מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 שהכהנים ניאותים מן המלח \u0003לקרבנם\u0004 — \u0003לאכילת קרבנם,\u0004 כגון בשר חטאת ואשם ושיירי המנחות של ישראל, \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 שנאסר להם \u0003לאכילה\u0004 — כוונתו לצורך \u0003אכילה\u0004 של \u0003חולין.\u0004","ותוהים: \u0003חולין, פשיטא\u0004 \u0005[פשוט]\u0006 הדבר! \u0003מאי בעו התם\u0004 \u0005[מה\u0006 חולין \u0005עושים שם]\u0006 בעזרה? ומשיבים, \u0003אף על גב דאמר מר\u0004 \u0005[אף על פי שאמר החכם]\u0006 בברייתא: נאמר במנחה \"והנותרת ממנה \u0003יאכלו\u0004 אהרן ובניו\" (ויקרא ו, ט) — \u0003שיאכלו עמה\u0004 \u0003חולין ותרומה כדי שתהא נאכלת על השובע,\u0004 ואם כן מכניסים חולין לעזרה, \u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003מלח\u0004 של \u0003קדשים לא יהבינן להו\u0004 \u0005[אין נותנים אנו להם]\u0006 לצורך אותם חולין.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 להבין את המשנה לפי דברי שמואל, שמה שהתנו בית דין שיהיו הכהנים נאותין מן המלח, הוא לצורך אכילת הקדשים. \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 כמו שהובן מתחילה, כי \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 שהותר לכהנים ליהנות מן המלח \u0003לקרבנם\u0004 — \u0003למלוח\u0004 את הקרבנות שהם מקריבים, צריך אתה לדייק מן המשנה כי \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום \u0003דאתני\u0004 \u0005[שהתנה]\u0006 על כך \u0003בית דין\u0004 מותר הדבר, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא אתני\u0004 \u0005[התנה]\u0006 \u0003בית דין לא;\u0004 וכי יכול אתה לומר כן? \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003לישראל יהבינן\u0004 \u0005[נותנים אנו]\u0006 מלח לקרבנם, \u0003לכהנים לא יהבינן\u0004 \u0005[אין אנו נותנים]?\u0006","ומנין שנותנים מלח לקרבנות ישראל — \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003יכול האומר \"הרי עלי מנחה\" יביא מלח מתוך ביתו\u0004 (משלו), כדי ליתן על הקומץ קודם הקטרה, \u0003כדרך שמביא לבונה\u0004 לצורך המנחה \u0003מתוך ביתו? ו\u0004לכאורה \u0003דין הוא: נאמר\u0004 בתורה \u0003הביא מנחה והביא\u0004 עמה \u0003מלח\u0004 (\"וכל קרבן מנחתך במלח תמלח\", ויקרא ב, יג), \u0003ונאמר הביא מנחה והביא\u0004 עמה \u0003לבונה,\u0004 ולפיכך יש לדון (ללמוד) מזה על זה: \u0003מה לבונה\u0004 מביא אדם \u0003מתוך ביתו,\u0004 שנאמר: \"ונתן עליה לבונה, והביאה אל בני אהרן\" (שם א— ב) — \u0003אף מלח\u0004 יביא \u0003מתוך ביתו.\u0004","\u0003או\u0004 שמא \u0003כלך\u0004 (לך) \u0003לדרך זו: נאמר הביא מנחה והביא\u0004 עמה \u0003מלח, ונאמר הביא מנחה והביא עצים,\u0004 שלא ניתן להקטיר על המזבח ללא עצים, \u0003מה עצים\u0004 הם \u0003משל ציבור\u0004 — \u0003אף מלח משל ציבור!\u0004","ונברר: \u0003נראה למי\u0004 מהם המלח \u0003דומה, דנין\u0004 מלח שהוא \u0003דבר הנוהג בכל הזבחים מ\u0004עצים שהם \u0003דבר הנוהג בכל הזבחים, ואל תוכיח לבונה שאינה נוהגת בכל הזבחים,\u0004 אלא במנחות.","ודוחים: \u0003או כלך\u0004 (לך) \u0003לדרך זו\u0004 ותאמר באופן אחר: \u0003דנין\u0004 מלח שהוא \u0003דבר הבא עמה\u0004 עם המנחה \u0003בכלי אחד מ\u0004לבונה שהיא \u0003דבר הבא עמה בכלי אחד, ואל יוכיחו עצים שאינן באין עמה בכלי אחד!\u0004","\u0003תלמוד לומר\u0004 במלח: \u0003\"ברית מלח עולם הוא\"\u0004 (במדבר יח, יט), \u0003ולהלן\u0004 בלחם הפנים \u0003הוא אומר: \"מאת בני ישראל ברית עולם\"\u0004 (ויקרא כד, ח), \u0003מה להלן\u0004 \"מאת בני ישראל\" כוונתו \u0003משל ציבור,\u0004 שלחם הפנים הוא קרבן ציבור, \u0003אף כאן\u0004 \"ברית מלח עולם\" — \u0003משל ציבור.\u0004 ואם לקרבנות ישראל נותנים מלח משל ציבור, בוודאי שנותנים לקרבנות הכהנים. ואם כן, בוודאי לא לשם כך הוצרכו לתנאי בית דין, כפי שסברנו מתחילה, אלא לצורך אכילתם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב מרדכי לרב אשי, הכי קאמר\u0004 \u0005[כך אומר]\u0006 \u0003רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי:\u0004 יש לפרש כי תנאי בית דין היה כפי שסברנו מתחילה, שיאותו הכהנים במלח לקרבנותיהם, ולפירוש זה \u0003לא נצרכא\u0004 המשנה \u0003אלא ל\u0004שיטת \u0003בן בוכרי.\u0004","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003אמר ר' יהודה, העיד בן בוכרי ביבנה: כל כהן ששוקל\u0004 שמביא את מחצית השקל \u0003אינו חוטא,\u0004 למרות שאין הכהנים חייבים במחצית השקל. \u0003אמר לו רבן יוחנן בן זכאי: לא כי\u0004 (כך), \u0003אלא כל כהן שאינו שוקל חוטא\u0004 הוא, \u0003אלא שהכהנים דורשין מקרא זה\u0004 \u0003ל\u0004טובת \u0003עצמן,\u0004 כדי להיפטר ממחצית השקל, שנאמר:","\u0003\"וכל מנחת כהן כליל תהיה לא תאכל\"\u0004 (שם ו, טז), והם טוענים: \u0003הואיל ו\u0004מנחת ה\u0003עומר ושתי הלחם ולחם הפנים שלנו היא,\u0004 כלומר, אם אנו חייבים בשקלים נמצא שאנו שותפים בקרבנות אלו, שהם קרבנות הציבור, ואם כן \u0003היאך\u0004 הם \u0003נאכלין\u0004 על ידינו? ולפי שיטתם העיד בן בוכרי, שלמרות שאינם חייבים במחצית השקל — כהן ששוקל אינו חוטא.","ותחילה מבררים: \u0003ול\u0004דעת \u0003בן בוכרי,\u0004 מדוע כהן ששוקל אינו חוטא? \u0003כיון\u0004 ש\u0003לכתחילה לא מיחייב לאיתויי\u0004 \u0005[אין\u0006 הכהן \u0005חייב להביא]\u0006 מחצית השקל, \u0003כי מייתי נמי\u0004 \u0005[כאשר מביא גם כן]\u0006 באמת \u0003חוטא הוא, דקא מעייל\u0004 \u0005[שהרי הוא מכניס]\u0006 \u0003חולין לעזרה,\u0004 שהרי אינו נותן אותה כחלק מתרומת השקלים המיועדת לקרבנות הציבור, ואין מביאים קרבן ציבור משל היחיד! ומשיבים: מדובר \u0003דמייתי ומסר להון\u0004 \u0005[שמביא ומוסר\u0006 את שקלו \u0005להם]\u0006 \u0003לציבור.\u0004","ועל כל פנים, לשיטת בן בוכרי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר],\u0006"],["\u0003כי זכי להו רחמנא\u0004 \u0005[כאשר זיכתה להם התורה]\u0006 את המלח לצורך קרבנותיהם — הרי זה \u0003לישראל דאית להו\u0004 \u0005[שיש להם]\u0006 \u0003לשכה,\u0004 כלומר, שהם מביאים את שקליהם ללשכה, ומתרומה זו נלקח המלח לצורך הקרבנות, אבל \u0003לכהנים דלית להו\u0004 \u0005[שאין להם]\u0006 \u0003לשכה,\u0004 שאינם חייבים מחצית השקל ללשכה \u0003—\u0004 \u0003לא זכי להו רחמנא\u0004 \u0005[לא זיכתה להם התורה],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[משמיעה לנו]\u0006 המשנה שתנאי בית דין הוא שגם הם ניאותים מן המלח לצורך קרבנותיהם.","\u0005ושואלים:\u0006 \u0003ועצים דפשיטא ליה\u0004 \u0005[שפשוט לו]\u0006 \u0003לתנא\u0004 של הברייתא ש\u0003משל ציבור\u0004 הם, שהוא רוצה ללמוד מהם למלח, \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה? ומשיבים, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003יכול האומר \"הרי עלי עולה\" יביא עצים מתוך ביתו\u0004 (משלו) כדי להקריב עליהם את עולתו, \u0003כדרך שמביא נסכים\u0004 יחד עם העולה \u0003מתוך ביתו\u0004 (ראה במדבר פרק טו)? \u0003תלמוד לומר\u0004 בקרבן העולה: \"וערך אותו הכהן \u0003על העצים אשר על האש אשר על המזבח\"\u0004 (ויקרא א, יב), להקיש עצים למזבח, \u0003מה מזבח משל ציבור\u0004 — \u0003אף עצים ואש משל ציבור,\u0004 אלו \u0003דברי ר' אלעזר בר ר' שמעון.\u0004","\u0003ר' אלעזר בן שמוע אומר: מה מזבח שלא נשתמש בו הדיוט,\u0004 שנבנה מתחילתו כמזבח לה' — \u0003אף עצים ואש\u0004 צריכים להיות כאלה \u0003שלא נשתמש בהן הדיוט\u0004 תחילה. ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 בין שני ההסברים? ומסבירים: \u0003איכא בינייהו חדתי\u0004 \u0005[יש ביניהם\u0006 הבדל לענין עצים \u0005חדשים],\u0006 שלדעת ר' אלעזר בר ר' שמעון די שיהיו העצים משל ציבור, אף אם אינם חדשים, ולדעת ר' אלעזר בן שמוע אינם כשרים אלא אם הם חדשים, שלא נשתמש בהם הדיוט תחילה.","ושואלים: \u0003ועתיקי\u0004 \u0005[ו\u0006עצים \u0005ישנים,\u0006 שנשתמשו בהם\u0003]\u0004 \u0003לא\u0004 כשרים למזבח? \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ויאמר ארונה אל דוד יקח ויעל אדני המלך הטוב בעיניו ראה הבקר לעלה והמרגים וכלי הבקר לעצים\"\u0004 (שמואל ב כד, כב), משמע שאפשר להשתמש לעולה מוריגים וכלי הבקר שכבר נשתמש בהם הדיוט! ומשיבים: \u0003הכא נמי בחדתי\u0004 \u0005[כאן גם כן\u0006 מדובר \u0005בחדשים],\u0006 שעדיין לא נשתמשו בהם.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003מוריגים? אמר עולא: מטה של טרבל.\u0004 ביטוי זה לא היה ידוע בבבל, ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003מטה\u0004 \u0003של טרבל? אמר רב יהודה: עיזא דקורקסא דדשו בה דשתאי\u0004 \u0005[לוח כבד ומשונן\u0006 \u0005שדשים בה הדיישים],\u0006 שהבהמה גוררת אותו על התבואה, וכך מוציאים את הגרעינים מן השיבולים. \u0003אמר רב יוסף: מאי קראה\u0004 \u0005[מהו המקרא]\u0006 המלמד על כך? \u0003\"הנה שמתיך למורג חרוץ חדש בעל פיפיות תדוש הרים\"\u0004 (ישעיהו מא, טו) הרי שמורג יש בו חריצים (\"חרוץ\") ושיניים (\"פיפיות\"), והוא משמש לדישה.","\u0003נתערב קומצה\u0004 של מנחה אחת \u0003בקומץ חבירתה,\u0004 או נתערב \u0003במנחת כהנים,\u0004 או \u0003במנחת כהן משיח,\u0004 או \u0003במנחת נסכים,\u0004 שכל אלה קרבים כליל על המזבח — הרי היא \u0003כשרה,\u0004 ויקטירם כך על המזבח.","\u0003ר' יהודה אומר:\u0004 אם נתערב הקומץ \u0003במנחת כהן משיח,\u0004 או \u0003במנחת נסכים\u0004 — \u0003פסולה,\u0004 לפי \u0003שזו\u0004 המנחה רגילה — \u0003בלילתה עבה,\u0004 לוג שמן לעישרון סולת, \u0003וזו\u0004 מנחת כהן משיח ומנחת נסכים — \u0003בלילתה רכה,\u0004 שיש בהן שלושה לוגים שמן לעישרון של סולת, \u0003ו\u0004כיון שאינן שוות \u0003הן בולעות זו מזו,\u0004 ונמצא שריבה שמנו של קומץ המנחה הרגילה, ומיעט שמנה של מנחת כהן משיח ומנחת נסכים, ודבר זה פוסל.","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במשנה: \u0003דם שנתערב במים, אם יש בו\u0004 בתערובת \u0003מראית דם\u0004 — \u0003כשר,\u0004 ויכול לזרוק אותו על המזבח. אם \u0003נתערב ביין,\u0004 שאז אי אפשר לדעת אם יש בו מראית דם, שהרי גם היין אדום — \u0003רואין\u0004 (אומדים) \u0003אותו\u0004 את היין \u0003כאילו הוא מים,\u0004 ואם בשיעור כזה של מים היתה מראית דם — הרי זה כשר. \u0003נתערב\u0004 דם הקרבן \u0003בדם בהמה\u0004 שאינה קרבן \u0003או בדם חיה\u0004 — \u0003רואין אותו\u0004 את דם הבהמה או החיה \u0003כאילו הוא מים. ר' יהודה אומר: אין דם מבטל דם,\u0004 ולכן יזרוק מדם התערובת, וכשר.","\u0003אמר ר' יוחנן: ושניהם מקרא אחד דרשו,\u0004 בעבודת הכהן הגדול ביום הכיפורים, שלאחר שהיזה מדם הפר ומדם השעיר בנפרד, בין הבדים ועל הפרוכת, צריך לערבם יחד ולתת מן הדם המעורב על מזבח הזהב, וציותה התורה בענין זה: \u0003\"ולקח מדם הפר ומדם השעיר\"\u0004 (ויקרא טז, יח), ומשמעו שגם בשעה שהם מעורבים דם השעיר נחשב לעצמו ואינו בטל. והרי \u0003הדבר ידוע שדמו של פר מרובה מדמו של שעיר,\u0004 ומפני מה לא ייבטל דם השעיר ברוב? \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]:\u0006"],["\u0003מכאן\u0004 למדים \u0003לעולין\u0004 לכל הדברים העולים על המזבח, כמו הדמים הללו, \u0003שאין מבטלין זה את זה,\u0004 שאין המועט בטל במרובה, והוא עומד בעינו. \u0003ור' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003מכאן\u0004 אתה למד \u0003למין במינו\u0004 בכל התורה \u0003שאינו בטל.\u0004 ודנים בהסבר זה של ר' יוחנן למחלוקת.","על מה שאמר ש\u0003רבנן סברי\u0004 \u0005[חכמים סבורים]:\u0006 \u0003מכאן לעולין שאין מבטלין זה את זה,\u0004 שואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 הטעם שדם השעיר אינו בטל בדם הפר \u0003משום\u0004 ש\u0003מין במינו הוא!\u0004","ומשיבים: \u0003אי אשמעינן\u0004 \u0005[אם היה משמיע לנו]\u0006 הכתוב במקרה אחר של \u0003מין במינו\u0004 שאינו בטל, \u0003ולא אשמעינן\u0004 \u0005[ולא היה משמיע לנו]\u0006 במקרה המיוחד הזה של \u0003עולין,\u0004 הייתי אומר \u0003כדקא אמרת\u0004 \u0005[כמו שאתה אומר],\u0006 שמכאן אתה למד למין במינו שאינו בטל. אבל \u0003השתא דאשמעינן\u0004 \u0005[עכשיו שהשמיע לנו]\u0006 הכתוב את ההלכה הזו בדברים ה\u0003עולין\u0004 למזבח, משמע שהטעם הוא \u0003משום\u0004 ש\u0003עולין\u0004 הם, ולא משום שהם מאותו מין.","ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 נלמד מכאן שלעולם המיעוט בטל ברוב \u0003עד דאיכא\u0004 \u0005[שיש]\u0006 תערובת \u0003מין במינו ו\u0004גם שניהם \u0003עולין,\u0004 ורק אז אינם בטלים! ואומרים: אכן \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר.","\u0003ו\u0004כן דנים במה שאמר ר' יוחנן, \u0003ר' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003מכאן\u0004 מכתוב זה למדים \u0003למין במינו שאינו בטל.\u0004 ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 טעמו של הכתוב שאינם בטלים \u0003משום\u0004 ש\u0003עולין הוא!\u0004","ומשיבים: \u0003אי אשמעינן\u0004 \u0005[אם היה משמיע לנו]\u0006 הכתוב דין זה ב\u0003עולין\u0004 שאינם מבטלים זה את זה בתערובת של \u0003מין בשאינו מינו\u0004 — הייתי אומר \u0003כדקאמרת\u0004 \u0005[כמו שאתה אומר],\u0006 אבל \u0003השתא דאשמעינן\u0004 \u0005[עכשיו שהשמיע לנו]\u0006 הכתוב דין זה בדבר שהוא \u0003מין במינו\u0004 (דם בדם), אתה למד כי \u0003משום\u0004 ש\u0003מין במינו הוא.\u0004","ושואלים גם כאן: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 נאמר שלעולם המיעוט בטל ברוב \u0003עד דאיכא\u0004 \u0005[שיש]\u0006 גם תערובת של \u0003מין במינו ו\u0004גם מדובר ב\u0003עולין!\u0004 ואומרים: אכן \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר. ועוד מקשים על הסברו של ר' יוחנן.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005],\u0006 \u0003ר' יהודה אומר:\u0004 אם נתערב הקומץ \u0003במנחת כהנים\u0004 או \u0003במנחת כהן משיח\u0004 או \u0003במנחת נסכים\u0004 — \u0003פסולה, שזו בלילתה עבה וזו בלילתה רכה, והן בולעות זו מזו.\u0004 ויש לשאול: \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003בולעות זו מזו מה הוי\u0004 \u0005[נעשה]?\u0006 מדוע פסולה המנחה? הלוא תערובת \u0003מין במינו הוא,\u0004 ואין שמנה של האחת בטל בשניה, ושתיהן קרבות יחד על המזבח!"],["\u0003אמר רבא, קסבר\u0004 \u0005[סבור]\u0006 \u0003ר' יהודה: כל שהוא\u0004 תערובת של \u0003מין במינו, ו\u0004של \u0003דבר אחר\u0004 שאינו מינו — \u0003סלק את מינו\u0004 כלומר, החשב אותו \u0003כמי שאינו, ו\u0004מה \u0003שאינו מינו רבה עליו ומבטלו,\u0004 וכאן שנתערב השמן המרובה של מנחת הנסכים בקומץ ששמנו מועט — סלק את השמן של הקומץ כמי שאינו, והסולת של הקומץ רבה על השמן של מנחת הנסכים שנבלע בה, ומבטלת אותו.","\u0003איתמר\u0004 \u0005[נאמר],\u0006 נחלקו אמוראים ביחס ל\u0003קומץ\u0004 של \u0003מנחת חוטא\u0004 שאין נותנים בה שמן, \u0003ששמנו\u0004 שנתן עליו שמן, \u0003ר' יוחנן אומר: פסול\u0004 הוא, \u0003וריש לקיש אמר: הוא עצמו,\u0004 כלומר, אף לכתחילה \u0003משכשכו בשירי הלוג\u0004 בשמן שנותר בכלי לאחר שיצקו ממנו על מנחה שטעונה שמן, \u0003ו\u0004כך \u0003מעלהו\u0004 ומקטירו, שלא יהא יבש לגמרי.","ומקשים: כיצד משכשכו בשמן? \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 במנחת חוטא: \u0003\"לא ישים עליה שמן ולא יתן עליה לבונה\"\u0004 (ויקרא ה, יא)! ומשיבים: \u0003ההוא\u0004 \u0005[אותו\u0006 כתוב\u0005]\u0006 משמעו \u0003שלא יקבע לה שמן כחברותיה\u0004 כשאר מנחות, אבל שמן מועט אינו פוסל אותה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 ממה ששנינו בברייתא: \u0003חרב\u0004 (בלא שמן) \u0003שנתערב בבלול\u0004 בשמן — \u0003יקריב, ר' יהודה אומר: לא יקריב. מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה ל\u0003קומץ\u0004 של \u0003מנחת חוטא דאיערב\u0004 \u0005[שהתערב]\u0006 \u0003בקומץ\u0004 של \u0003מנחת נדבה?\u0004 הרי שהשמן פוסל את הקומץ של מנחת החוטא!","ודחה ריש לקיש: \u0003לא,\u0004 הכוונה היא ל\u0003מנחת\u0004 נסכים של \u0003פרים ואילים,\u0004 שיש בה שני לוגים שמן לכל עשרון סולת, שנתערבה \u0003במנחת\u0004 נסכים של \u0003כבשים,\u0004 שיש בה שלושה לוגים לעשרון, והיא חרבה ביחס אליה.","הקשה לו ר' יוחנן: \u0003והא בהדיא קתני לה\u0004 \u0005[והרי\u0006 \u0003במפורש הוא שונה אותה]\u0004 כדין לעצמו: \u0003מנחת פרים ואילים במנחת כבשים, וחרב שנתערב בבלול\u0004 — \u0003יקרב, ר' יהודה אומר: לא יקרב,\u0004 משמע שהם שני מקרים נפרדים! השיב לו: \u0003פירושי קמפרש לה\u0004 \u0005[מפרש הוא לה],\u0006 מדוע אינו מקריב מנחת פרים שנתערבה במנחת כבשים — מפני שהוא חרב שנתערב בבלול.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: קומץ שמיצה שמנו על גבי עצים,\u0004 ואחר כך הניח את הקומץ על העצים להקטירו, \u0003מהו?\u0004 האם נאמר ש\u0003חיבורי עולין כעולין דמו\u0004 \u0005[נחשבים],\u0006 שהשמן הספוג בעצים ומחובר לקומץ נחשב כחלק מן הקומץ, \u0003או לאו כעולין דמו\u0004 \u0005[נחשבים],\u0006 והשמן אינו נחשב כחלק מן הקומץ, והרי זה קומץ שחסר שמנו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: לאו היינו\u0004 \u0005[וכי אין זו]\u0006 מחלוקת של \u0003ר' יוחנן וריש לקיש?\u0004","\u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בבעיה הבאה: \u0003המעלה אבר\u0004 של קרבן \u0003שאין בו\u0004 בבשרו \u0003כזית\u0004 על מזבח מחוץ למקדש, \u0003ועצם\u0004 שעמו \u0003משלימו לכזית\u0004 — \u0003ר' יוחנן אמר: חייב\u0004 משום העלאה זו, \u0003ריש לקיש אמר: פטור;\u0004","\u0003ר' יוחנן אמר חייב,\u0004 משום שלדעתו \u0003חיבורי עולין\u0004 העצם המחוברת לבשר — \u0003כעולין\u0004 כבשר עצמו \u0003דמו\u0004 \u0005[נחשבים],\u0006 ונשלם שיעורו לכזית, \u0003וריש לקיש אמר פטור,\u0004 מפני שלדעתו \u0003חיבורי עולין לאו כעולין דמו\u0004 \u0005[נחשבים],\u0006 ולא נשלם שיעורו לכזית, ואינו חייב על הקטרת העצם כשלעצמה.","השיב לו רב אשי: לא, אין הבעיות דומות, \u0003אלא\u0004 \u0003תיבעי\u0004 \u0005[תישאל]\u0006 השאלה גם \u0003ל\u0004דעת \u0003ר' יוחנן, ותיבעי\u0004 \u0005[ותישאל]\u0006 \u0003ל\u0004דעת \u0003ריש לקיש. תיבעי\u0004 \u0005[תישאל]\u0006 \u0003ל\u0004דעת \u0003ר' יוחנן\u0004 באופן זה: \u0003עד כאן לא קא אמר\u0004 \u0005[\u0006שמענו ש\u0005אומר]\u0006 \u0003ר' יוחנן התם\u0004 \u0005[שם]\u0006 שחייב, \u0003אלא בעצם,\u0004 שהוא מחשיב אותה כחלק מן האבר משום \u0003דמינא\u0004 \u0005[שמין]\u0006 של \u0003בשר הוא, אבל האי\u0004 \u0005[זה]\u0006 השמן \u0003דלאו דמינא\u0004 \u0005[שלא ממין]\u0006 ה\u0003קומץ הוא\u0004 — \u0003לא,\u0004 ויש לומר שמה שהוא מחובר לקומץ אינו עושה אותו כקומץ עצמו.","\u0003או דלמא\u0004 \u0005[שמא]\u0006 להיפך, \u0003אפילו ל\u0004שיטת \u0003ריש לקיש, לא קא אמר\u0004 \u0005[אין הוא אומר]\u0006 שאין העצם נחשבת חלק מן האבר, \u0003אלא בעצם, דבר מפרש הוא\u0004 \u0005[שיכול להיות מופרש לעצמו],\u0006 \u0003ו\u0004הרי \u0003אי פריש\u0004 \u0005[אם פרש]\u0006 ונפל מן המערכה \u0003לאו\u0004 \u0005[אין]\u0006 \u0003מצוה לאהדורי\u0004 \u0005[להחזירו]\u0006 ולהקטירו, \u0003אבל שמן דלאו בר מפרש הוא\u0004 \u0005[שאינו ניתן להפרשה]\u0006 מן הקומץ, שבלעדיו הקומץ חסר — \u0003לא,\u0004 אלא הריהו כקומץ עצמו. \u0003או דלמא לא שנא\u0004 \u0005[שמא אינו שונה].\u0006 והואיל ושאלה זו אינה יכולה להיפתר מתוך חברתה, \u0003נשארה ב\u0004\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003שתי מנחות שלא נקמצו\u0004 עדיין, \u0003ונתערבו זו בזו, אם יכול לקמוץ מזו בפני עצמה ומזו בפני עצמה,\u0004 שיש בכל אחת חלק שלא נתערב, ויכול לקמוץ ממנו — הרי הן \u0003כשירות, ואם לאו\u0004 — \u0003פסולות,\u0004 שהקומץ של כל מנחה צריך לבוא ממנה עצמה.","\u0003קומץ שנתערב במנחה שלא נקמצה\u0004 — \u0003לא יקטיר\u0004 את התערובת, \u0003ואם\u0004 שכח ו\u0003הקטיר\u0004 — \u0003זו שנקמצה עולה לבעלים, וזו שלא נקמצה לא עולה לבעלים.\u0004","\u0003נתערב קומצה\u0004 של מנחה \u0003בשיריה\u0004 (בסולת שנותרה לאחר שנטלו ממנה את הקומץ) \u0003או בשיריה של חבירתה\u0004 — \u0003לא יקטיר\u0004 את התערובת, שאסור להקטיר שיריים, \u0003ואם הקטיר\u0004 — \u0003עולה לבעלים,\u0004 שהרי הקטיר את הקומץ.","\u0003אמר רב חסדא:\u0004 חתיכת בשר \u0003נבילה\u0004 שהיא מטמאת במגע ובמשא, \u0003בטילה\u0004 ברוב כשנתערבה \u0003ב\u0004שתי חתיכות בשר טהורות של בהמה \u0003שחוטה\u0004 כראוי, ואם נגע באחת מן החתיכות שבתערובת — אינו נטמא, וכדין תערובת מין בשאינו מינו. וטעם הדבר שאין דנים על כך כתערובת מין במינו, שאין המיעוט שבה בטל ברוב — מפני \u0003שאי אפשר לשחוטה\u0004 שהיא הרוב \u0003שתעשה נבילה.\u0004","אבל חתיכת בשר \u0003שחוטה אינה בטילה\u0004 ברוב כשנתערבה \u0003ב\u0004חתיכות \u0003נבילה,\u0004 מפני שזו תערובת מין במינו, \u0003ש\u0004הרי \u0003אפשר לנבילה\u0004 שהיא הרוב \u0003שתעשה\u0004 טהורה כ\u0003שחוטה,\u0004 \u0003דלכי מסרחה\u0004 \u0005[ש\u0006הרי \u0005כאשר היא מסריחה,\u0006 מתקלקלת\u0005]\u0006 \u0003פרחה\u0004 \u0005[יוצאת]\u0006 \u0003טומאתה\u0004 ממנה.","\u0003ור' חנינא אמר\u0004 להיפך: \u0003כל שאפשר לו\u0004 למועט \u0003להיות כמוהו\u0004 כמו המרובה — \u0003אינו בטל\u0004 בו, \u0003וכל שאי אפשר לו\u0004 למועט \u0003להיות כמוהו\u0004 כמרובה — \u0003בטל.\u0004 ולכן שחוטה בטילה בנבילה, מפני שאי אפשר לה להיעשות נבילה, אבל נבילה אינה בטילה בשחוטה, מפני שאפשר לה להיעשות טהורה כשחוטה.","ושואלים: \u0003אליבא דמאן\u0004 \u0005[לפי\u0006 שיטתו \u0005של מי]\u0006 נאמרו הדברים? \u0003אי אליבא דרבנן\u0004 \u0005[אם לפי\u0006 שיטתם \u0005של חכמים],\u0006 \u0003הא אמרי\u0004 \u0005[הרי אומרים הם]:\u0006 רק \u0003עולין\u0004 על המזבח שנתערבו \u0003הוא דלא מבטלי אהדדי\u0004 \u0005[שאינם מבטלים זה את זה],\u0006 \u0003אבל\u0004 בסתם כל תערובת \u0003מין במינו,\u0004 וכגון בשר נבילה ובשר שחוטה, ששתיהן מין בשר — \u0003בטל\u0004 המועט במרובה, בין אם נבילה בשחוטה ובין אם שחוטה בנבילה!","\u0003אי אליבא\u0004 \u0005[אם לפי\u0006 שיטתו\u0005]\u0006 של \u0003ר' יהודה,\u0004 שאמר שאין דם קדשים מתבטל בדם חולין מפני שהוא מינו — \u0003והא\u0004 \u0005[והרי]\u0006"],["\u0003ר' יהודה בתר חזותא אזיל\u0004 \u0005[אחר המראה הוא הולך],\u0006 לגבי הגדרת מין במינו, \u0003ו\u0004לפי זה \u0003אידי ואידי\u0004 \u0005[זה וזה],\u0006 בשר שחוטה ובשר נבילה, \u0003מין במינו הוא,\u0004 שהרי מראיהן שווה, ובכל מקרה אין אחת מהן בטלה באחרת!","\u0003אלא\u0004 צריך לומר שהמחלוקת \u0003היא\u0004 \u0003אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003ר' חייא, דתני\u0004 \u0005[ששנה]\u0006 \u0003ר' חייא: נבילה ושחוטה בטילות זו בזו,\u0004 כלומר, אחת מהן בטלה באחרת, שרב חסדא סבור כי דבריו אמורים בנבילה שנתערבה ברוב שחוטה, ור' חנינא סבור שדבריו אמורים בשחוטה שנתערבה ברוב נבילה.","וחוזרים ושואלים: ו\u0003ר' חייא\u0004 עצמו \u0003אליבא דמאן\u0004 \u0005[על פי שיטת מי]\u0006 הוא שונה שרק אחת מהן מבטלת את חבירתה? \u0003אי אליבא דרבנן\u0004 \u0005[אם לפי שיטתם של חכמים]\u0006 — \u0003הא אמרי\u0004 \u0005[הרי אומרים\u0006 הם\u0005]:\u0006 \u0003עולין הוא דלא מבטלי אהדדי\u0004 \u0005[שאינם מבטלים זה את זה],\u0006 \u0003הא\u0004 \u0005[אבל]\u0006 כל תערובת אחרת של \u0003מין במינו בטיל\u0004 \u0005[בטל]!\u0006 \u0003ואי אליבא\u0004 \u0005[ואם לפי שיטתו]\u0006 של \u0003ר' יהודה,\u0004 הלוא \u0003כל מין במינו לר' יהודה לא בטיל\u0004 \u0005[אינו בטל]!\u0006","ומשיבים: \u0003לעולם\u0004 יש לפרש שר' חייא שונה \u0003אליבא\u0004 \u0005[לפי שיטת]\u0006 \u0003ר' יהודה,\u0004 שמין במינו אינו בטל, \u0003ו\u0004לפי דעת ר' חייא, \u0003כי קא אמר\u0004 \u0005[כאשר אומר]\u0006 \u0003ר' יהודה\u0004 ש\u0003מין במינו לא בטל\u0004 — \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 רק \u0003היכא דאפשר ליה למיהוי כוותיה\u0004 \u0005[במקום שאפשר לו שיהיה כמותו],\u0006 \u0003אבל היכא דלא אפשר ליה למיהוי כוותיה\u0004 \u0005[במקום שלא אפשר לו שיהיה כמותו]\u0006 הרי הוא \u0003בטל,\u0004 שאינו נחשב מינו.","\u0003ובהא קא מיפלגי\u0004 \u0005[וב\u0006דבר \u0005זה חלוקים הם],\u0006 ש\u0003רב חסדא סבר\u0004 \u0005[סבור]:\u0006 \u0003בתר\u0004 \u0005[אחר]\u0006 ה\u0003מבטל אזלינן\u0004 \u0005[הולכים אנו],\u0006 שאם אפשר שייעשה הרוב כמו המיעוט, וכגון שחוטה שנתערבה ברוב נבילה, שאפשר לה לנבילה להיות כשחוטה, שלכשתסריח תפקע ממנה טומאתה — הרי זה מין במינו, ואין המיעוט בטל ברוב.","\u0003ור' חנינא סבר\u0004 \u0005[סבור]:\u0006 \u0003בתר\u0004 \u0005[אחר]\u0006 ה\u0003בטל אזלינן\u0004 \u0005[הולכים אנו],\u0006 ורק אם המיעוט יכול להעשות כמו המבטל, וכגון נבילה שנתערבה ברוב שחוטה, הרי זה מין במינו שאינו בטל. ומנסים להביא ראיה.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003שתי מנחות שלא נקמצו ונתערבו זו בזו, אם יכול לקמוץ מזו בפני עצמה ומזו בפני עצמה,\u0004 שלא נתערבו לגמרי — \u0003כשרות, ואם לאו\u0004 — \u0003פסולות. והא הכא\u0004 \u0005[והרי כאן],\u0006 \u0003כיון דקמיץ ליה מחדא\u0004 \u0005[כיון שהוא קומץ מאחת מהן]\u0006 — \u0003אידך הוה ליה\u0004 \u0005[הנותר\u0006 ממנחה זו \u0005הרי הוא נעשה]\u0006 \u0003שירים\u0004 המיועדים לכהנים, \u0003ולא קא מבטלי\u0004 \u0005[ואין מבטלים]\u0006 ה\u0003שירים לטיבלא\u0004 \u0005[את הטבל]\u0006 כלומר, את חלקי המנחה שלא נקמצה, המעורבים בהם.","ונברר: \u0003מני\u0004 \u0005[\u0006שיטת \u0005מי היא]\u0006 משנה זו? \u0003אי רבנן\u0004 \u0005[אם\u0006 שיטת \u0005חכמים]\u0006 — \u0003הא אמרי\u0004 \u0005[הרי אומרים הם]:\u0006 \u0003עולין\u0004 למזבח \u0003הוא דלא מבטלי הדדי\u0004 \u0005[שאינם מבטלים זה את זה],\u0006 \u0003הא\u0004 \u0005[אבל]\u0006 כל תערובת אחרת של \u0003מין במינו,\u0004 כגון שיריים של מנחה אחת במנחה אחרת שהיא טבל, ששניהם סולת בלולה בשמן — \u0003בטל! אלא פשיטא\u0004 \u0005[פשוט]\u0006 הדבר שהיא לשיטת \u0003ר' יהודה,\u0004 ואינו בטל מפני שהוא מין במינו.","ומעתה, \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת ר' חנינא \u0005האומר]:\u0006 \u0003בתר\u0004 \u0005[אחר]\u0006 ה\u0003בטל אזלינן\u0004 \u0005[הולכים אנו],\u0006 במקרה זה ה\u0003בטל הוי\u0004 \u0005[\u0006הרי \u0005הוא]\u0006 יכול להעשות \u0003כמבטל, דלכי קמיץ מאידך\u0004 \u0005[ש\u0006הרי \u0005כאשר יקמוץ מן\u0006 המנחה \u0005האחרת],\u0006 חלקי הטבל המעורבים בשייריה של מנחה זו \u0003הוו להו\u0004 \u0005[הרי הם נעשים]\u0006 \u0003שירים כי הני\u0004 \u0005[כמו אלה],\u0006 ולכן אין הטבל של המנחה האחת בטל ברוב בשיריים של זו.","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת רב חסדא \u0005האומר]:\u0006 \u0003בתר\u0004 \u0005[אחר]\u0006 \u0003מבטל אזלינן\u0004 \u0005[הולכים אנו],\u0006 וכי ה\u0003שירים\u0004 של המנחה הראשונה שנקמצה \u0003מי קא הוו טיבלא\u0004 \u0005[האם הם יכולים\u0006 לחזור ו\u0005להיעשות טבל],\u0006 שתאמר שאין הטבל בטל בהם? ואם כן, \u0003לימא אליבא\u0004 \u0005[נאמר לפי שיטתו]\u0006 של \u0003רב חסדא,\u0004 שמשנתנו היא ש\u0003לא כ\u0004הבנת \u0003ר' חייא\u0004 בשיטתו של ר' יהודה?","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 יש טעם מיוחד לדין המשנה — \u0003כ\u0004דברי \u0003ר' זירא,\u0004 ש\u0003אמר ר' זירא: נאמרה הקטרה בקומץ,\u0004 שמצוה להקטירו, \u0003ונאמרה הקטרה בשירים,\u0004 שנאסר להקטירם,","\u0003מה\u0004 לגבי \u0003הקטרה האמורה בקומץ\u0004 — \u0003אין הקומץ מבטל את חבירו,\u0004 שקומץ שנתערב בקומץ אחר — מקטירם יחד לדעת הכל, \u0003אף הקטרה האמורה בשירים\u0004 — \u0003אין שירים מבטלין את הקומץ,\u0004 והוא הדין שאין שיריים מבטלים שיריים אחרים, ולא את הטבל שיש בו קומץ ושיריים.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו במשנתנו: \u0003הקומץ שנתערב במנחה שלא נקמצה\u0004 — \u0003לא יקטיר, ואם הקטיר\u0004 — \u0003זו שנקמצה עלתה לבעלים, וזו שלא נקמצה לא עלתה לבעלים;\u0004 הרי שיש כאן תערובת מין במינו, \u0003ולא קא מבטיל ליה טיבלא\u0004 \u0005[ואין הטבל מבטל]\u0006 את ה\u0003קומץ,\u0004 שהרי אם הקטיר את התערובת עלתה המנחה לבעלים.","ונברר: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 \u0003אי רבנן\u0004 \u0005[אם\u0006 שיטת \u0005חכמים]\u0006 — \u0003הא אמרי\u0004 \u0005[הרי אומרים\u0006 הם\u0005]:\u0006 \u0003עולין הוא דלא מבטלי הדדי\u0004 \u0005[שאינם מבטלים זה את זה],\u0006 \u0003הא\u0004 \u0005[אבל]\u0006 \u0003מין במינו\u0004 סתם \u0003בטיל\u0004 \u0005[בטל]!\u0006 \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שהוא כדעת \u0003ר' יהודה\u0004 האומר שמין במינו לא בטל.","ומעתה, \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת רב חסדא \u0005האומר]:\u0006 \u0003בתר\u0004 \u0005[אחר]\u0006 ה\u0003מבטל אזלינן\u0004 \u0005[הולכים אנו],\u0006 שאם אפשר שיהיה כבטל הרי זה מין במינו — מובן הדבר, שהרי במקרה זה ה\u0003מבטל,\u0004 המנחה שלא נקמצה, \u0003הוי\u0004 \u0005[הריהי]\u0006 יכולה שתיעשה \u0003כבטל\u0004 כקומץ שנתערב בה, \u0003דכל פורתא חזי למקמץ מיניה\u0004 \u0005[ש\u0006הרי כל מעט מן המנחה ראוי לקמוץ ממנו], לעשותו קומץ של מנחה זו, \u0003ו\u0004כיון שכך \u0003הוי ליה\u0004 \u0005[הריהו]\u0006 \u0003מין ומינו, ומין במינו לא בטל.\u0004","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת ר' חנינא \u0005האומר]:\u0006 \u0003בתר\u0004 \u0005[אחר]\u0006 ה\u0003בטל אזלינן\u0004 \u0005[הולכים אנו],\u0006 \u0003קומץ מי קא הוי טיבלא\u0004 \u0005[האם הוא יכול\u0006 לחזור \u0005ולהיעשות טבל],\u0006 מנחה שלא נקמצה, כדי שייחשב מין במינו שאינו בטל? ואם כן, לשיטתו האם \u0003לימא\u0004 \u0005[נאמר]\u0006 שמשנתנו היא ש\u0003לא כ\u0004הבנת \u0003ר' חייא\u0004 בשיטת ר' יהודה? ומשיבים: \u0003הא נמי\u0004 \u0005[\u0006הלכה \u0005זו גם כן]\u0006 יש לה טעם מיוחד, \u0003כ\u0004דברי \u0003ר' זירא,\u0004 שאמר שגזירת הכתוב היא שאין שיריים מבטלים את הקומץ, והוא הדין שאין טבל שיש בו שיריים מבטל את הקומץ.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו עוד במשנתנו: \u0003נתערב קומצה\u0004 של מנחה אחת \u0003בשירים של חברתה\u0004 — \u0003לא יקטיר, ואם הקטיר\u0004 — \u0003עלתה לבעלים. והא הכא דלא הוי מבטל כבטיל\u0004 \u0005[והרי כאן שאין המבטל\u0006 יכול להיעשות כמו \u0005הבטל],\u0006 שהרי שיריים \u0005אינם יכולים להיעשות קומץ, וגם הבטל אינו יכול להיעשות כמבטל, שהרי קומץ אינו יכול להיעשות שיריים,\u0006 \u0003ולא קא מבטלי ליה\u0004 \u0005[ו\u0006מכל מקום \u0005אין מבטלים]\u0006 ה\u0003שירים\u0004 את ה\u0003קומץ.\u0004","ויש לברר: \u0003מני\u0004 \u0005[\u0006שיטת \u0005מי היא]\u0006 הלכה זו? \u0003אי רבנן\u0004 \u0005[אם\u0006 כדעת \u0005חכמים]\u0006 — הרי הם סבורים שמין במינו בטל! אלא בהכרח שיטת ר' יהודה היא, הסבור שמין במינו אינו בטל, ומכאן עולה שלדעתו דין זה חל בכל מקרה, גם כשהמבטל אינו יכול להיעשות כבטל, וגם כשהבטל אינו יכול להיעשות כמבטל, ושלא כהבנת ר' חייא בדעת ר' יהודה!","בתשובה לכך \u0003אמר ר' זירא:\u0004 יש בענין זה דין מיוחד, שאינו נוגע לדיני תערובת רגילים, שכן \u0003נאמרה הקטרה בקומץ,\u0004 שצריך להקטירו, \u0003ונאמרה הקטרה בשירים,\u0004 שנאסר להקטירם, \u0003מה הקטרה האמורה בקומץ\u0004 — \u0003אין קומץ מבטל את חבירו, אף הקטרה האמורה בשירים\u0004 — \u0003אין שירים מבטלין את הקומץ.\u0004","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו: מצה ש\u0003תיבלה בקצח, בשומשמין, ובכל מיני תבלין\u0004 — \u0003כשרה\u0004 לאוכלה בפסח, שכן \u0003מצה היא אלא שנקראת מצה מתובלת. קא סלקא דעתך\u0004 \u0005[עולה על דעתנו]\u0006 לפרש שמדובר במקרה \u0003דאפיש\u0004 \u0005[שהרבה]\u0006 \u0003לה תבלין טפי\u0004 \u0005[יותר]\u0006 \u0003מ\u0004אשר ה\u0003מצה\u0004 בעצמה.","ומעתה, \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת ר' חנינא \u0005האומר]:\u0006 \u0003בתר\u0004 \u0005[אחר]\u0006 ה\u0003בטל אזלינן\u0004 \u0005[הולכים אנו],\u0006 במקרה זה \u0003בטיל הוי\u0004 \u0005[הבטל הריהו]\u0006 יכול להיעשות \u0003כ\u0004מו ה\u0003מבטל,\u0004 מדוע? \u0003דלכי מעפשא הוי לה\u0004 \u0005[ש\u0006הרי \u0005כאשר\u0006 המצה עצמה \u0005מתעפשת הרי היא]\u0006 \u0003כתבלין,\u0004 שאינו יכול לצאת בה ידי חובת אכילת מצה, ולכן אין המצה בטלה בתבלין, ויוצא בה ידי חובתו. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת רב חסדא \u0005האומר]:\u0006 \u0003בתר\u0004 \u0005[אחר]\u0006 ה\u0003מבטל אזלינן\u0004 \u0005[הולכים אנו],\u0006 מיני \u0003תבלין מי קא הוו\u0004 \u0005[האם הם נעשים]\u0006 \u0003מצה?\u0004","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003דלא אפיש לה\u0004 \u0005[שלא הירבה לה]\u0006 \u0003תבלין,\u0004 אלא \u0003רובה מצה היא, ולא\u0004 \u0005[ו\u0006לכן \u0005אינה]\u0006 \u0003בטלה.\u0004 ומעירים: \u0003דיקא נמי\u0004 \u0005[מדויק גם כן]\u0006 מן הלשון שכן הוא, \u0003דקתני\u0004 \u0005[שהוא שונה]:\u0006 \u0003מצה היא אלא שנקראת מצה מתובלת, שמע מינה\u0004 \u0005[למד מכאן]\u0006 שאכן מדובר שהיתה רובה מצה, ולכן היא נקראת מצה מתובלת.","\u0003מסופר,\u0004 \u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 \u0003רב כהנא\u0004 לארץ ישראל, \u0003אשכחינהו\u0004 \u0005[מצא אותם]\u0006 את \u0003בני רבי חייא דיתבי וקאמרי\u0004 \u0005[שיושבים ואומרים כך]:\u0006 \u0003עשרון\u0004 של מנחה \u0003שחלקו\u0004"],["\u0003והניחו בביסא\u0004 (כלי), ואין חלקיו נוגעים זה בזה, \u0003ונגע טבול יום באחד מהן\u0004 (כלומר אדם שטבל באותו יום מטומאתו, ולא שקעה עליו השמש, שהוא פוסל את הקדשים במגע), \u0003מהו\u0004 הדין? האם נפסל גם חבירו או לא? והצדדים בשאלה: \u0003כי תנן\u0004 \u0005[כאשר שנינו\u0006 במשנה\u0005]\u0006 ש\u0003כלי מצרף\u0004 את \u0003מה שבתוכו לקדש,\u0004 לענין קדשים המצויים בו, שאם נגע טבול יום במקצת נטמא הכל — \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 \u0003היכא דנגעי בהדדי\u0004 \u0005[במקום שנוגעים זה בזה],\u0006 \u0003אבל היכא דלא נגעי בהדדי\u0004 \u0005[במקום שאינם נוגעים זה בזה]\u0006 — \u0003לא,\u0004 והטהור נשאר בטהרתו, \u0003או דילמא לא שנא\u0004 \u0005[שמא אינו שונה]?\u0006","\u0003אמר להו איהו\u0004 \u0005[אמר להם הוא,\u0006 רב כהנא\u0005]:\u0006 \u0003מי תנן\u0004 \u0005[האם שנינו]\u0006 \u0003כלי מחבר\u0004 את מה שבתוכו? \u0003כלי מצרף תנן\u0004 \u0005[שנינו]\u0006 — \u0003כל דהו\u0004 \u0005[כל שהוא],\u0006 בכל אופן, גם בלא מגע. ועוד שאלו בני ר' חייא את רב כהנא: אם \u0003הושיט\u0004 חצי עשרון \u0003אחד\u0004 נוסף \u0003לביניהן\u0004 (בין שני חצאי העשרון שהיו בכלי), ונגע בו טבול יום, \u0003מהו?\u0004 האם נטמאו גם האחרים?","\u0003אמר להו\u0004 \u0005[להם]:\u0006 רק מה ש\u0003צריך\u0004 \u0003לכלי\u0004 — ה\u0003כלי מצרפו,\u0004 וכגון שני חצאי העשרון, שצריכים כלי כדי לקדשם. אבל מה ש\u0003אין צריך לכלי,\u0004 כגון אותו חצי עשרון שהושיט ביניהם — \u0003אין כלי מצרפו.\u0004","ועוד שאלו בני ר' חייא את רב כהנא: אם \u0003הושיט טבול יום את אצבעו ביניהן\u0004 באויר שבין שני חצאי העשרון, ולא נגע באחד מהם, \u0003מהו?\u0004 האם נטמאו? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אין לך דבר שמטמא מאוירו\u0004 את מה שנמצא בו \u0003אלא כלי חרס בלבד.\u0004","\u0003הדר איהו בעא מינייהו\u0004 \u0005[חזר הוא\u0006 רב כהנא \u0005ושאל מהם]\u0006 באותו ענין עצמו: שני חצאי עשרון בכלי אחד ואינם נוגעים זה בזה \u0003מהו לקמוץ מזה על זה?\u0004 כשקומץ מחצי עישרון אחד, האם תעלה הקמיצה גם לחצי האחר? האם נאמר ש\u0003צירוף\u0004 של כלי \u0003דאורייתא\u0004 \u0005[מן התורה\u0006 הוא\u0005],\u0006 ותחשב זו לקמיצה, \u0003או\u0004 שצירוף כלי הוא רק \u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 ואין זו קמיצה, שהרי אין כאן עשרון שלם של מנחה?","\u0003אמרו לו:\u0004 הלכה \u0003זו לא שמענו\u0004 במפורש, אבל \u0003כיוצא בו שמענו, דתנן\u0004 \u0005[ששנינו\u0006 במשנתנו\u0005]:\u0006 \u0003שני מנחות שלא נקמצו\u0004 עדיין \u0003ונתערבו זו בזו, אם יכול לקמוץ מזו בפני עצמה ומזו בפני עצמה,\u0004 שמלבד התערובת נשאר מכל מנחה חלק שאינו מחובר לתערובת, וממנו יכול לקמוץ — \u0003כשירות, ואם לאו\u0004 — \u0003פסולות;\u0004","\u0003כי\u0004 \u0005[כאשר]\u0006 \u0003יכול לקמוץ\u0004 מכל אחת בפני עצמה \u0003מיהא\u0004 \u0005[על כל פנים]\u0006 הן \u0003כשירות,\u0004 ולכאורה, \u0003אמאי\u0004 \u0005[מדוע]\u0006 מועילה הקמיצה? והלוא \u0003הך דמערב הא לא נגע\u0004 \u0005[\u0006חלק \u0005זה שמעורב\u0006 במנחה האחרת \u0005הרי אינו נוגע]\u0006 בחלק שמשם הוא קומץ! אלא מכאן שצירוף הכלי מועיל לקמוץ מזה על זה!","\u0003אמר רבא:\u0004 יש לדחות את הראיה, \u0003דלמא\u0004 \u0005[שמא]\u0006 מדובר כאן \u0003בגושין המחולקין העשויין\u0004 \u0003כמסרק\u0004 כשיניים של המסרק, שאף שהן נפרדות זו מזו הרי הן מחוברות לבסיס. כלומר, חלקי המנחות שלא נתערבו, אף שהם ניכרים לעצמם — נשארו מחוברים לחלק המעורב, וכך יכול לקמוץ מהם על מה שנתערב. אבל אם לא היה כלל חיבור — שמא אין הכלי מצרף לענין קמיצה.","ושואלים: אם כן, כיון שהשאלה לא נפתרה \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה]?\u0006 \u0003אמר רבא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 מה שנאמר \u0003\"והרים ממנו\u0004 בקומצו\" (ויקרא ו, ח) — כוונתו \u0003מן המחובר,\u0004 שהקומץ צריך לבוא מן המנחה עצמה, \u0003שלא יביא עשרון\u0004 מחולק \u0003בשני כלים ויקמוץ\u0004 מאחד מהם על האחר. ונדייק מכאן: דווקא בשני כלים לא יקמוץ, \u0003הא\u0004 \u0005[אבל]\u0006 אם הביא \u0003בכלי אחד דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003שני כלים,\u0004 וכגון שהם שני חצאי עשרון מחולקים בכלי אחד, ואינם נוגעים זה בזה — \u0003קמיץ\u0004 \u0005[קומץ]\u0006 מזה על זה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: דילמא\u0004 \u0005[שמא]\u0006 מה שנאמר שלא יביא עשרון ב\u0003שני כלים היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005מדובר\u0006 שם\u0005]?\u0006 \u0003כגון קפיזא בקבא\u0004 \u0005[\u0006שחוקק \u0005כלי קטן ב\u0006תוך \u0005כלי גדול],\u0006 שיש בכלי שני חללים, ומחיצה (שאינה מגיעה עד שפת הכלי) מפרידה ביניהם, \u0003דאף על גב דעריבי מעילאי\u0004 \u0005[שאף על פי שהם מעורבים מלמעלה],\u0006 מעל גובה המחיצה, \u0003כיון דמיפסק מחיצתא דקפיזא מתתא\u0004 \u0005[שמפסיקה המחיצה של הכלי הקטן מלמטה]\u0006 אינם מצטרפים כאחד.","ולדרך זו, \u0003הא\u0004 \u0005[אבל]\u0006 \u0003כלי אחד דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003שני כלים,\u0004 שהוא מצרף מה שבתוכו, \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005מדובר\u0006\u0005]?\u0006 \u0003כגון עריבתה של תרנגולין,\u0004 שנותנים שם מים או אוכל, והיא מחולקת בחלקה העליון בלבד על ידי מחיצות, \u0003ו\u0004במקרה זה, \u0003אף על גב דמיפסקן מחיצתא הא נגיע\u0004 \u0005[אף על פי שמפסיקות המחיצות הרי הוא נוגע]\u0006 למטה. \u0003אבל הכא\u0004 \u0005[כאן],\u0006 בשני חצאי העשרון המצויים בכלי, \u0003דלא נגיע\u0004 \u0005[שאינו נוגע]\u0006 \u0003כלל,\u0004 עדיין \u0003תיבעי לך\u0004 \u0005[תישאל לך]\u0006 השאלה, האם הכלי מצרף מה שבתוכו לענין קמיצה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה: צירוף כלי\u0004 כלומר, כלי שמצרף שני חצאי עשרון המצויים בו (ואינם נוגעים זה בזה), \u0003ו\u0004יש \u0003חיבור מים\u0004 בין אחד מן החצאים לחצי עשרון אחר הנמצא מחוץ לכלי, ונגע טבול יום בחצי העשרון האחר המצוי בכלי, \u0003מהו?\u0004 האם נטמא גם חצי העשרון שבחוץ?","ומפרטים: \u0003כי תנן\u0004 \u0005[כאשר שנינו\u0006 במשנה\u0005]\u0006 שה\u0003כלי מצרף מה שבתוכו לקדש,\u0004 האם \u0003הני מילי דגואי\u0004 \u0005[דברים אלה\u0006 אמורים \u0005במה ש\u0006נמצא \u0005בפנים],\u0006 \u0003אבל\u0004 לגבי \u0003דבראי\u0004 \u0005[מה שבחוץ]\u0006 — \u0003לא,\u0004 למרות שהוא מחובר למה שבפנים, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003כיון דמחבר מחבר\u0004 \u0005[שהוא מחובר\u0006 לדבר שנטמא, \u0005הריהו\u0006 \u0005מחובר],\u0006 וגם הוא נטמא?","\u0003ואם תימצי\u0004 \u0005[תמצא]\u0006 \u0003לומר: כיון דמחבר מחבר\u0004 \u0005[שהוא מחובר מחובר],\u0006 אם היה מקרה כזה של \u0003חיבור מים וצירוף כלי, ונגע טבול יום\u0004 בחצי עשרון ש\u0003מבחוץ,\u0004 והוא מחובר במים אל אחד החלקים שבפנים, \u0003מהו?\u0004","האם \u0003כי תנן\u0004 \u0005[כאשר שנינו]\u0006 ש\u0003כלי מצרף, הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים במקרה ש\u0003נגע\u0004 בדבר \u0003מגואי\u0004 \u0005[\u0006ש\u0005מבפנים],\u0006 שהצירוף מועיל לטומאה שבתוך הכלי, ומתוך שמצטרף אליו החלק האחר שבפנים — גם המחובר אליו מבחוץ נטמא, \u0003אבל\u0004 כשנגע טבול יום בדבר ש\u0003מבראי\u0004 \u0005[מבחוץ]\u0006 — \u0003לא\u0004 מצרף הכלי את שני החלקים, ורק המחובר במים לחלק שבחוץ נטמא, \u0003או דילמא לא שנא\u0004 \u0005[שמא אינו שונה]?\u0006 שאלות אלה לא נפתרו, ונשארו ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004 מה ששנינו שהכלי מצרף מה שבתוכו לקודש בלא שיגעו זה בזה, הוא כאשר הטמא נוגע באחד מן החלקים, והחלק האחר מצוי באותה שעה בכלי. ואולם \u0003עשרון שחלקו\u0004 בשני כלים, \u0003ונטמא אחד מהן,\u0004 וחזר \u0003והניחו בביסא\u0004 (בכלי) יחד עם האחר שלא נטמא, \u0003וחזר טבול יום ונגע באותו\u0004 חלק \u0003טמא, מהו?\u0004 \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 כבר \u0003שבע לו\u0004 החלק שנטמא מה \u0003טומאה\u0004 הראשונה, ושוב אינו מקבל טומאה, ולכן גם החלק האחר אינו נטמא מחמת צירוף הכלי, \u0003או לא?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ומי אמרינן\u0004 \u0005[והאם אומרים אנו]\u0006 שדבר \u0003שבע ליה\u0004 \u0005[לו]\u0006 \u0003טומאה\u0004 ואינו מקבל עוד טומאה נוספת? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003סדין\u0004 שהיה \u0003טמא\u0004"],["\u0003מדרס\u0004 כגון ששכב עליו הזב, ונטמא טומאה חמורה (שמטמא אדם וכלים), \u0003ו\u0004אחר כך \u0003עשאו וילון\u0004 — הרי זה \u0003טהור מן\u0004 טומאת \u0003המדרס,\u0004 שכבר אינו משמש למושב ומשכב, \u0003אבל טמא מגע מדרס\u0004 (טומאת נוגע במדרס הזב, שמטמא רק אוכלים ומשקים).","\u0003אמר ר' יוסי:\u0004 וכי \u0003באיזה מדרס נגע\u0004 וילון \u0003זה? אלא שאם\u0004 גם \u0003נגע בו הזב\u0004 קודם שעשאו וילון (ולא רק ישב עליו), הרי אף שנטהר מן המדרס כשעשאו וילון — עדיין הוא \u0003טמא מגע הזב,\u0004 שטומאה זו שייכת גם בוילון.","ומדברי ר' יוסי יש ללמוד לענייננו: \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003נגע בו הזב מיהא\u0004 \u0005[על כל פנים]\u0006 הוא \u0003טמא, ואפילו\u0004 נגע בו \u0003לבסוף\u0004 לאחר שישב עליו, \u0003כ\u0004דין דבר שהוא \u0003טמא מדרס ואחר כך\u0004 נטמא ב\u0003מגע הזב.\u0004 ולפי דברי רבא \u0003אמאי\u0004 \u0005[מדוע]\u0006 נטמא? \u0003לימא\u0004 \u0005[שנאמר]:\u0006 כבר \u0003שבע ליה\u0004 \u0005[לו]\u0006 מן ה\u0003טומאה!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא לאביי: \u0003וממאי דהאי\u0004 \u0005[ומנין\u0006 יודע אתה \u0005שזה]\u0006 שאמר ר' יוסי \u0003שאם נגע בו הזב\u0004 נעשה טמא מגע הזב, כוונתו שנגע בו \u0003לבתר\u0004 \u0005[לאחר]\u0006 שנעשה \u0003מדרס?\u0004 \u0003דילמא מקמי\u0004 \u0005[שמא לפני]\u0006 שנעשה \u0003מדרס,\u0004 שתחילה נגע בו זב, ואחר כך ישב עליו, שבאופן זה \u0003הויא\u0004 \u0005[חלה]\u0006 \u0003טומאה חמורה\u0004 של מדרס הזב, שהוא אב הטומאה שמטמא אדם וכלים, \u0003על טומאה קלה\u0004 של מגע הזב, שמטמא רק אוכלים ומשקים.","\u0003אבל הכא\u0004 \u0005[כאן]\u0006 בשאלה שלנו, לענין מנחה שנטמאה במגע טבול יום, וחזר טבול יום ונגע בה, \u0003דאידי ואידי\u0004 \u0005[שזו וזו]\u0006 \u0003טומאה קלה\u0004 היא — \u0003לא\u0004 תחול שוב הטומאה, שכבר שבעה לה מטומאה ראשונה!","\u0003אלא\u0004 יש להביא ראיה שאין אומרים ששבעה לו טומאה, \u0003מסיפא\u0004 \u0005[מסופה]\u0006 של אותה משנה, ששנינו: \u0003מודה ר' יוסי בשני סדינין המקופלין ומונחין זה על זה וישב זב עליהן\u0004 — \u0003שהעליון טמא מדרס, והתחתון טמא\u0004 גם משום \u0003מדרס,\u0004 שהרי כל שתחת הזב נטמא משום מדרס, \u0003ו\u0004גם משום \u0003מגע מדרס,\u0004 שנגע בו הסדין שעליו. \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 טמא התחתון גם טומאת מגע מדרס? \u0003לימא\u0004 \u0005[שנאמר]:\u0006 \u0003שבע ליה\u0004 \u0005[לו]\u0006 \u0003טומאה\u0004 מטומאת מדרס!","ודוחים: אין זו ראיה, \u0003התם\u0004 \u0005[שם]\u0006 מדובר כשנטמא \u0003בבת אחת,\u0004 שהרי טומאת \u0003מדרס ומגע מדרס באות לסדין התחתון בבת אחת. אבל\u0004 \u0003הכא\u0004 \u0005[כאן],\u0006 במנחה שנטמאה, מדובר שהטומאות באו \u0003בזה אחר זה,\u0004 והשאלה איפוא לא נפתרה.","\u0003אמר רבא: עשרון\u0004 של מנחה \u0003שחלקו\u0004 לשנים, \u0003ואבד אחד מהן\u0004 מן החלקים \u0003והפריש אחר תחתיו, ונמצא הראשון\u0004 שאבד, \u0003והרי שלשתן מונחין בביסא\u0004 (בכלי) אחד, אם \u0003נטמא\u0004 החלק שהיה \u0003אבוד\u0004 מתחילה — הרי ה\u0003אבוד ו\u0004ה\u0003ראשון\u0004 שהיה עימו בהפרשה ראשונה \u0003מצטרפין\u0004 לטומאה, כפי ששנינו שהכלי מצרף מה שבתוכו בקודש, אבל ה\u0003מופרש\u0004 תחת האבוד \u0003אין מצטרף\u0004 אליו, שהרי לא הופרש כדי להצטרף עם האבוד, אלא לבוא תחתיו; וכן אם","\u0003נטמא\u0004 החלק ה\u0003מופרש\u0004 תחת האבוד — ה\u0003מופרש ו\u0004ה\u0003ראשון\u0004 שלא אבד \u0003מצטרפין,\u0004 שהרי הופרש כדי להצטרף עמו, אבל ה\u0003אבוד אין מצטרף;\u0004 אבל אם \u0003נטמא\u0004 ה\u0003ראשון\u0004 — \u0003שניהם מצטרפין,\u0004 גם האבוד וגם המופרש, שהרי לכל אחד מהם יש שייכות עמו.","ואילו \u0003אביי אמר: אפילו נטמא\u0004 כל \u0003אחד מהן נמי\u0004 \u0005[גם כן]\u0006 — \u0003שניהם\u0004 שני החלקים האחרים \u0003מצטרפין\u0004 עמו להיפסל, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003כולהו בני ביקתא דהדדי נינהו\u0004 \u0005[כולם בני ביקתה אחת הם],\u0006 שכולם באו מכח אותה מנחה.","\u0003וכן לענין קמיצה,\u0004 לדברי רבא, אם \u0003קמץ מן האבוד\u0004 — \u0003שיריו\u0004 של זה \u0003ו\u0004של ה\u0003ראשון\u0004 שהיה עימו מתחילה \u0003נאכלין,\u0004 אבל ה\u0003מופרש\u0004 תחתיו \u0003אינו נאכל,\u0004 שלא הופרש כדי להצטרף עמו, ואין הקמיצה מן האבוד מתירה אותו באכילה; וכיוצא בזה, \u0003קמץ מן המופרש\u0004 — \u0003שיריו ו\u0004של ה\u0003ראשון\u0004 שלא אבד — \u0003נאכלין,\u0004 ושייריו של ה\u0003אבוד אינו נאכל;\u0004 אבל אם","\u0003קמץ מן\u0004 ה\u0003ראשון\u0004 — \u0003שניהם אינן נאכלין,\u0004 שהרי הקומץ אינו מתיר אלא עשרון, ולא ניתן להכריע איזה משני חצאי העשרון הותר.","ואילו \u0003אביי אמר: אפילו קמץ מאחד מהן\u0004 כל שיהיה — \u0003שניהן\u0004 האחרים \u0003אינן נאכלין, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003כולהו נמי בני ביקתא דהדדי נינהו\u0004 \u0005[כולם בני ביקתה אחת הם],\u0006 מכח אותה מנחה באו, ולא ניתן לדעת איזה משני החלקים הותר על ידי הקומץ.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא: ושירים דידיה\u0004 \u0005[שלו]\u0006 של החלק שממנו הפריש את הקומץ \u0003מיהא\u0004 \u0005[על כל פנים]\u0006 \u0003נאכלין? הא איכא דנקא דקומץ דלא קריב\u0004 \u0005[הרי יש שישית של הקומץ שלא קרב\u0006 עבור שיריים אלו\u0005],\u0006 שהרי הקומץ הופרש על שלושת החצאים שהיו בכלי, ונמצא ששליש ממנו קרב עבור החצי שאינו חלק מן המנחה, וכך נחסרו שני החצאים של המנחה שליש מן הקומץ שצריך ליקרב עבורם, שישית הקומץ לכל אחד, ולא הותר אף אחד מהם באכילה!","ועוד \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב משרשיא: וקומץ גופיה היכי קריב\u0004 \u0005[וקומץ עצמו כיצד קרב]?\u0006 \u0003הא איכא תלתא\u0004 \u0005[הרי יש\u0006 בו \u0005שליש]\u0006 \u0003חולין,\u0004 אותו חלק שנקמץ עבור החלק היתר על המנחה!","\u0003רב אשי אמר:\u0004 אין אלו קושיות, שכן הקדשת ה\u0003קומץ בדעתא\u0004 \u0005[בדעתו]\u0006 של ה\u0003כהן תליא מילתא\u0004 \u0005[תלוי הדבר],\u0006 \u0003ו\u0004ה\u0003כהן כי קמיץ\u0004 \u0005[כאשר הוא קומץ]\u0006 — על \u0003עשרון קא קמיץ\u0004 \u0005[הוא קומץ],\u0006 ולא על החלק הנוסף היתר על עשרון."],["אם לאחר שנטל קומץ מן המנחה \u0003נטמא הקומץ ו\u0004בכל זאת \u0003הקריבו\u0004 — \u0003הציץ\u0004 שעל מצח הכהן הגדול \u0003מרצה\u0004 על כך, והמנחה כשרה ושייריה נאכלים לכהנים. אבל אם \u0003יצא\u0004 הקומץ מחוץ למקומו \u0003ו\u0004אחר כך \u0003הקריבו\u0004 — \u0003אין הציץ מרצה, שהציץ מרצה\u0004 \u0003על הטמא\u0004 שהוקרב, \u0003ואינו מרצה על היוצא.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר בציץ: \"והיה על מצח אהרן \u0003ונשא אהרן את עון הקדשים\u0004 אשר יקדישו בני ישראל... לרצון להם לפני ה' \" (שמות כח, לח), \u0003וכי איזה עון הוא נושא? אם תאמר\u0004 שהוא מרצה על \u0003עון פיגול\u0004 — \u0003הרי כבר נאמר \"לא יחשב\"\u0004 (שם ז, יח)! \u0003אם תאמר\u0004 על \u0003עון נותר\u0004 — \u0003הרי כבר נאמר\u0004 בו \u0003\"לא ירצה\"\u0004 (שם)!","\u0003הא אינו נושא אלא עון טומאה,\u0004 שהקדשים שקרבו בטומאה יעלו לבעליהם לרצון. וטעם לדבר — \u0003ש\u0004הרי טומאה \u0003הותרה מכללה בציבור,\u0004 שאם כל הציבור כולו טמא מקריבים לכתחילה את קרבנות הציבור בטומאה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' זירא:\u0004 \u0003אימא\u0004 \u0005[אמור]\u0006 שהוא מכפר על \u0003עון יוצא\u0004 כלומר, על קדשים שיצאו חוץ לעזרה ונפסלו בכך, \u0003ש\u0004הרי \u0003הותר\u0004 איסור זה \u0003מכללו בבמה\u0004 שהקריבו בה ישראל משנכנסו לארץ (כל זמן שלא היה משכן קבוע), שאין איסור יוצא בבמה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי, אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין ציץ: \u0003\"לרצון להם לפני ה' \"\u0004(שמות כח, לח), ונדייק: \u0003עון\u0004 ש\u0003לפני ה',\u0004 שהותר מכללו בתוך המקדש — \u0003אין\u0004 \u0005[כן]\u0006 הוא מרצה, אבל \u0003עון יוצא\u0004 שאינו \"לפני ה' \" — \u0003לא.\u0004","ועוד \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' אילעא: אימא\u0004 \u0005[אמור]\u0006 שהציץ ירצה על \u0003עון שמאל,\u0004 כלומר, אם עשה את העבודה ביד שמאל ולא בימין, \u0003ש\u0004הרי דבר זה \u0003הותר מכללו ביום הכפורים,\u0004 שהכהן מכניס את כף הקטורת לקדש הקדשים בידו השמאלית!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי, אמר קרא\u0004 \u0005[המקרא]\u0006 בענין ציץ: \"ונשא אהרן את \u0003עון\u0004 הקדשים\" — לומר שמדובר על \u0003עון שהיה בו ודחיתיו,\u0004 שהותר מכללו, \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003יום הכפורים,\u0004 שאין שם עוון שהותר, אלא לכתחילה \u0003הכשירו בשמאל הוא,\u0004 שצריך להשתמש בשתי ידיו, שהיה נוטל את מחתת הגחלים בימינו ואת הכף בשמאלו.","\u0003רב אשי אמר:\u0004 טעם אחר יש לדבר, שנאמר בציץ: \"ונשא את \u0003עון הקדשים\",\u0004 כלומר, פסול שיש בקרבן עצמו, \u0003ולא\u0004 את \u0003עון המקדישין,\u0004 כלומר, המקריבים. ואילו עבודה בשמאל אינה פסול בקודש עצמו, אלא בכהן שעושה את העבודה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב סימא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי לרב אשי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב סימא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אשי\u0004 עצמו \u0003לרב אשי: ואימא\u0004 \u0005[ואמור]\u0006 שירצה הציץ על \u0003עון בעל מום\u0004 שהוקרב, \u0003ש\u0004הרי \u0003הותר מכללו בעופות,\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 מצות \u0003תמות,\u0004 שיהיה הקרבן תמים, \u0003ו\u0004מצות \u0003זכרות,\u0004 שיהא זכר — דווקא \u0003בבהמה\u0004 נאמר, \u0003ואין\u0004 דין \u0003תמות וזכרות בעופות!\u0004","\u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003עליך\u0004 על שאלתך \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 בענין בעל מום: \u0003\"לא ירצה\"\u0004 (ויקרא כב, כג), \u0003\"כי לא לרצון יהיה לכם\"\u0004 (שם כ), לומר שבעלי מומים אינם עולים לרצון כלל, גם לא על ידי ציץ.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003דם\u0004 קדשים \u0003שנטמא וזרקו\u0004 על המזבח, אם עשה כן \u0003בשוגג\u0004 — \u0003הורצה,\u0004 אם עשה כן \u0003במזיד\u0004 — \u0003לא הורצה. במה דברים אמורים? ב\u0004קרבן \u0003יחיד, אבל בציבור, בין בשוגג בין במזיד\u0004 — \u0003הורצה. ובגוי\u0004 שהביא קרבן, ונטמא דמו וזרקוהו, \u0003בין בשוגג בין במזיד, בין באונס בין ברצון\u0004 —"],["\u0003לא הורצה,\u0004 שהרי נאמר בציץ: \"לרצון להם\" (שמות כח, לח), לישראל ולא לאחרים.","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא אחרת: \u0003על מה הציץ מרצה? על הדם ועל הבשר ועל החלב שנטמא, בין בשוגג בין במזיד, בין באונס בין ברצון, בין ביחיד בין בציבור,\u0004 ושלא כמו ששנינו, שביחיד אינו מרצה על המזיד!","\u0003אמר רב יוסף, לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 ששנינו בה שמרצה על הדם גם במזיד — היא כשיטת \u0003ר' יוסי, הא\u0004 \u0005[זו]\u0006 ששנינו בה שאינו מרצה, היא כשיטת \u0003רבנן\u0004 \u0005[חכמים].\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003אין תורמין\u0004 תרומה \u0003מן הטמא על הטהור, ואם תרם,\u0004 אם היה זה \u0003בשוגג\u0004 — \u0003תרומתו תרומה,\u0004 \u0003במזיד\u0004 — \u0003אין תרומתו תרומה,\u0004 שקנס הוא שקנסוהו חכמים. \u0003ר' יוסי אומר: בין\u0004 אם תרם מן הטמא \u0003בשוגג בין במזיד\u0004 — \u0003תרומתו תרומה.\u0004 הרי שר' יוסי אינו מחלק בין אם עשה בשוגג או במזיד, וכשיטת הברייתא השניה.","ומקשים: \u0003אימר דשמעת ליה\u0004 \u0005[אמור ששמעת אותו]\u0006 את \u0003ר' יוסי דלא קניס\u0004 \u0005[שאינו קונס]\u0006 את העושה במזיד, ואולם מה ששנינו בברייתא זו \u0003ש\u0004\u0003מרצה ציץ על אכילות,\u0004 כגון על בשר שנטמא, שייחשב כטהור, \u0003מי שמעת ליה\u0004 \u0005[האם שמעת אותו]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: הציץ מרצה על אכילות,\u0004 כלומר, גם על דברים הנאכלים שנטמאו, \u0003ר' יוסי אומר: אין הציץ מרצה על אכילות!\u0004","ומשיבים: \u0003איפוך\u0004 \u0005[הפוך]\u0006 את השיטות בברייתא זו, \u0003ר' אליעזר אומר: אין הציץ מרצה על אכילות, ר' יוסי אומר: הציץ מרצה על אכילות.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב ששת: ומי מצית אפכת לה\u0004 \u0005[והאם יכול אתה להפוך אותה]\u0006 ולומר כי לדעת ר' אליעזר הציץ אינו מרצה על האכילות? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003יכול\u0004 נאמר ש\u0003בשר\u0004 קרבן \u0003שנטמא,\u0004 כלומר, שאכלוהו טמאים \u0003לפני זריקת דמים\u0004 על המזבח, \u0003יהו חייבין עליהן\u0004 על אכילה זו כרת \u0003משום\u0004 אכילת קדשים ב\u0003טומאה?\u0004","\u0003תלמוד לומר: \"כל טהור יאכל בשר\"\u0004 (ויקרא ז, יט), ומיד אחר כך נאמר: \u0003\"והנפש אשר תאכל בשר מזבח השלמים אשר לה' וטמאתו עליו ונכרתה\"\u0004 (שם כ), ללמדנו ש\u0003הניתר לטהורין\u0004 הוא ש\u0003חייבין עליו משום\u0004 אכילה ב\u0003טומאה,\u0004","\u0003ושאינו ניתר לטהורין אין חייבין עליו משום טומאה,\u0004 והואיל ואין בשר מותר באכילה קודם זריקת הדם — אין חייבים על אכילתו בטומאה.","ויש לשאול: \u0003או אינו\u0004 כן, \u0003אלא\u0004 יש לדייק מכתוב זה באופן אחר: ה\u0003נאכל\u0004 בפועל \u0003לטהורין\u0004 — \u0003חייבין עליו משום טומאה, ושאינו נאכל\u0004 \u0003לטהורין\u0004 — \u0003אין חייבין עליו\u0004 על אכילתו \u0003משום טומאה,\u0004 למרות שכבר נזרק עליו הדם, ובכך \u0003אוציא אני את הלן\u0004 שעבר זמן אכילתו, \u0003ואת היוצא\u0004 מחוץ למקום אכילתו, \u0003ש\u0004נפסלו ושוב \u0003אינן נאכלין לטהורים,\u0004 שאין לחייב את האוכלם בטומאה?","\u0003תלמוד לומר: \"אשר לה'\"\u0004— \u0003ריבה\u0004 גם את אלה, שחייבים על אכילתם בטומאה.","\u0003יכול שאני מרבה\u0004 בכלל זה גם \u0003את הפיגולין\u0004 שנפסלו במחשבת חוץ לזמנו \u0003ואת הנותרות?\u0004","ולפני שמגיעים לסיום הענין מקשים: \u0003נותרות היינו\u0004 \u0005[הרי זה]\u0006 בדיוק \u0003לן,\u0004 שכבר הזכרנו שחייבים על אכילתו בטומאה! \u0003אלא\u0004 כך צריך לגרוס: יכול שאני מרבה \u0003אף הפיגולין,\u0004 שיהא דינם \u0003כנותרות? תלמוד לומר: \"מזבח השלמים\"\u0004 — \u0003מיעט,\u0004 שהמ' של \"מזבח\" באה למעט, שאין חייבים על אכילת הפיגול משום טומאה.","ושואלים: \u0003ומה ראית לרבות את אלו\u0004 הנותר והיוצא, \u0003ולהוציא את אלו\u0004 הפיגולים? ומשיבים: \u0003אחר שריבה הכתוב ומיעט, אמרת\u0004 (אומר אתה): \u0003מרבה אני את אלו\u0004 הנותר והיוצא, \u0003שהיתה להן שעת הכושר,\u0004 שהיו ראויים לאכילה משנזרק דם הזבח, ורק אחר כך נותר הבשר או יצא, \u0003ומוציא אני את אלו\u0004 את הפיגולים, \u0003שלא היתה להן שעת הכושר,\u0004 שמשעה שנזרק דמם כבר היו פסולים.","\u0003ואם תאמר:\u0004 אם כן, \u0003בשר שנטמא לפני זריקת דמים ואכלו\u0004 הטמא \u0003לאחר זריקת דמים, מפני מה חייבין עליו משום טומאה?\u0004 והרי לא היתה לו שעת הכושר! על כך יש להשיב: \u0003מפני שהציץ מרצה\u0004 על הטמא, שתועיל לו זריקת הדם, אף על פי שאינו נאכל.","על כל פנים מברייתא זו עולה כי בשר \u0003ש\u0004\u0003נטמא\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 הציץ מרצה עליו, \u0003יוצא\u0004 — \u0003לא\u0004 מרצה עליו הציץ, ולכן לא היתה לו שעת הכושר;","\u0003מאן שמעת ליה דאמר\u0004 \u0005[מי\u0006 הוא ש\u0005שמעת אותו שאומר]:\u0006 \u0003אין זריקה מועלת ליוצא?\u0004 הלוא \u0003ר' אליעזר\u0004 הוא, כפי שלמדנו במקום אחר (מעילה ו,ב), ואם כן ברייתא זו היא בהכרח כשיטתו, \u0003וקתני\u0004 \u0005[והוא שונה]\u0006 כאן ש\u0003מרצה ציץ על אכילות.\u0004 ואם כן לא ניתן להפוך את השיטות בברייתא שהובאה לעיל, כפי שהצענו!","\u0003אלא אמר רב חסדא, לא קשיא\u0004 \u0005[אינו קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 הברייתא ששנינו בה שהציץ מרצה על היחיד גם במזיד — כשיטת \u0003ר' אליעזר\u0004 היא, הסבור שציץ מרצה על האכילות, \u0003הא\u0004 \u0005[זו]\u0006 ששנינו בה שאינו מרצה — היא כשיטת \u0003רבנן\u0004 \u0005[\u0006שאר \u0005חכמים]\u0006 האומרים שאינו מרצה על האכילות.","ומקשים: \u0003אימר דשמעת ליה\u0004 \u0005[אמור ששמעת אותו]\u0006 את \u0003ר' אליעזר\u0004 שהוא אומר ש\u0003מרצה\u0004 ה\u0003ציץ על אכילות, דלא קניס מי שמעת ליה\u0004 \u0005[שאיננו קונס\u0006 אדם שעשה במזיד \u0005האם שמעת אותו]?\u0006 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003כי היכי דשמעת ליה\u0004 \u0005[כמו ששמעת אותו]\u0006 את \u0003ר' יוסי\u0004 בענין תרומה, שאינו קונס את התורם במזיד מן הטמא על הטהור, כך \u0003שמעת ליה\u0004 \u0005[שמעת אותו]\u0006 את \u0003ר' אליעזר, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: בין בשוגג בין במזיד\u0004 — \u0003תרומתו תרומה.\u0004","ומקשים: \u0003אימר דשמעת ליה\u0004 \u0005[אמור ששמעת אותו]\u0006 את \u0003ר' אליעזר\u0004 שהוא אומר שאין קונסים במזיד — \u0003בתרומה דקילא\u0004 \u0005[שהיא קלה],\u0006 \u0003בקדשים דחמירי מי שמעת ליה\u0004 \u0005[שהם חמורים האם שמעת אותו]?\u0006 ומשיבים: על כרחך צריך אתה לומר כך, ש\u0003אם כן,\u0004 אם אין אתה אומר כך, \u0003הא אמאן תרמייה\u0004 \u0005[\u0006ברייתא \u0005זו על מי תזרוק]?\u0006 כלומר, למי תשייך אותה?","\u0003רבינא אמר,\u0004 יש לתרץ את הסתירה בין הברייתות באופן אחר: לענין \u0003טומאתו, בין\u0004 שנטמא הדם \u0003בשוגג בין\u0004 שנטמא \u0003במזיד\u0004 — \u0003הורצה,\u0004 כדברי הברייתא השניה. לענין \u0003זריקתו,\u0004 אם לאחר שנטמא (בין בשוגג בין במזיד) זרק אותו \u0003בשוגג\u0004 — \u0003הורצה, במזיד\u0004 — \u0003לא הורצה,\u0004 כדברי הברייתא הראשונה.","\u0003ורב שילא אמר\u0004 להיפך: לענין \u0003זריקתו, בין\u0004 שזרקו \u0003בשוגג בין במזיד\u0004 — \u0003הורצה.\u0004 לענין \u0003טומאתו,\u0004 רק אם נטמא \u0003בשוגג\u0004 — \u0003הורצה,\u0004 אבל אם נטמא \u0003במזיד\u0004 — \u0003לא הורצה.\u0004","ומעירים: \u0003ולרב שילא, הא דקתני\u0004 \u0005[\u0006ברייתא \u0005זו,\u0006 השניה, \u0005שהוא שונה]\u0006 בה: הציץ מרצה על הדם \u0003שנטמא בין בשוגג בין במזיד\u0004 — \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003נטמא\u0004 הדם \u0003בשוגג, וזרקו, בין\u0004 שזרקו \u0003בשוגג בין\u0004 שזרקו \u0003במזיד\u0004 — הציץ מרצה."]]};
